package receipt_test

import (
	"encoding/json"
	"reflect"
	"strings"
	"testing"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/receipt"
	"github.com/gitdek/invariant/internal/verify"
)

// The JSON boundary keeps these acceptance tests independent of the concrete
// Go fields used to carry application dependency evidence into a receipt.
func pythonDependenciesAcceptDocument() map[string]any {
	return map[string]any{
		"project":   "python application dependencies",
		"passed":    true,
		"assurance": "tested against the model",
		"bounds":    map[string]any{"Capacity": "2"},
		"build":     map[string]any{"passed": true},
		"toolchain": map[string]any{
			"python_image":  "python@sha256:" + strings.Repeat("ab", 32),
			"nagini_recipe": "sha256:" + strings.Repeat("cd", 32),
			"python_dependencies": map[string]any{
				"base":     "python@sha256:" + strings.Repeat("ef", 32),
				"recipe":   "sha256:" + strings.Repeat("12", 32),
				"platform": "linux/amd64",
				"inputs": []any{
					map[string]any{"path": "requirements.txt", "sha256": "sha256:" + strings.Repeat("34", 32)},
					map[string]any{"path": "requirements/constraints.txt", "sha256": "sha256:" + strings.Repeat("56", 32)},
				},
				"canonical_inputs": []any{
					map[string]any{"path": "constraints.txt", "sha256": "sha256:" + strings.Repeat("a1", 32)},
					map[string]any{"path": "requirements.txt", "sha256": "sha256:" + strings.Repeat("b2", 32)},
				},
				"artifacts": []any{
					map[string]any{"name": "idna", "version": "3.10", "filename": "idna-3.10-py3-none-any.whl", "sha256": "sha256:" + strings.Repeat("78", 32)},
					map[string]any{"name": "six", "version": "1.16.0", "filename": "six-1.16.0-py2.py3-none-any.whl", "sha256": "sha256:" + strings.Repeat("9a", 32)},
				},
			},
		},
	}
}

func pythonDependenciesAcceptReport(t *testing.T, document map[string]any) verify.Report {
	t.Helper()
	b, err := json.Marshal(document)
	if err != nil {
		t.Fatal(err)
	}
	var r verify.Report
	if err := json.Unmarshal(b, &r); err != nil {
		t.Fatal(err)
	}
	return r
}

func pythonDependenciesAcceptEvidence(document map[string]any) map[string]any {
	return document["toolchain"].(map[string]any)["python_dependencies"].(map[string]any)
}

func pythonDependenciesAcceptSetImage(t *testing.T, r *verify.Report, image string) {
	t.Helper()
	// Image is deliberately absent from JSON. Set the execution-only value
	// directly so the exclusion check exercises a selected runtime image.
	fields := reflect.ValueOf(&r.Toolchain).Elem()
	for i := 0; i < fields.NumField(); i++ {
		if strings.Split(fields.Type().Field(i).Tag.Get("json"), ",")[0] != "python_dependencies" {
			continue
		}
		evidence := fields.Field(i)
		if evidence.Kind() == reflect.Pointer && !evidence.IsNil() {
			evidence = evidence.Elem()
		}
		if evidence.Kind() == reflect.Struct {
			value := evidence.FieldByName("Image")
			if value.IsValid() && value.CanSet() && value.Kind() == reflect.String {
				value.SetString(image)
				return
			}
		}
	}
	t.Fatal("Python dependency evidence must retain the execution-only Image field")
}

// Hashes may use the receipt's existing twelve-hex-digit display convention.
func pythonDependenciesAcceptShort(hash string) string {
	if i := strings.Index(hash, "sha256:"); i >= 0 && len(hash) >= i+19 {
		return hash[:i+19]
	}
	return hash
}

func TestPythonReceiptIdentifiesResolvedDependencies(t *testing.T) {
	document := pythonDependenciesAcceptDocument()
	r := pythonDependenciesAcceptReport(t, document)
	pythonDependenciesAcceptMarkdown(t, document, r)
	pythonDependenciesAcceptMarkdown(t, document, pythonDependenciesAcceptAttributed(t, r))
}

// The existing attribution API can preserve shared environment evidence
// without enabling Python component discovery or execution.
func pythonDependenciesAcceptAttributed(t *testing.T, r verify.Report) verify.Report {
	t.Helper()
	sourceHash := "sha256:" + strings.Repeat("d7", 32)
	inv := &project.ComponentInventory{
		Mode:  "explicit",
		Scope: []string{"core"},
		Files: []project.ComponentFile{{Path: "core/ops.go", SHA256: sourceHash}},
		Components: []project.Component{{
			ID: "go:example.com/app/core#Step@core/ops.go", Language: "go",
			Package: "example.com/app/core", Symbol: "Step", Source: "core/ops.go", SourceSHA256: sourceHash,
		}},
	}
	if err := r.AttributeComponentProofs(inv, nil); err != nil {
		t.Fatal(err)
	}
	if r.CodeAssurance() != "component evidence" || len(r.Components.Proofs) != 1 || r.Components.Proofs[0].Status != "unchecked" {
		t.Fatalf("environment evidence must not establish component proof: %#v", r.Components)
	}
	return r
}

func pythonDependenciesAcceptMarkdown(t *testing.T, document map[string]any, r verify.Report) {
	t.Helper()
	md := receipt.Markdown(&r)
	evidence := pythonDependenciesAcceptEvidence(document)
	appRecipe := pythonDependenciesAcceptShort(evidence["recipe"].(string))
	naginiRecipe := pythonDependenciesAcceptShort(document["toolchain"].(map[string]any)["nagini_recipe"].(string))
	for _, want := range []string{appRecipe, pythonDependenciesAcceptShort(evidence["base"].(string)), evidence["platform"].(string), naginiRecipe} {
		if !strings.Contains(md, want) {
			t.Errorf("receipt omits dependency or verifier provenance %q:\n%s", want, md)
		}
	}
	// The application's recipe and Nagini's recipe must have distinct
	// descriptions, so an application package is not presented as prover input.
	var applicationNamed, naginiNamed bool
	for _, line := range strings.Split(md, "\n") {
		lower := strings.ToLower(line)
		if strings.Contains(lower, "python") && strings.Contains(lower, "depend") {
			applicationNamed = true
		}
		if strings.Contains(line, naginiRecipe) && strings.Contains(lower, "nagini") && !strings.Contains(line, appRecipe) {
			naginiNamed = true
		}
	}
	if !applicationNamed || !naginiNamed {
		t.Errorf("receipt must distinguish Python application dependencies from the pinned Nagini verifier:\n%s", md)
	}
	for _, kind := range []string{"inputs", "canonical_inputs"} {
		for _, value := range evidence[kind].([]any) {
			input := value.(map[string]any)
			path, hash := input["path"].(string), pythonDependenciesAcceptShort(input["sha256"].(string))
			var identified bool
			for _, line := range strings.Split(md, "\n") {
				if strings.Contains(line, path) && strings.Contains(line, hash) {
					identified = true
				}
			}
			if !identified {
				t.Errorf("receipt omits %s provenance %s %s:\n%s", kind, path, hash, md)
			}
		}
	}
	if !strings.Contains(strings.ToLower(md), "canonical") {
		t.Errorf("receipt must distinguish canonical installation files from original application inputs:\n%s", md)
	}
	for _, value := range evidence["artifacts"].([]any) {
		artifact := value.(map[string]any)
		for _, key := range []string{"name", "version", "filename", "sha256"} {
			want := pythonDependenciesAcceptShort(artifact[key].(string))
			if !strings.Contains(md, want) {
				t.Errorf("receipt omits resolved artifact %s %s=%q:\n%s", artifact["name"], key, want, md)
			}
		}
	}
}

func TestPythonFingerprintTracksResolvedDependencies(t *testing.T) {
	document := pythonDependenciesAcceptDocument()
	r := pythonDependenciesAcceptReport(t, document)
	original := verify.Fingerprint(r)
	attributed := pythonDependenciesAcceptAttributed(t, r)
	attributedOriginal := verify.Fingerprint(attributed)
	changes := []struct {
		name   string
		change func(map[string]any)
	}{
		{"artifact hash", func(e map[string]any) {
			e["artifacts"].([]any)[0].(map[string]any)["sha256"] = "sha256:" + strings.Repeat("bc", 32)
		}},
		{"artifact version", func(e map[string]any) {
			e["artifacts"].([]any)[0].(map[string]any)["version"] = "3.11"
		}},
		{"platform", func(e map[string]any) { e["platform"] = "linux/arm64" }},
		{"referenced input hash", func(e map[string]any) {
			e["inputs"].([]any)[1].(map[string]any)["sha256"] = "sha256:" + strings.Repeat("de", 32)
		}},
		{"root input hash", func(e map[string]any) {
			e["inputs"].([]any)[0].(map[string]any)["sha256"] = "sha256:" + strings.Repeat("e3", 32)
		}},
		{"canonical constraints hash", func(e map[string]any) {
			e["canonical_inputs"].([]any)[0].(map[string]any)["sha256"] = "sha256:" + strings.Repeat("f4", 32)
		}},
		{"canonical requirements hash", func(e map[string]any) {
			e["canonical_inputs"].([]any)[1].(map[string]any)["sha256"] = "sha256:" + strings.Repeat("05", 32)
		}},
	}
	for _, change := range changes {
		changed := pythonDependenciesAcceptDocument()
		change.change(pythonDependenciesAcceptEvidence(changed))
		if got := verify.Fingerprint(pythonDependenciesAcceptReport(t, changed)); got == original {
			t.Errorf("changing %s while retaining the recipe must change the fingerprint", change.name)
		}
		changedAttributed := pythonDependenciesAcceptAttributed(t, pythonDependenciesAcceptReport(t, changed))
		if got := verify.Fingerprint(changedAttributed); got == attributedOriginal || changedAttributed.Fingerprint != got {
			t.Errorf("component attribution must preserve %s and recompute the fingerprint", change.name)
		}
	}
	attributedJSON, err := json.Marshal(attributed)
	if err != nil {
		t.Fatal(err)
	}
	var attributedDocument map[string]any
	if err := json.Unmarshal(attributedJSON, &attributedDocument); err != nil {
		t.Fatal(err)
	}
	if got := attributedDocument["toolchain"].(map[string]any)["python_dependencies"]; !reflect.DeepEqual(got, pythonDependenciesAcceptEvidence(document)) {
		t.Errorf("component attribution loses application dependency evidence: got %s", attributedJSON)
	}
	if got := verify.Fingerprint(pythonDependenciesAcceptReport(t, attributedDocument)); got != attributedOriginal {
		t.Errorf("component JSON round trip changes the fingerprint: %s != %s", got, attributedOriginal)
	}

	encoded, err := json.Marshal(r)
	if err != nil {
		t.Fatal(err)
	}
	var roundtripDocument map[string]any
	if err := json.Unmarshal(encoded, &roundtripDocument); err != nil {
		t.Fatal(err)
	}
	gotEvidence := roundtripDocument["toolchain"].(map[string]any)["python_dependencies"]
	if !reflect.DeepEqual(gotEvidence, pythonDependenciesAcceptEvidence(document)) {
		t.Errorf("report JSON loses application dependency evidence: got %s", encoded)
	}
	roundtrip := pythonDependenciesAcceptReport(t, roundtripDocument)
	if got := verify.Fingerprint(roundtrip); got != original {
		t.Errorf("JSON round trip changes the fingerprint: %s != %s", got, original)
	}

	// Local Docker tags and immutable IDs select execution environments;
	// the portable evidence, including canonical bytes, identifies them.
	for _, image := range []string{"invariant-python-deps:local-only", "sha256:" + strings.Repeat("c6", 32)} {
		withImage := pythonDependenciesAcceptDocument()
		pythonDependenciesAcceptEvidence(withImage)["image"] = image
		selected := pythonDependenciesAcceptReport(t, withImage)
		pythonDependenciesAcceptSetImage(t, &selected, image)
		if got := verify.Fingerprint(selected); got != original {
			t.Errorf("local image %q changes the dependency fingerprint: %s != %s", image, got, original)
		}
		selectedJSON, err := json.Marshal(selected)
		if err != nil {
			t.Fatal(err)
		}
		if strings.Contains(string(selectedJSON), image) || strings.Contains(receipt.Markdown(&selected), image) {
			t.Errorf("receipt exposes a local dependency image identity %q: %s", image, selectedJSON)
		}
	}

	legacy := pythonDependenciesAcceptDocument()
	delete(legacy["toolchain"].(map[string]any), "python_dependencies")
	legacyReport := pythonDependenciesAcceptReport(t, legacy)
	legacyJSON, err := json.Marshal(legacyReport)
	if err != nil {
		t.Fatal(err)
	}
	var legacyDocument map[string]any
	if err := json.Unmarshal(legacyJSON, &legacyDocument); err != nil {
		t.Fatal(err)
	}
	legacyTools := legacyDocument["toolchain"].(map[string]any)
	if _, present := legacyTools["python_dependencies"]; present {
		t.Errorf("legacy report adds an empty Python dependency field: %s", legacyJSON)
	}
	if got, want := legacyTools["python_image"], legacy["toolchain"].(map[string]any)["python_image"]; got != want {
		t.Errorf("legacy Python image changed: got %v, want %v", got, want)
	}
	if got := verify.Fingerprint(legacyReport); got == original {
		t.Error("a report with resolved dependencies has the same fingerprint as the legacy report without them")
	}
}

sources.internal/verify/python_authority_accept_:
package verify

import (
	"context"
	"encoding/json"
	"os"
	"path"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/toolchain"
)

// The pinned-base parser's versioned JSON boundary is deliberately observable:
// testing only a second parser beside production cannot prove that production
// uses pip at all. These types describe its report, not an independent parser.
// Paths are project-relative and slash-separated; include values retain the
// spelling pip actually followed. Requirement identity comes from pip's own
// InstallRequirement constructor, including its separate link and marker.
type pyDepsAuthorityReport struct {
	Schema       int                          `json:"schema"`
	PipVersion   string                       `json:"pip_version"`
	Root         string                       `json:"root"`
	Files        []pyDepsAuthorityFile        `json:"files"`
	Includes     []pyDepsAuthorityInclude     `json:"includes"`
	Requirements []pyDepsAuthorityRequirement `json:"requirements"`
	Options      []pyDepsAuthorityOption      `json:"options"`
	Errors       []pyDepsAuthorityError       `json:"errors"`
}

type pyDepsAuthorityFile struct {
	Path       string `json:"path"`
	Constraint bool   `json:"constraint"`
}

type pyDepsAuthorityInclude struct {
	Source     string `json:"source"`
	Target     string `json:"target"`
	Value      string `json:"value"`
	Constraint bool   `json:"constraint"`
}

type pyDepsAuthorityRequirement struct {
	Source     string                  `json:"source"`
	Line       int                     `json:"line"`
	Name       string                  `json:"name"`
	Extras     []string                `json:"extras"`
	Specifier  string                  `json:"specifier"`
	Marker     string                  `json:"marker"`
	Hashes     map[string][]string     `json:"hashes"`
	Constraint bool                    `json:"constraint"`
	URL        string                  `json:"url"`
	Link       string                  `json:"link"`
	Path       string                  `json:"path"`
	Archive    bool                    `json:"archive"`
	Editable   bool                    `json:"editable"`
	Options    []pyDepsAuthorityOption `json:"options"`
}

type pyDepsAuthorityOption struct {
	Source string `json:"source"`
	Line   int    `json:"line"`
	Name   string `json:"name"`
	Value  string `json:"value"`
}

type pyDepsAuthorityError struct {
	Source  string `json:"source"`
	Line    int    `json:"line"`
	Type    string `json:"type"`
	Message string `json:"message"`
}

func pyDepsAuthorityFixtureReport() pyDepsAuthorityReport {
	return pyDepsAuthorityReport{
		Schema: 1, PipVersion: "26.2.1", Root: "requirements.txt",
		Files: []pyDepsAuthorityFile{{"requirements.txt", false}, {"deps/application.txt", false}, {"deps/constraints.txt", true}},
		Includes: []pyDepsAuthorityInclude{
			{"requirements.txt", "deps/application.txt", "deps/application.txt", false},
			{"deps/application.txt", "deps/constraints.txt", "constraints.txt", true},
		},
		Requirements: []pyDepsAuthorityRequirement{
			{Source: "deps/application.txt", Line: 1, Name: "packaging", Extras: []string{}, Specifier: ">=24,<25", Hashes: map[string][]string{}, Options: []pyDepsAuthorityOption{}},
			{Source: "deps/constraints.txt", Line: 1, Name: "packaging", Extras: []string{}, Specifier: "==24.2", Hashes: map[string][]string{}, Constraint: true, Options: []pyDepsAuthorityOption{}},
		},
		Options: []pyDepsAuthorityOption{}, Errors: []pyDepsAuthorityError{},
	}
}

// #264: every example is superficially valid to an overly broad Go name or
// whitespace parser. Retain all prior strict rejection tests, and add these
// in root requirements, nested requirements and nested constraints. A strict
// preflight may refuse them before pip; either path must prevent installation.
func TestPythonDependenciesRejectPinnedPipInterpretationGaps(t *testing.T) {
	cases := []pyDepsInvalidInputCase{
		{"review bare sdist", "package-1.0.tar.gz\n"},
		{"review bare wheel", "packaging-24.2-py3-none-any.whl\n"},
		{"bare zip", "package-1.0.zip\n"},
		{"bare compressed tar", "package-1.0.tar.bz2\n"},
		{"bare archive with marker", "package-1.0.tar.gz; python_version < '0'\n"},
		{"bare wheel with hash", "packaging-24.2-py3-none-any.whl --hash=sha256:" + strings.Repeat("a", 64) + "\n"},
		{"review empty requirement equals", "--requirement= deps/application.txt\n"},
		{"empty constraint equals", "--constraint= deps/application.txt\n"},
		{"review no-break-space requirement", "-r\u00a0deps/application.txt\n"},
		{"no-break-space constraint", "-c\u00a0deps/application.txt\n"},
	}
	for _, tc := range cases {
		for _, filename := range []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"} {
			t.Run(tc.name+"/"+filename, func(t *testing.T) {
				pyDepsFakeDocker(t)
				root := pyDepsFixture(t)
				// If a faulty preflight strips the bad separator or empty value,
				// its repaired reference must really exist even in a nested file.
				pyDepsWrite(t, root, "deps/deps/application.txt", "packaging==24.2\n")
				pyDepsWrite(t, root, filename, tc.raw)
				before := pyDepsFiles(t, root)
				pyDepsAssertAuthorityRefused(t, root, false)
				if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
					t.Fatal("rejecting a pip interpretation gap changed application inputs")
				}
			})
		}
	}
}

func TestPythonDependenciesParseWithPinnedPipBeforeBuild(t *testing.T) {
	pyDepsFakeDocker(t)
	t.Setenv("INVARIANT_ACCEPT_CREDENTIAL", "host-only-secret")
	t.Setenv("PIP_INDEX_URL", "https://host-only.invalid/private")
	t.Setenv("PYTHONPATH", "/host/unsafe-python-path")
	root := pyDepsFixture(t)
	pyDepsWrite(t, root, "pip.py", "raise AssertionError('application pip module executed')\n")
	pyDepsWrite(t, root, "sitecustomize.py", "raise AssertionError('application sitecustomize executed')\n")
	before := pyDepsFiles(t, root)
	if recipe, err := toolchain.PythonDepsRecipe(root); err != nil || !pyDepsDigest.MatchString(recipe) {
		t.Fatalf("recipe could not obtain an authoritative offline report: %q %v", recipe, err)
	}
	pyDepsAssertParserCalls(t, root)
	if pyDepsBuildCount(t) != 0 {
		t.Fatal("requesting a recipe built a dependency image")
	}
	env := pyDepsBuild(t, root)
	pyDepsAssertCanonicalStaging(t, root, env, []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"})
	pyDepsAssertParserCalls(t, root)
	seenParser := false
	for _, call := range pyDepsCalls(t) {
		if call.Kind == "parser" {
			seenParser = true
		}
		if call.Kind == "build" && !seenParser {
			t.Fatal("dependency build ran before the pinned pip parser")
		}
	}
	if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
		t.Fatal("offline pinned pip parsing changed application files")
	}
	t.Run("no requirements keeps standard library path", func(t *testing.T) {
		pyDepsFakeDocker(t)
		empty := t.TempDir()
		if recipe, err := toolchain.PythonDepsRecipe(empty); err != nil || recipe != "" {
			t.Fatalf("missing requirements invoked dependency parsing: %q %v", recipe, err)
		}
		if env, err := toolchain.PythonDepsImage(context.Background(), empty); err != nil || env != nil {
			t.Fatalf("missing requirements selected dependency environment: %#v %v", env, err)
		}
		if calls := pyDepsCalls(t); len(calls) != 0 {
			t.Fatalf("standard library path invoked Docker: %#v", calls)
		}
	})
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
		t.Run("production pip reports every unsupported form", pyDepsAssertProductionParserReportsForbiddenForms)
	}
}

// The earlier rejection corpus deliberately fails strict preflight before
// Docker. To test the production Python helper's own observation of forbidden
// syntax, let that preflight read a valid project, then have the CLI boundary
// substitute a second read-only project when forwarding the actual helper to
// real Docker. No independent parser or fabricated report participates here.
func pyDepsAssertProductionParserReportsForbiddenForms(t *testing.T) {
	t.Helper()
	for _, tc := range []struct {
		name     string
		filename string
		body     string
		option   string
		form     string
	}{
		{"standalone index", "requirements.txt", "--index-url https://example.invalid/simple\n-r deps/application.txt\n", "--index-url", ""},
		{"standalone source builds", "deps/application.txt", "--no-binary :all:\npackaging>=24,<25\n-c constraints.txt\n", "--no-binary", ""},
		{"constraint option", "deps/constraints.txt", "--find-links https://example.invalid/wheels\npackaging==24.2\n", "--find-links", ""},
		{"standalone pre-release flag", "requirements.txt", "--pre\n-r deps/application.txt\n", "--pre", ""},
		{"per requirement build setting", "deps/application.txt", "packaging>=24,<25 --config-settings=backend.key=value\n-c constraints.txt\n", "--config-settings", ""},
		{"named wheel link", "requirements.txt", "packaging-24.2-py3-none-any.whl\n", "", "link"},
		{"bare source archive", "deps/application.txt", "package-1.0.tar.gz\n", "", "link"},
		{"named URL link", "deps/application.txt", "packaging @ https://example.invalid/packaging-24.2-py3-none-any.whl ; python_version < '0'\n", "", "link"},
		{"editable local directory", "requirements.txt", "-e ./local-package\n", "", "editable"},
		{"empty equals include", "requirements.txt", "--requirement= deps/application.txt\n", "", "error"},
		{"no-break-space include", "requirements.txt", "-r\u00a0deps/application.txt\n", "", "error"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			pyDepsFakeDocker(t)
			acceptedRoot, reportedRoot := pyDepsFixture(t), pyDepsFixture(t)
			pyDepsWrite(t, reportedRoot, tc.filename, tc.body)
			before := pyDepsFiles(t, reportedRoot)
			t.Setenv("INVARIANT_PY_DEPS_PARSER_PROJECT", reportedRoot)
			ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
			defer cancel()
			if env, err := toolchain.PythonDepsImage(ctx, acceptedRoot); err == nil || env != nil {
				t.Errorf("production accepted a forbidden form reported by its actual pinned pip helper: env=%#v error=%v", env, err)
			}
			var report pyDepsAuthorityReport
			found := false
			for _, call := range pyDepsCalls(t) {
				if call.Kind == "build" || call.Kind == "application" || call.Kind == "evidence" {
					t.Errorf("real helper's forbidden form reached installation or execution: %#v", call)
				}
				if call.Kind == "parser" && len(call.ParserReport) > 0 {
					if err := json.Unmarshal(call.ParserReport, &report); err != nil {
						t.Fatal(err)
					}
					found = true
				}
			}
			if !found || report.Schema != 1 || report.PipVersion == "" {
				t.Fatalf("actual production helper failed without a pip report; infrastructure failure is not input refusal: %#v", report)
			}
			if tc.option != "" {
				options := append([]pyDepsAuthorityOption{}, report.Options...)
				for _, row := range report.Requirements {
					options = append(options, row.Options...)
				}
				observed := false
				for _, option := range options {
					observed = observed || (option.Name == tc.option && option.Source == tc.filename && option.Line > 0)
				}
				if !observed {
					t.Fatalf("pip accepted the option syntax but production omitted its option row: wanted %s in %s; report=%#v", tc.option, tc.filename, report)
				}
			} else {
				observed := false
				for _, inputError := range report.Errors {
					observed = observed || (inputError.Source == tc.filename && inputError.Type != "" && inputError.Message != "")
				}
				for _, row := range report.Requirements {
					if row.Source != tc.filename {
						continue
					}
					switch tc.form {
					case "link":
						observed = observed || row.Link != "" || row.URL != "" || row.Path != "" || row.Archive
					case "editable":
						observed = observed || row.Editable
					}
				}
				if !observed {
					t.Fatalf("production omitted pip's forbidden form or input refusal: wanted %s in %s; report=%#v", tc.form, tc.filename, report)
				}
			}
			if !reflect.DeepEqual(before, pyDepsFiles(t, reportedRoot)) {
				t.Fatal("the real production parser rewrote its read-only project")
			}
		})
	}
}

func pyDepsAssertParserCalls(t *testing.T, root string) {
	t.Helper()
	resolvedRoot, err := filepath.EvalSymlinks(root)
	if err != nil {
		t.Fatal(err)
	}
	count := 0
	for _, call := range pyDepsCalls(t) {
		if call.Kind != "parser" {
			continue
		}
		count++
		if call.Image != toolchain.PythonImage || call.Network != "none" || call.Platform != "linux/amd64" {
			t.Errorf("parser did not use the pinned offline base: %#v", call)
		}
		isolated := false
		for _, arg := range call.Command {
			isolated = isolated || arg == "-I"
		}
		python := call.Entrypoint
		if python == "" && len(call.Command) > 0 {
			python = call.Command[0]
		}
		if !isolated || !path.IsAbs(python) || !strings.HasPrefix(path.Base(python), "python") {
			t.Errorf("parser is not an absolute isolated Python invocation: %#v", call)
		}
		if call.Workdir == "" || !path.IsAbs(call.Workdir) {
			t.Errorf("parser lacks an explicit clean working directory: %#v", call)
		}
		projectMounted := false
		for target, host := range call.Mounts {
			if path.Clean(call.Workdir) == path.Clean(target) || strings.HasPrefix(path.Clean(call.Workdir), path.Clean(target)+"/") {
				t.Errorf("parser runs from mounted input directory %q: %#v", target, call)
			}
			resolvedHost, err := filepath.EvalSymlinks(host)
			if err == nil && filepath.Clean(resolvedHost) == filepath.Clean(resolvedRoot) {
				projectMounted = true
				if !call.ReadOnlyMounts[target] {
					t.Errorf("project is writable during authoritative parsing: %#v", call)
				}
			}
		}
		if !projectMounted {
			t.Errorf("parser did not read the application's project mount: %#v", call)
		}
		for key := range call.Environment {
			if key == "INVARIANT_ACCEPT_CREDENTIAL" || key == "PIP_INDEX_URL" || key == "PYTHONPATH" || key == "PYTHONHOME" {
				t.Errorf("parser inherited host configuration or credentials: %s", key)
			}
		}
	}
	if count == 0 {
		t.Fatal("production accepted application requirements without invoking pinned pip")
	}
}

func TestPythonDependenciesCanonicalFilesComeFromPipReport(t *testing.T) {
	// Deliberate boundary injection, never a real-pip fixture: keep source
	// bytes fixed while varying the successful trusted parser's semantic
	// report. This catches calling pip only for show, then using Go's parse.
	t.Setenv("INVARIANT_PYTHON_DEPS_REAL", "")
	pyDepsFakeDocker(t)
	root := pyDepsFixture(t)
	before := pyDepsFiles(t, root)
	report := pyDepsAuthorityFixtureReport()
	pyDepsSetParserReport(t, report)
	first := pyDepsBuild(t, root)
	inputs := []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"}
	canonical := pyDepsAssertCanonicalStaging(t, root, first, inputs)
	pyDepsAssertCanonicalLines(t, canonical["requirements.txt"], []string{"packaging>=24,<25"})
	report.Requirements[0].Name = "requests"
	report.Requirements[0].Extras = []string{"security", "socks"}
	report.Requirements[0].Specifier = "==2.32.3"
	report.Requirements[0].Marker = "python_version < '0'"
	report.Requirements[0].Hashes = map[string][]string{"sha256": {strings.Repeat("a", 64), strings.Repeat("b", 64)}}
	pyDepsSetParserReport(t, report)
	second := pyDepsBuild(t, root)
	changed := pyDepsAssertCanonicalStaging(t, root, second, inputs)
	pyDepsAssertCanonicalLines(t, changed["requirements.txt"], []string{"requests[security,socks]==2.32.3; python_version < '0' --hash=sha256:" + strings.Repeat("a", 64) + " --hash=sha256:" + strings.Repeat("b", 64)})
	pyDepsAssertCanonicalLines(t, changed["constraints.txt"], []string{"packaging==24.2"})
	if first.Recipe == second.Recipe || first.Image == second.Image || reflect.DeepEqual(first.CanonicalInputs, second.CanonicalInputs) || pyDepsBuildCount(t) != 2 {
		t.Fatalf("pip report semantics did not determine canonical bytes and cache identity: first=%#v second=%#v", first, second)
	}
	if !reflect.DeepEqual(first.Inputs, second.Inputs) || !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
		t.Fatal("using pip's report altered original dependency evidence or application files")
	}
	if recipe, err := toolchain.PythonDepsRecipe(root); err != nil || recipe != second.Recipe {
		t.Fatalf("recipe API ignored the authoritative report: %q %v", recipe, err)
	}
}

func TestPythonDependenciesRejectDisallowedPipReports(t *testing.T) {
	// Every source file is an ordinary valid named requirement. Only the
	// trusted parser's report introduces the unsupported form or option.
	// In particular, a named req does not make a separate install.link safe.
	cases := []struct {
		name   string
		change func(*pyDepsAuthorityReport)
	}{
		{"named requirement with link", func(r *pyDepsAuthorityReport) { r.Requirements[0].Link = "file:///project/package.whl" }},
		{"named direct URL", func(r *pyDepsAuthorityReport) { r.Requirements[0].URL = "https://example.invalid/package.whl" }},
		{"local path", func(r *pyDepsAuthorityReport) { r.Requirements[0].Path = "deps/package" }},
		{"archive", func(r *pyDepsAuthorityReport) { r.Requirements[0].Archive = true }},
		{"editable", func(r *pyDepsAuthorityReport) { r.Requirements[0].Editable = true }},
		{"unnamed requirement", func(r *pyDepsAuthorityReport) { r.Requirements[0].Name = "" }},
		{"requirement from unreported file", func(r *pyDepsAuthorityReport) { r.Requirements[0].Source = "not-followed.txt" }},
		{"unsupported hash", func(r *pyDepsAuthorityReport) {
			r.Requirements[0].Hashes = map[string][]string{"md5": {strings.Repeat("a", 32)}}
		}},
		{"pip input error", func(r *pyDepsAuthorityReport) {
			r.Errors = []pyDepsAuthorityError{{"deps/application.txt", 1, "InstallationError", "Invalid requirement: acceptance parser refusal"}}
		}},
		{"escaped include", func(r *pyDepsAuthorityReport) {
			r.Includes[0].Target = "../outside.txt"
			r.Includes[0].Value = "../outside.txt"
		}},
		{"absolute include", func(r *pyDepsAuthorityReport) {
			r.Includes[0].Target = "/etc/passwd"
			r.Includes[0].Value = "/etc/passwd"
		}},
		{"remote include", func(r *pyDepsAuthorityReport) {
			r.Includes[0].Target = "https://example.invalid/req.txt"
			r.Includes[0].Value = r.Includes[0].Target
		}},
		{"empty include value", func(r *pyDepsAuthorityReport) { r.Includes[0].Value = "" }},
		{"unreported include target", func(r *pyDepsAuthorityReport) { r.Includes[0].Target = "not-followed.txt" }},
		{"escaped file", func(r *pyDepsAuthorityReport) { r.Files[1].Path = "../outside.txt" }},
		{"missing reported file", func(r *pyDepsAuthorityReport) { r.Files = r.Files[:1] }},
		{"unknown schema", func(r *pyDepsAuthorityReport) { r.Schema = 999 }},
		{"missing pip identity", func(r *pyDepsAuthorityReport) { r.PipVersion = "" }},
		{"wrong root", func(r *pyDepsAuthorityReport) { r.Root = "other.txt" }},
		{"missing requirement records", func(r *pyDepsAuthorityReport) { r.Requirements = nil }},
	}
	for _, name := range []string{"--index-url", "--extra-index-url", "--no-binary", "--find-links", "--trusted-host", "--no-index", "--pre", "--require-hashes", "--config-settings", "--unknown-option"} {
		option := name
		cases = append(cases, struct {
			name   string
			change func(*pyDepsAuthorityReport)
		}{"standalone " + option, func(r *pyDepsAuthorityReport) {
			r.Options = []pyDepsAuthorityOption{{"requirements.txt", 1, option, "reported"}}
		}})
	}
	cases = append(cases, struct {
		name   string
		change func(*pyDepsAuthorityReport)
	}{"per requirement option", func(r *pyDepsAuthorityReport) {
		r.Requirements[0].Options = []pyDepsAuthorityOption{{"deps/application.txt", 1, "--config-settings", "backend.key=value"}}
	}})
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv("INVARIANT_PYTHON_DEPS_REAL", "")
			pyDepsFakeDocker(t)
			root := pyDepsFixture(t)
			before := pyDepsFiles(t, root)
			report := pyDepsAuthorityFixtureReport()
			tc.change(&report)
			pyDepsSetParserReport(t, report)
			pyDepsAssertAuthorityRefused(t, root, true)
			if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
				t.Fatal("rejecting pip's report changed application inputs")
			}
		})
	}
}

func TestPythonDependenciesParserFailuresDoNotBuildOrFallBack(t *testing.T) {
	for _, cached := range []bool{false, true} {
		for _, mode := range []string{"process failure", "empty report", "invalid JSON", "empty JSON object", "truncated report"} {
			name := mode
			if cached {
				name = "cached/" + name
			}
			t.Run(name, func(t *testing.T) {
				t.Setenv("INVARIANT_PYTHON_DEPS_REAL", "")
				pyDepsFakeDocker(t)
				root := pyDepsFixture(t)
				if cached {
					pyDepsBuild(t, root)
				}
				// Ignore the initial successful build; no failed parse may
				// build again, inspect cached evidence, or execute application.
				if err := os.WriteFile(filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "calls.jsonl"), nil, 0o644); err != nil {
					t.Fatal(err)
				}
				switch mode {
				case "process failure":
					t.Setenv("INVARIANT_PY_DEPS_PARSER_FAILURE", "acceptance pinned pip parser unavailable")
				case "empty report":
					pyDepsSetParserRawReport(t, nil)
				case "invalid JSON":
					pyDepsSetParserRawReport(t, []byte("pip parser emitted invalid JSON"))
				case "empty JSON object":
					pyDepsSetParserRawReport(t, []byte("{}"))
				case "truncated report":
					pyDepsSetParserRawReport(t, []byte(`{"schema":1,"pip_version":"26.2.1","requirements":[`))
				}
				pyDepsAssertAuthorityRefused(t, root, true)
			})
		}
	}
}

func pyDepsAssertAuthorityRefused(t *testing.T, root string, requireParser bool) {
	t.Helper()
	if recipe, err := toolchain.PythonDepsRecipe(root); err == nil || recipe != "" {
		t.Errorf("recipe API accepted refused or untrustworthy pip report: recipe=%q error=%v", recipe, err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	if env, err := toolchain.PythonDepsImage(ctx, root); err == nil || env != nil {
		t.Errorf("image API accepted refused or untrustworthy pip report: env=%#v error=%v", env, err)
	}
	p, err := project.Load(root)
	if err != nil {
		t.Fatal(err)
	}
	b, evidence, err := (Python{Image: toolchain.PythonImage}).Check(ctx, p)
	if err == nil || b.Passed || len(evidence.Traces) != 0 {
		t.Errorf("parser refusal or failure ran a Python fallback: build=%#v evidence=%#v error=%v", b, evidence, err)
	}
	if os.Getenv("INVARIANT_PY_DEPS_PARSER_FAILURE") != "" && (err == nil || !strings.Contains(err.Error(), "acceptance pinned pip parser unavailable")) {
		t.Errorf("parser failure lost its actionable diagnostic: %v", err)
	}
	for _, call := range pyDepsCalls(t) {
		if call.Kind == "build" || call.Kind == "application" || call.Kind == "evidence" {
			t.Errorf("refused parsing reached installation, cached evidence or execution: %#v", call)
		}
	}
	if requireParser {
		pyDepsAssertParserCalls(t, root)
	}
}

sources.internal/verify/python_canonical_accept_:
package verify

import (
	"reflect"
	"sort"
	"strings"
	"testing"
)

func TestPythonDependenciesRejectBackslashExploit(t *testing.T) {
	// Exact #246 shape: two literal trailing backslashes. pip removes the
	// whole run while the old validator removed one, so the following option
	// escaped validation during a network-enabled installation.
	const review = "packaging; python_version >= '3.0' " + "\\\\" + "\n--no-binary :all:\n"
	pyDepsRejectInvalidInputs(t, []pyDepsInvalidInputCase{
		{"review source builds", review},
		{"review index redirection", strings.ReplaceAll(review, "--no-binary :all:", "--index-url https://example.invalid/simple")},
	})
}

func TestPythonDependenciesRejectUnsupportedBackslashes(t *testing.T) {
	pyDepsRejectInvalidInputs(t, []pyDepsInvalidInputCase{
		{"double trailing", "packaging==24.2 " + strings.Repeat("\\", 2) + "\n"},
		{"triple trailing", "packaging==24.2 " + strings.Repeat("\\", 3) + "\n--hash=sha256:" + strings.Repeat("a", 64) + "\n"},
		{"long trailing run", "packaging==24.2 " + strings.Repeat("\\", 8) + "\n"},
		{"inside package", "pack\\aging==24.2\n"},
		{"inside marker value", "packaging; os_name == 'po\\six'\n"},
		{"escaped marker quote", "packaging; os_name == 'po\\'six'\n"},
		{"inside include path", "-r deps\\application.txt\n"},
		{"inside hash", "packaging==24.2 --hash=sha256:" + strings.Repeat("a", 32) + "\\" + strings.Repeat("b", 32) + "\n"},
		{"inside comment", "# comment with a \\ backslash\npackaging==24.2\n"},
		{"run in comment", "# comment " + strings.Repeat("\\", 2) + "\npackaging==24.2\n"},
		{"before inline comment", "packaging==24.2 \\ # comment\n"},
		{"before trailing space", "packaging==24.2 \\ \n--hash=sha256:" + strings.Repeat("a", 64) + "\n"},
		{"before trailing tab", "packaging==24.2 \\\t\n"},
		{"dangling without LF", "packaging==24.2 \\"},
		{"dangling with LF", "packaging==24.2 \\\n"},
	})
}

func TestPythonDependenciesRejectUnsupportedGrammar(t *testing.T) {
	pyDepsRejectInvalidInputs(t, []pyDepsInvalidInputCase{
		{"two requirements on one line", "packaging==24.2 idna==3.10\n"},
		{"empty extra", "packaging[foo,,bar]==24.2\n"},
		{"unterminated extras", "packaging[foo==24.2\n"},
		{"missing version", "packaging==\n"},
		{"unparsed requirement suffix", "packaging==24.2 garbage\n"},
		{"unknown marker variable", "packaging; mystery_platform == 'linux'\n"},
		{"invalid marker operator", "packaging; python_version = '3.0'\n"},
		{"unterminated marker literal", "packaging; python_version >= '3.0\n"},
		{"unbalanced marker parentheses", "packaging; (python_version >= '3.0'\n"},
		{"incomplete marker conjunction", "packaging; python_version >= '3.0' and\n"},
		{"unparsed marker suffix", "packaging; python_version >= '3.0' garbage\n"},
		{"second marker separator", "packaging; python_version >= '3.0'; os_name == 'posix'\n"},
		{"source option after marker", "packaging; python_version >= '3.0' --no-binary :all:\n"},
		{"index option after marker", "packaging; python_version >= '3.0' --index-url https://example.invalid/simple\n"},
		{"continued source option", "packaging; python_version >= '3.0' \\\n    --no-binary :all:\n"},
		{"continued index option", "packaging; python_version >= '3.0' \\\n    --index-url https://example.invalid/simple\n"},
		// pip's option splitter can recognize a space-delimited option even
		// inside a quoted PEP 508 marker literal. Such atoms are outside the
		// supported grammar; copying them into canonical files is not safe.
		{"source option inside marker literal", "packaging; python_version >= '3.0 --no-binary :all:'\n"},
		{"index option inside marker literal", "packaging; python_version >= '3.0 --index-url https://example.invalid/simple'\n"},
		{"source option as marker literal", "packaging; python_version == '--no-binary :all:'\n"},
		{"index option as marker literal", "packaging; python_version == '--index-url https://example.invalid/simple'\n"},
		{"include option inside marker literal", "packaging; os_name == 'posix -r deps/application.txt'\n"},
		{"hash option inside marker literal", "packaging; os_name == 'posix --hash=sha256:" + strings.Repeat("a", 64) + "'\n"},
		{"hash option as marker literal", "packaging; os_name == '--hash=sha256:" + strings.Repeat("a", 64) + "'\n"},
		// A literal # has different comment behavior across pip parsing
		// stages. Marker strings containing it are unsupported; ordinary
		// comments remain supported and are removed during canonicalization.
		{"comment character inside marker literal", "packaging; os_name == 'posix # ignored'\n"},
		{"comment character as marker literal", "packaging; os_name == '#'\n"},
		{"build setting after requirement", "packaging==24.2 --config-settings=backend.key=value\n"},
		{"include followed by option", "-r deps/application.txt --no-binary :all:\n"},
		{"constraint followed by extra token", "-c deps/constraints.txt garbage\n"},
		{"standalone hash", "--hash=sha256:" + strings.Repeat("a", 64) + "\n"},
		{"unsupported hash algorithm", "packaging==24.2 --hash=md5:" + strings.Repeat("a", 32) + "\n"},
		{"short SHA256", "packaging==24.2 --hash=sha256:abcd\n"},
		{"nonhex SHA256", "packaging==24.2 --hash=sha256:" + strings.Repeat("g", 64) + "\n"},
		{"missing hash value", "packaging==24.2 --hash\n"},
		{"unknown inline option", "packaging==24.2 --unknown-option=value\n"},
	})
}

func TestPythonDependenciesCanonicalizeAcceptedRequirements(t *testing.T) {
	t.Run("recursive closure and single continuations", func(t *testing.T) {
		pyDepsFakeDocker(t)
		root := pyDepsFixture(t)
		firstHash, secondHash := strings.Repeat("a", 64), strings.Repeat("b", 64)
		pyDepsWrite(t, root, "requirements.txt", "\xef\xbb\xbf# café root requirements\r\n--requirement \\\r\n    deps/application.txt\r\n--constraint deps/constraints.txt\r\n-r deps/shared.txt\r\n")
		pyDepsWrite(t, root, "deps/application.txt", "# requirement include\npackaging==24.2 # requested package\n-rnested/extras.txt\n")
		pyDepsWrite(t, root, "deps/nested/extras.txt", "requests[security,socks]==2.32.3 ; python_version < '0' and (os_name == 'posix' or sys_platform == 'linux') \\\n    --hash=sha256:"+firstHash+" \\\n    --hash=sha256:"+secondHash+" # accepted hashes\n")
		pyDepsWrite(t, root, "deps/constraints.txt", "packaging==24.2\n-c nested/constraints.txt\n--constraint=shared.txt\n")
		pyDepsWrite(t, root, "deps/nested/constraints.txt", "# nested constraint\nrequests<3 ; \\\n    python_version >= '3.0'\n")
		pyDepsWrite(t, root, "deps/shared.txt", "idna==3.10 ; python_version < '0'\n")
		inputs := []string{"requirements.txt", "deps/application.txt", "deps/nested/extras.txt", "deps/constraints.txt", "deps/nested/constraints.txt", "deps/shared.txt"}
		before := pyDepsFiles(t, root)
		env := pyDepsBuild(t, root)
		pyDepsAssertRecipeEnvironment(t, root, env, inputs)
		canonical := pyDepsAssertCanonicalStaging(t, root, env, inputs)
		// The shared file is hashed once in Inputs and visited in both roles:
		// its entry must be present in each canonical file. Synthetic hashes
		// exercise serialization here; real recipe execution has its own test.
		pyDepsAssertCanonicalLines(t, canonical["requirements.txt"], []string{
			"packaging==24.2",
			"requests[security,socks]==2.32.3; python_version < '0' and (os_name == 'posix' or sys_platform == 'linux') --hash=sha256:" + firstHash + " --hash=sha256:" + secondHash,
			"idna==3.10; python_version < '0'",
		})
		pyDepsAssertCanonicalLines(t, canonical["constraints.txt"], []string{
			"packaging==24.2",
			"requests<3; python_version >= '3.0'",
			"idna==3.10; python_version < '0'",
		})
		if second := pyDepsBuild(t, root); !reflect.DeepEqual(env, second) || pyDepsBuildCount(t) != 1 {
			t.Fatalf("canonical dependency environment did not reuse exact evidence: first=%#v second=%#v", env, second)
		}
		if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
			t.Fatal("canonicalization rewrote the application's requirement files or other source")
		}
	})
	t.Run("explicit empty constraints file", func(t *testing.T) {
		pyDepsFakeDocker(t)
		root := pyDepsFixture(t)
		pyDepsWrite(t, root, "requirements.txt", "# only a root requirement\npackaging==24.2\n")
		before := pyDepsFiles(t, root)
		env := pyDepsBuild(t, root)
		canonical := pyDepsAssertCanonicalStaging(t, root, env, []string{"requirements.txt"})
		pyDepsAssertCanonicalLines(t, canonical["requirements.txt"], []string{"packaging==24.2"})
		if canonical["constraints.txt"] != "" {
			t.Fatalf("no constraints must produce an empty canonical constraints file, got %q", canonical["constraints.txt"])
		}
		if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
			t.Fatal("canonicalization rewrote an application with no constraints")
		}
	})
}

func TestPythonDependenciesCanonicalCacheTracksBothRepresentations(t *testing.T) {
	pyDepsFakeDocker(t)
	root := pyDepsFixture(t)
	inputs := []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"}
	original := pyDepsFiles(t, root)
	first := pyDepsBuild(t, root)
	canonical := pyDepsAssertCanonicalStaging(t, root, first, inputs)
	builds := 1
	// Source bytes remain provenance even when canonicalization removes a
	// comment. Keying reuse only on canonical bytes would miss each change.
	for _, filename := range inputs {
		pyDepsWrite(t, root, filename, original[filename]+"# canonical-inert provenance change\n")
		before := pyDepsFiles(t, root)
		changed := pyDepsBuild(t, root)
		got := pyDepsAssertCanonicalStaging(t, root, changed, inputs)
		builds++
		if changed.Recipe == first.Recipe || reflect.DeepEqual(changed.Inputs, first.Inputs) || pyDepsBuildCount(t) != builds {
			t.Fatalf("changing raw %s reused the old recipe or its provenance: first=%#v changed=%#v builds=%d", filename, first, changed, pyDepsBuildCount(t))
		}
		if !reflect.DeepEqual(got, canonical) || !reflect.DeepEqual(changed.CanonicalInputs, first.CanonicalInputs) {
			t.Fatalf("a comment in %s changed canonical installation bytes or hashes: got=%#v want=%#v", filename, got, canonical)
		}
		if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
			t.Fatal("building changed original dependency bytes")
		}
		pyDepsWrite(t, root, filename, original[filename])
		if restored := pyDepsBuild(t, root); !reflect.DeepEqual(restored, first) || pyDepsBuildCount(t) != builds {
			t.Fatalf("restoring the original bytes did not reuse the original environment: %#v", restored)
		}
	}
	// An effective constraint change updates canonical bytes and their hashes
	// as well as original provenance, recipe identity and installed evidence.
	pyDepsWrite(t, root, "deps/constraints.txt", "packaging==24.1\n")
	before := pyDepsFiles(t, root)
	changed := pyDepsBuild(t, root)
	got := pyDepsAssertCanonicalStaging(t, root, changed, inputs)
	builds++
	if changed.Recipe == first.Recipe || reflect.DeepEqual(changed.CanonicalInputs, first.CanonicalInputs) || pyDepsBuildCount(t) != builds {
		t.Fatalf("effective constraints did not change canonical provenance and the cached recipe: first=%#v changed=%#v", first, changed)
	}
	if got["requirements.txt"] != canonical["requirements.txt"] || got["constraints.txt"] == canonical["constraints.txt"] {
		t.Fatalf("constraint change affected the wrong canonical file: before=%#v after=%#v", canonical, got)
	}
	pyDepsAssertCanonicalLines(t, got["constraints.txt"], []string{"packaging==24.1"})
	pyDepsAssertEnvironment(t, root, changed, "24.1")
	if second := pyDepsBuild(t, root); !reflect.DeepEqual(second, changed) || pyDepsBuildCount(t) != builds {
		t.Fatalf("changed canonical recipe did not reuse its evidence: %#v", second)
	}
	if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
		t.Fatal("canonical cache handling rewrote application files")
	}
}

// Compare a multiset of fully parsed fixture requirements without dictating
// quote style, harmless whitespace, specifier order or line order. No comments, continuations,
// includes or pip options other than complete SHA256 hash tokens can survive.
func pyDepsAssertCanonicalLines(t *testing.T, body string, want []string) {
	t.Helper()
	if strings.ContainsAny(body, "\\#\r") || strings.Contains(body, "\xef\xbb\xbf") || (body != "" && !strings.HasSuffix(body, "\n")) {
		t.Fatalf("canonical file contains source syntax or lacks final LF: %q", body)
	}
	var got []string
	for _, line := range strings.Split(strings.TrimSuffix(body, "\n"), "\n") {
		if line == "" {
			if body != "" {
				t.Fatal("canonical file contains an empty requirement line")
			}
			continue
		}
		for _, token := range strings.Fields(line) {
			if strings.HasPrefix(token, "-") && (!strings.HasPrefix(token, "--hash=") || !pyDepsDigest.MatchString(strings.TrimPrefix(token, "--hash="))) {
				t.Fatalf("canonical file retained an include or installer option: %q", line)
			}
		}
		got = append(got, pyDepsComparableRequirement(t, line))
	}
	var expected []string
	for _, line := range want {
		expected = append(expected, pyDepsComparableRequirement(t, line))
	}
	sort.Strings(got)
	sort.Strings(expected)
	if !reflect.DeepEqual(got, expected) {
		t.Fatalf("canonical requirements lost or changed accepted semantics:\n got %q\nwant %q\nraw canonical bytes %q", got, expected, body)
	}
}

func pyDepsComparableRequirement(t *testing.T, line string) string {
	t.Helper()
	var normalized strings.Builder
	var quote rune
	for _, r := range line {
		if quote != 0 {
			if r == quote {
				quote = 0
				normalized.WriteRune('\'')
			} else {
				normalized.WriteRune(r)
			}
		} else if r == '\'' || r == '"' {
			quote = r
			normalized.WriteRune('\'')
		} else if r != ' ' && r != '\t' {
			normalized.WriteRune(r)
		}
	}
	if quote != 0 {
		t.Fatalf("canonical requirement has an unterminated marker literal: %q", line)
	}
	value := normalized.String()
	// Pip reports a SpecifierSet, whose iteration/string order need not match
	// the original file. Compare that set without changing marker literals or
	// the hash evidence that follows it. The real-pip oracle independently
	// checks complete requirement semantics.
	end := len(value)
	for _, boundary := range []string{";", "--hash="} {
		if i := strings.Index(value, boundary); i >= 0 && i < end {
			end = i
		}
	}
	head, tail := value[:end], value[end:]
	if start := strings.IndexAny(head, "<>=!~"); start >= 0 {
		specifiers := strings.Split(head[start:], ",")
		sort.Strings(specifiers)
		return head[:start] + strings.Join(specifiers, ",") + tail
	}
	return value
}

