package verify

import (
	"archive/zip"
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/toolchain"
)

// The CLI layer checks the actual commands crossing the Docker boundary.
// The real layer first executes the unmodified generated recipe, then makes
// an adversarial cached image by installing a fixture wheel with real pip,
// offline. That wheel installs cat, sh and timeout. Its genuine pip report
// is combined with the recipe's report, retaining both artifact hashes.
// This cache fixture does not add support for local-wheel requirements.
//
// Required on the pull request head before merge, with the earlier suite:
// INVARIANT_PYTHON_DEPS_REAL=1 go test ./internal/verify -run '^TestPythonDependenc' -count=1 -timeout 30m
func TestPythonDependenciesKeepGateCommandsTrusted(t *testing.T) {
	root := pyDepsFixture(t)
	pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("# command regression %d\n-r deps/application.txt\n", time.Now().UnixNano()))
	// Test network isolation in the ordinary AND larger-bound drivers.
	driver := pyDepsFiles(t, root)["conformance.py"]
	driver = "import socket\ntry:\n    socket.create_connection(('198.51.100.1', 443), timeout=0.2)\nexcept OSError:\n    pass\nelse:\n    raise AssertionError('driver has network access')\n" + driver
	pyDepsWrite(t, root, "conformance.py", driver)
	var recipe string
	t.Run("trusted command boundary", func(t *testing.T) {
		pyDepsFakeDocker(t)
		tc := toolchain.Toolchain{PythonImage: toolchain.PythonImage, JavaImage: "accept-java", TLCJar: filepath.Join(t.TempDir(), "tlc.jar")}
		r, err := Run(context.Background(), root, "", tc)
		pyDepsRequireGateChecks(t, r, err)
		var evidence, ordinary, larger bool
		for _, call := range pyDepsCalls(t) {
			if call.Kind != "evidence" && call.Kind != "application" {
				continue
			}
			if len(call.Command) == 0 || !pyDepsTrustedExecutable(call.Command[0]) {
				t.Fatalf("gate command can resolve through dependency-controlled PATH: %#v", call)
			}
			if call.Kind == "evidence" {
				evidence = true
			} else {
				if path.Base(call.Command[0]) != "sh" {
					t.Fatalf("check launcher must be the trusted shell: %#v", call.Command)
				}
				if call.Count {
					larger = true
				} else {
					ordinary = true
				}
			}
			if path.Base(call.Command[0]) == "sh" {
				if len(call.Command) != 3 || call.Command[1] != "-c" {
					t.Fatalf("unexpected sandbox launch: %#v", call.Command)
				}
				pyDepsRequireTrustedHelpers(t, call.Command[2])
			}
		}
		if !evidence || !ordinary || !larger {
			t.Fatalf("missing execution paths: evidence=%t ordinary=%t larger=%t", evidence, ordinary, larger)
		}
		staged := pyDepsFiles(t, filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "context"))
		pyDepsAssertPipParserMatches(t, root, map[string]string{
			"requirements.txt": staged["canonical/requirements.txt"],
			"constraints.txt":  staged["canonical/constraints.txt"],
		})
		recipe = staged["Dockerfile"]
		pyDepsRecipeLibraryTarget(t, recipe)
	})
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
		t.Run("installed commands cannot replace gate commands", func(t *testing.T) {
			pyDepsRealTrustedCommands(t, root, recipe, "commands")
		})
	}
}

func pyDepsTrustedExecutable(command string) bool {
	// These directories belong to the pinned base, outside the application
	// library target. Shell builtins do not consult PATH and need no executable path.
	return path.IsAbs(command) && path.Clean(command) == command && path.Base(command) != "env" &&
		(path.Dir(command) == "/bin" || path.Dir(command) == "/usr/bin" || path.Dir(command) == "/usr/local/bin")
}

func pyDepsRequireTrustedHelpers(t *testing.T, script string) {
	t.Helper()
	// Quoted bootstrap programs stay single arguments. Every executable,
	// including the application's Python and timeout's child, is trusted.
	for _, statement := range pyDepsShellCommands(t, script) {
		if strings.TrimSpace(statement) == "exec 2>&1" {
			continue
		}
		args := pyDepsRecipeArguments(t, statement)
		if len(args) == 0 {
			continue
		}
		if args[0] == "exec" {
			args = args[1:]
			if len(args) == 0 {
				t.Fatal("unexpected empty exec in check script")
			}
		}
		command := args[0]
		switch command {
		case "cd", "echo", "printf", ":", "true", "false", "test", "[":
			continue // builtins of the trusted shell
		}
		if !pyDepsTrustedExecutable(command) {
			t.Errorf("check helper %q can resolve through application PATH:\n%s", command, script)
		}
		if path.Base(command) == "timeout" {
			// Production's timeout uses --option=value, then the duration.
			for i := 1; i < len(args); i++ {
				if strings.HasPrefix(args[i], "-") {
					continue
				}
				if i+1 >= len(args) || !pyDepsTrustedExecutable(args[i+1]) {
					t.Fatalf("timeout child can resolve through application PATH: %s", statement)
				}
				break
			}
		}
	}
}

// Locate the saved pip report in the generated recipe, without imposing a
// new production path/API just to set up the adversarial cache fixture.
func pyDepsRecipeReportPath(t *testing.T, recipe string) string {
	t.Helper()
	recipe = strings.ReplaceAll(strings.ReplaceAll(recipe, "\\\r\n", " "), "\\\n", " ")
	cwd, report := "", ""
	for _, line := range strings.Split(recipe, "\n") {
		line = strings.TrimSpace(line)
		word, body, _ := strings.Cut(line, " ")
		switch strings.ToUpper(word) {
		case "WORKDIR":
			args := pyDepsRecipeArguments(t, strings.TrimSpace(body))
			if len(args) == 1 {
				cwd = args[0]
			}
		case "RUN":
			args := pyDepsRecipeArguments(t, strings.TrimSpace(body))
			for i, arg := range args {
				value := ""
				if arg == "--report" && i+1 < len(args) {
					value = args[i+1]
				} else if strings.HasPrefix(arg, "--report=") {
					value = strings.TrimPrefix(arg, "--report=")
				}
				if value != "" {
					if !path.IsAbs(value) {
						value = path.Join(cwd, value)
					}
					report = value
				}
			}
		}
	}
	if !path.IsAbs(report) {
		t.Fatalf("generated recipe has no saved pip report: %s", recipe)
	}
	return report
}

func pyDepsRequireGateChecks(t *testing.T, r *Report, err error) {
	t.Helper()
	if err != nil || r == nil || !r.Passed || !r.Build.Passed || r.Conformance == nil || !r.Conformance.Passed ||
		r.Larger == nil || !r.Larger.Passed || r.Larger.States != 3 || r.Larger.Depth != 3 {
		t.Fatalf("gate checks changed under command shadowing: report=%#v error=%v", r, err)
	}
}

func pyDepsRealTrustedCommands(t *testing.T, root, recipe, vector string) {
	t.Helper()
	reportPath := pyDepsRecipeReportPath(t, recipe)
	libraryPath := pyDepsRecipeLibraryTarget(t, recipe)
	pyDepsRequireRealDocker(t)
	ctx, cancel := context.WithTimeout(context.Background(), 12*time.Minute)
	defer cancel()
	docker := func(args ...string) []byte {
		t.Helper()
		out, err := exec.CommandContext(ctx, "docker", args...).CombinedOutput()
		if err != nil {
			t.Fatalf("Docker fixture %v: %v\n%s", args, err, out)
		}
		return bytes.TrimSpace(out)
	}
	// This runs the actual production recipe before installing the hostile
	// fixture. Keep its real packaging artifact as an independent oracle.
	first := pyDepsBuild(t, root)
	pyDepsCleanupRecipeImage(t, first.Image)
	pyDepsAssertEnvironment(t, root, first, "24.2")
	var tags []string
	if err := json.Unmarshal(docker("image", "inspect", "--format", "{{json .RepoTags}}", first.Image), &tags); err != nil || len(tags) == 0 {
		t.Fatalf("generated recipe image has no cache reference: %v %v", tags, err)
	}
	wheel, wheelHash := pyDepsShadowWheel(t, vector)
	container := fmt.Sprintf("invariant-command-fixture-%d", time.Now().UnixNano())
	t.Cleanup(func() {
		cleanupCtx, stop := context.WithTimeout(context.Background(), 30*time.Second)
		defer stop()
		exec.CommandContext(cleanupCtx, "docker", "rm", "--force", container).Run()
	})
	// The base interpreter performs setup in isolated mode. pip installs
	// into the production library target and reports the exact fixture wheel.
	// It never starts an interpreter from a dependency-controlled directory.
	const install = `import json, subprocess, sys
report_path, target, wheel = sys.argv[1:]
with open(report_path) as f:
    report = json.load(f)
subprocess.run([sys.executable, "-I", "-m", "pip", "--isolated", "install", "--no-index", "--no-deps", "--only-binary=:all:", "--target", target, "--upgrade", "--report", "/tmp/shadow-report.json", wheel], check=True)
with open("/tmp/shadow-report.json") as f:
    fixture = json.load(f)
assert len(fixture["install"]) == 1
report["install"].extend(fixture["install"])
with open(report_path, "w") as f:
    json.dump(report, f)
`
	docker("run", "--name", container, "--network", "none", "--platform", "linux/amd64", "-w", "/tmp",
		"-v", filepath.Dir(wheel)+":/fixture:ro", first.Image, "/usr/local/bin/python", "-I", "-c", install, reportPath, libraryPath, "/fixture/"+filepath.Base(wheel))
	derived := string(docker("commit", container))
	if !pyDepsDigest.MatchString(derived) {
		t.Fatalf("fixture did not yield an immutable image ID: %q", derived)
	}
	t.Cleanup(func() {
		cleanupCtx, stop := context.WithTimeout(context.Background(), 30*time.Second)
		defer stop()
		for _, tag := range tags {
			exec.CommandContext(cleanupCtx, "docker", "image", "rm", tag).Run()
		}
		exec.CommandContext(cleanupCtx, "docker", "image", "rm", derived).Run()
	})
	for _, tag := range tags {
		docker("tag", derived, tag)
	}
	// Negative controls explicitly enable the unsafe lookup/startup path.
	// The production image need not put dependency scripts on PATH.
	pyDepsShadowNegativeControl(t, ctx, docker, derived, libraryPath, reportPath, vector)
	pyDepsAssertImportOnlyImage(t, docker, derived, libraryPath)
	selected := pyDepsBuild(t, root)
	if selected.Image != derived || selected.Recipe != first.Recipe || !reflect.DeepEqual(selected.Inputs, first.Inputs) || !reflect.DeepEqual(selected.CanonicalInputs, first.CanonicalInputs) {
		t.Fatalf("gate did not reuse the adversarial cached environment: %#v", selected)
	}
	if len(selected.Artifacts) != 2 {
		t.Fatalf("installed %s changed the genuine installation reports: %#v", vector, selected.Artifacts)
	}
	packaging, fixture := false, false
	for _, artifact := range selected.Artifacts {
		switch artifact.Name {
		case "packaging":
			packaging = reflect.DeepEqual(artifact, first.Artifacts[0])
		case "invariant-gate-shadow":
			fixture = artifact.Version == "1.0" && artifact.Filename == filepath.Base(wheel) && artifact.SHA256 == wheelHash
		}
	}
	if !packaging || !fixture {
		t.Fatalf("receipt evidence differs from the wheels actually installed: %#v", selected.Artifacts)
	}
	if again := pyDepsBuild(t, root); !reflect.DeepEqual(again, selected) {
		t.Fatalf("evidence changed on reuse: %#v != %#v", again, selected)
	}
	tc, err := toolchain.Ensure(ctx)
	if err != nil {
		t.Fatal(err)
	}
	// Every application process explicitly imports the fixture library. Its
	// side effect must be absent before that import and present afterwards.
	originalSources := pyDepsFiles(t, root)
	const importProbe = "import builtins\nassert not hasattr(builtins, 'INVARIANT_IMPORTED_LIBRARY')\nimport invariant_gate_shadow\nassert builtins.INVARIANT_IMPORTED_LIBRARY == 'import-only'\n"
	for _, name := range []string{"test_dependency.py", "conformance.py"} {
		pyDepsWrite(t, root, name, importProbe+originalSources[name])
	}
	r, err := Run(ctx, root, "", tc)
	pyDepsRequireGateChecks(t, r, err)
	all, _ := json.Marshal(r)
	if strings.Contains(string(all), "INVARIANT_SHADOW_") {
		t.Fatalf("dependency code ran without an application import: %s", all)
	}
	encoded, err := json.Marshal(r.Toolchain)
	if err != nil {
		t.Fatal(err)
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(encoded, &fields); err != nil {
		t.Fatal(err)
	}
	want, _ := json.Marshal(selected)
	if string(fields["python_dependencies"]) != string(want) {
		t.Fatalf("gate receipt lost genuine dependency evidence: %s != %s", fields["python_dependencies"], want)
	}
	// Checks must still detect application failures, not merely print
	// successful markers. Each failure is planted independently.
	p, err := project.Load(root)
	if err != nil {
		t.Fatal(err)
	}
	original := pyDepsFiles(t, root)
	pyDepsWrite(t, root, "test_dependency.py", original["test_dependency.py"]+"\n    def test_planted_failure(self):\n        self.fail('INVARIANT_PLANTED_UNIT_FAILURE')\n")
	b, _, err := (Python{Image: toolchain.PythonImage}).Check(ctx, p)
	if err != nil || b.Passed || !strings.Contains(b.Output, "INVARIANT_PLANTED_UNIT_FAILURE") {
		t.Fatalf("installed commands concealed a failing unittest: %#v %v", b, err)
	}
	pyDepsWrite(t, root, "test_dependency.py", original["test_dependency.py"])
	pyDepsWrite(t, root, "conformance.py", "raise RuntimeError('INVARIANT_PLANTED_DRIVER_FAILURE')\n"+original["conformance.py"])
	_, evidence, err := (Python{Image: toolchain.PythonImage}).Check(ctx, p)
	if err != nil || len(evidence.Traces) != 0 || !strings.Contains(evidence.Message, "INVARIANT_PLANTED_DRIVER_FAILURE") {
		t.Fatalf("installed commands concealed failed conformance: %#v %v", evidence, err)
	}
	larger, err := countLarger(ctx, selected.Image, "python", p, map[string]int{"Capacity": 2})
	if err != nil || larger.OK || !strings.Contains(larger.Message, "INVARIANT_PLANTED_DRIVER_FAILURE") {
		t.Fatalf("installed commands concealed a failing larger driver: %#v %v", larger, err)
	}
	pyDepsWrite(t, root, "conformance.py", original["conformance.py"])
	if after := pyDepsBuild(t, root); !reflect.DeepEqual(after, selected) {
		t.Fatalf("running installed %s changed dependency receipt evidence: %#v != %#v", vector, after, selected)
	}
}

// Construct real wheel bytes, including RECORD hashes and executable script
// modes, so pip's actual wheel installation scheme is exercised offline.
func pyDepsShadowWheel(t *testing.T, vector string) (string, string) {
	t.Helper()
	const dist = "invariant_gate_shadow-1.0.dist-info/"
	const data = "invariant_gate_shadow-1.0.data/scripts/"
	files := map[string]string{
		"invariant_gate_shadow.py": "import builtins\nbuiltins.INVARIANT_IMPORTED_LIBRARY = 'import-only'\n",
		dist + "METADATA":          "Metadata-Version: 2.1\nName: invariant-gate-shadow\nVersion: 1.0\n",
		dist + "WHEEL":             "Wheel-Version: 1.0\nGenerator: invariant-acceptance\nRoot-Is-Purelib: true\nTag: py3-none-any\n",
	}
	// Forged success includes real evidence files, so planted failures detect
	// startup takeover even when the gate requires traces/counts as well as
	// exit status. The marker also makes each negative control observable.
	payload := fmt.Sprintf(`import json, os, sys
print(%q, flush=True)
if "INVARIANT_TRACES" in os.environ:
    with open(os.environ["INVARIANT_TRACES"], "w") as f:
        json.dump({"traces": [[{"n": 0}, {"n": 1}]]}, f)
if "INVARIANT_COUNT" in os.environ:
    with open(os.environ["INVARIANT_COUNT"], "w") as f:
        json.dump({"states": 3, "depth": 3}, f)
print("@@invariant compile=0\n@@invariant test=0\n@@invariant conform=0\n@@invariant count=0", flush=True)
os._exit(0)
`, "INVARIANT_SHADOW_"+vector)
	switch vector {
	case "commands":
		files[data+"cat"] = `#!python
import json, sys
with open(sys.argv[1]) as f:
    report = json.load(f)
report["install"] = []
print(json.dumps(report))
`
		for i, name := range []string{"sh", "timeout"} {
			files[data+name] = fmt.Sprintf("#!python\nimport sys\nprint(%q, file=sys.stderr)\nsys.exit(%d)\n", "INVARIANT_SHADOW_"+name, 86+i)
		}
	case "python":
		files[data+"python"] = "#!python\n" + payload
	case "pth":
		files["invariant_gate_shadow.pth"] = "import invariant_gate_shadow_bootstrap\n"
		files["invariant_gate_shadow_bootstrap.py"] = payload
	case "sitecustomize", "usercustomize":
		files[vector+".py"] = payload
	case "gate_modules":
		for _, name := range []string{"compileall", "unittest", "runpy"} {
			files[name+".py"] = payload
		}
	default:
		t.Fatalf("unknown hostile wheel vector %q", vector)
	}
	var names []string
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	var record strings.Builder
	for _, name := range names {
		sum := sha256.Sum256([]byte(files[name]))
		fmt.Fprintf(&record, "%s,sha256=%s,%d\n", name, base64.RawURLEncoding.EncodeToString(sum[:]), len(files[name]))
	}
	record.WriteString(dist + "RECORD,,\n")
	files[dist+"RECORD"] = record.String()
	names = append(names, dist+"RECORD")
	var buf bytes.Buffer
	w := zip.NewWriter(&buf)
	for _, name := range names {
		header := &zip.FileHeader{Name: name, Method: zip.Deflate}
		header.SetMode(0o644)
		if strings.HasPrefix(name, data) {
			header.SetMode(0o755)
		}
		f, err := w.CreateHeader(header)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := f.Write([]byte(files[name])); err != nil {
			t.Fatal(err)
		}
	}
	if err := w.Close(); err != nil {
		t.Fatal(err)
	}
	filename := filepath.Join(t.TempDir(), "invariant_gate_shadow-1.0-py3-none-any.whl")
	if err := os.WriteFile(filename, buf.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}
	return filename, pyDepsHash(buf.Bytes())
}

package verify

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"regexp"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/project"
	"github.com/gitdek/invariant/internal/toolchain"
)

// Intended API: PythonDepsRecipe(root) returns the recipe digest after an
// offline parser run in the pinned Python base; PythonDepsImage(ctx, root)
// returns *PythonDependencies. Neither may build or select a dependency image
// until the pinned base's pip has accepted the original application files.
// Missing requirements.txt returns an empty recipe / nil environment.
// PythonDependencies has Image (an immutable Docker ID, execution only,
// json:"-"), Base, Recipe,
// Platform, Inputs {Path,SHA256}, CanonicalInputs {Path,SHA256}, and
// Artifacts {Name,Version,Filename,SHA256}.
// JSON uses lower_snake_case, including toolchain.python_dependencies.
// Lists are canonical (inputs by path; artifacts by name/version/filename).
// Hashes are sha256:<64 lowercase hex>. Base is toolchain.PythonImage and
// platform is linux/amd64; both and the full installation recipe enter the
// recipe digest, together with length-delimited relative paths and bytes of
// every reachable input and the generated canonical files. CanonicalInputs
// names constraints.txt and requirements.txt relative to the canonical/
// build-context directory, in path order. Local tags and timestamps are not
// evidence.
//
// Supported requirements: UTF-8 pip requirement files with an optional leading
// UTF-8 BOM, LF or CRLF line endings, comments, blank lines,
// single trailing backslash continuations joined without inserted characters,
// exactly as pip joins them, a strict safe subset of PEP 508
// names/extras/versions/markers,
// --hash=sha256:..., and local -r/--requirement/-c/--constraint references.
// Only ASCII spaces separate a requirement from its hash options; other
// whitespace at that boundary is rejected rather than normalized into spaces.
// References resolve from their containing file, stay inside root and may
// share inputs; cycles and symlinks are errors. A strict parser validates
// every requirement and marker as a stricter first check. The pinned base's
// own pip is authoritative: its complete report controls the accepted inputs
// and canonical requirements. Unsupported syntax is rejected rather than
// passed through to installation. Runs of backslashes and every other backslash
// position are rejected, including in comments or markers. Pip parses offline
// with -I from a clean directory and a read-only project mount, reporting
// every requirement, include, constraint and other option or form. Only named
// PyPI requirements with hashes as their only options and contained references
// are accepted. Marker literals containing '#' or
// option-like tokens (including --hash) are outside the supported subset.
// The installer also applies
// its full hash-checking rules. Wheel-only installation from
// public PyPI rejects sdist-only packages rather than running build backends.
// No environment interpolation, URLs/VCS/local/editable packages, index or
// other pip option overrides are allowed. No host pip configuration is used.
// Reject invalid UTF-8, bare CR, encoding declarations in comments anywhere
// in a file (never a package name such as geocoding==1.0), and VT, FF, FS,
// GS, RS, NEL, LS and PS before interpreting comments,
// continuations or references. Installation never reads application files:
// serialize pip's reported requirements to canonical/requirements.txt and
// reported
// constraints to canonical/constraints.txt, one requirement with its hashes
// per LF-terminated line, with no comments, includes, continuations or other
// options. Copy only that directory literally into the build. Validate every
// directory traversed by an input reference on the host, including those
// canceled by '..', but do not stage the original inputs or directories.
// All Python invoked during the build uses -I from a clean cwd outside the
// canonical files. Install wheels with --target into a directory that is not
// a site directory and cannot replace the pinned interpreter or any trusted
// command. Ordinary and larger-bound checks run the base interpreter by its
// absolute path and add this directory to sys.path only after startup: wheel
// scripts, .pth files, sitecustomize and usercustomize must never run just
// because a distribution was installed. Imports explicitly made by the
// application still execute dependency code as part of the code under test.
// Suppress Docker-client proxy defaults for every run and build, in both
// cases of each proxy variable, without rewriting the client's configuration.
//
// Persist pip's installation report in the image and read it back (offline)
// on both build and reuse; never manufacture artifact evidence from inputs.
// Missing or invalid reports are errors, or may trigger a rebuild that must
// yield valid evidence before use. All installed application distributions,
// including transitives, need wheel filename, version and artifact SHA-256.
// A valid empty resolution (e.g. all markers false) differs from no report.
// Resolve an immutable image ID once, then use it for report reads and every
// application run, including larger bounds. A recipe tag is only a cache key.
//
// Default tests use a Docker CLI double. With INVARIANT_PYTHON_DEPS_REAL=1,
// The image reuse and recipe regression tests also execute the actual build
// with real Docker and PyPI, without skipping failures. The parser comparison
// reads every accepted fixture with the pinned image's own pip, offline, and
// compares its requirements, constraints and hashes with the canonical files.
// It also requires pip and the validator to refuse the shared rejected
// option-boundary whitespace corpus, including tabs before --hash.
// The merger runs this
// on the final pull request head and posts its passing output before merge:
// INVARIANT_PYTHON_DEPS_REAL=1 go test ./internal/verify -run '^TestPythonDependenc' -count=1 -timeout 30m

var pyDepsDigest = regexp.MustCompile(`^sha256:[0-9a-f]{64}$`)

func pyDepsHash(b []byte) string {
	h := sha256.Sum256(b)
	return "sha256:" + hex.EncodeToString(h[:])
}

func pyDepsWrite(t *testing.T, root, path, body string) {
	t.Helper()
	p := filepath.Join(root, filepath.FromSlash(path))
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

func pyDepsFiles(t *testing.T, root string) map[string]string {
	t.Helper()
	out := map[string]string{}
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		b, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(root, path)
		out[filepath.ToSlash(rel)] = string(b)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return out
}

// The same referenced-requirement/constraint fixture is used with the CLI
// double and in the real integration run. packaging is a small real wheel.
func pyDepsFixture(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	for path, body := range map[string]string{
		"requirements.txt":     "# application dependencies\n-r deps/application.txt\n",
		"deps/application.txt": "packaging>=24,<25\n-c constraints.txt\n",
		"deps/constraints.txt": "packaging==24.2\n",
		"test_dependency.py": `import os, socket, unittest
from packaging.version import Version
class DependencyTest(unittest.TestCase):
    def test_package_and_isolation(self):
        self.assertLess(Version("1.9"), Version("1.10"))
        self.assertNotIn("INVARIANT_ACCEPT_CREDENTIAL", os.environ)
        self.assertNotIn("PIP_INDEX_URL", os.environ)
        self.assertFalse(os.path.exists("/root/.config/pip/pip.conf"))
        with self.assertRaises(OSError):
            socket.create_connection(("198.51.100.1", 443), timeout=0.2)
`,
		"conformance.py": `import json, os
from packaging.version import Version
Capacity = 1
assert Version("1.9") < Version("1.10")
assert "INVARIANT_ACCEPT_CREDENTIAL" not in os.environ
if "INVARIANT_COUNT" in os.environ:
    with open(os.environ["INVARIANT_COUNT"], "w") as f:
        json.dump({"states": Capacity + 1, "depth": Capacity + 1}, f)
else:
    with open(os.environ["INVARIANT_TRACES"], "w") as f:
        json.dump({"traces": [[{"n": 0}, {"n": 1}]]}, f)
`,
		"core/core.py":                 "def identity(n: int) -> int:\n    return n\n",
		".invariant/invariant.json":    `{"name":"python dependencies","module":".invariant/specs/Counter.tla","language":"python","code":"core","conformance":"conformance.py","exhaustive":true}`,
		".invariant/ratified.lock":     `{"decision":"acceptance fixture","bounds":{"Capacity":"1"},"statements":[{"name":"Spec","kind":"spec","says":"Count within the bound."},{"name":"Safe","kind":"invariant","says":"The count stays within the bound."}]}`,
		".invariant/specs/Counter.tla": "---- MODULE Counter ----\nEXTENDS Naturals\nCONSTANT Capacity\nVARIABLE n\nvars == <<n>>\nInit == n = 0\nNext == IF n < Capacity THEN n' = n + 1 ELSE UNCHANGED n\nSpec == Init /\\ [][Next]_vars\nSafe == n \\in 0..Capacity\n====\n",
	} {
		pyDepsWrite(t, root, path, body)
	}
	p, err := project.Load(root)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := p.Pin(); err != nil {
		t.Fatal(err)
	}
	return root
}

func TestPythonDependencyRecipeCoversReferencedInputs(t *testing.T) {
	pyDepsFakeDocker(t)
	root := pyDepsFixture(t)
	before := pyDepsFiles(t, root)
	recipe, err := toolchain.PythonDepsRecipe(root)
	if err != nil || !pyDepsDigest.MatchString(recipe) {
		t.Fatalf("recipe=%q error=%v", recipe, err)
	}
	pyDepsAssertAcceptedWithPip(t, root)
	copy := t.TempDir()
	for name, body := range before {
		pyDepsWrite(t, copy, name, body)
	}
	pyDepsWrite(t, copy, "test_dependency.py", "# unrelated source edit\n")
	pyDepsWrite(t, copy, "unused-requirements.txt", "idna==3.10\n")
	if got, err := toolchain.PythonDepsRecipe(copy); err != nil || got != recipe {
		t.Fatalf("relocation/unreferenced files changed recipe: %q %v", got, err)
	}
	pyDepsAssertAcceptedWithPip(t, copy)
	for _, path := range []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"} {
		pyDepsWrite(t, copy, path, before[path]+"# effective input changed\n")
		if got, err := toolchain.PythonDepsRecipe(copy); err != nil || got == recipe {
			t.Errorf("changed reachable input %s did not change recipe: %q %v", path, got, err)
		}
		pyDepsAssertAcceptedWithPip(t, copy)
		pyDepsWrite(t, copy, path, before[path])
	}
	// Include spelling, nesting, whitespace, markers, extras and pip hashes
	// are accepted inputs, not content a Go parser silently drops.
	pyDepsWrite(t, copy, "requirements.txt", "--requirement=deps/application.txt\n--constraint deps/constraints.txt\n")
	pyDepsWrite(t, copy, "deps/application.txt", "# nested input\n-rshared.txt\n-cconstraints.txt\n")
	pyDepsWrite(t, copy, "deps/shared.txt", "requests[socks]==2.32.3 ; python_version >= '3.13' \\\n    --hash=sha256:"+strings.Repeat("a", 64)+"\n")
	if _, err := toolchain.PythonDepsRecipe(copy); err != nil {
		t.Fatalf("documented requirement forms rejected: %v", err)
	}
	pyDepsAssertAcceptedWithPip(t, copy)
	if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
		t.Fatal("reading dependency inputs rewrote the application")
	}
	if got, err := toolchain.PythonDepsRecipe(t.TempDir()); err != nil || got != "" {
		t.Fatalf("no requirements should need no dependency recipe: %q %v", got, err)
	}
}

func TestPythonDependenciesRejectUnaccountedInputs(t *testing.T) {
	pyDepsFakeDocker(t)
	for name, body := range map[string]string{
		"outside reference":  "-r ../outside.txt\n",
		"absolute reference": "-c /etc/passwd\n",
		"missing reference":  "-r missing.txt\n",
		"cycle":              "-r requirements.txt\n",
		"url":                "packaging @ https://example.test/pkg.whl\n",
		"remote include":     "--requirement=https://example.test/requirements.txt\n",
		"vcs":                "git+https://example.test/pkg.git\n",
		"editable":           "-e ./package\n",
		"local archive":      "./package.whl\n",
		"local directory":    "../package\n",
		"environment":        "packaging==${PACKAGE_VERSION}\n",
		"index override":     "--index-url https://example.test/simple\npackaging\n",
		"extra index":        "--extra-index-url https://example.test/simple\n",
		"find links":         "--find-links wheels\n",
		"source override":    "--no-binary :all:\npackaging\n",
		"option":             "--trusted-host example.test\n",
	} {
		t.Run(name, func(t *testing.T) {
			root := t.TempDir()
			pyDepsWrite(t, root, "requirements.txt", body)
			if _, err := toolchain.PythonDepsRecipe(root); err == nil {
				t.Fatal("accepted input outside the declared requirements policy")
			}
			if env, err := toolchain.PythonDepsImage(context.Background(), root); err == nil || env != nil {
				t.Fatalf("invalid inputs reached image selection: %#v %v", env, err)
			}
		})
	}
	root := t.TempDir()
	pyDepsWrite(t, root, "requirements.txt", "-r linked.txt\n")
	pyDepsWrite(t, root, "actual.txt", "packaging==24.2\n")
	if err := os.Symlink("actual.txt", filepath.Join(root, "linked.txt")); err != nil {
		t.Fatal(err)
	}
	if _, err := toolchain.PythonDepsRecipe(root); err == nil {
		t.Fatal("symlinked dependency input accepted")
	}
	if calls := pyDepsCalls(t); len(calls) != 0 {
		t.Fatalf("invalid inputs invoked Docker: %v", calls)
	}
}

// Python str.splitlines recognizes these in addition to CR and LF.
func TestPythonDependenciesRejectHiddenPipOptions(t *testing.T) {
	pyDepsFakeDocker(t)
	for _, separator := range []rune{'\v', '\f', '\u001c', '\u001d', '\u001e', '\u0085', '\u2028', '\u2029'} {
		for _, option := range []string{"--index-url https://example.invalid/simple", "--no-binary :all:"} {
			for _, path := range []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"} {
				t.Run(fmt.Sprintf("U+%04X/%s/%s", separator, strings.Fields(option)[0], path), func(t *testing.T) {
					root := pyDepsFixture(t)
					pyDepsWrite(t, root, path, "# seemingly harmless comment"+string(separator)+option+"\npackaging==24.2\n")
					if recipe, err := toolchain.PythonDepsRecipe(root); err == nil {
						t.Fatalf("hidden pip option accepted in %s: recipe=%s", path, recipe)
					}
					if env, err := toolchain.PythonDepsImage(context.Background(), root); err == nil || env != nil {
						t.Fatalf("hidden pip option reached image selection: env=%#v error=%v", env, err)
					}
				})
			}
		}
	}
	if calls := pyDepsCalls(t); len(calls) != 0 {
		t.Fatalf("hidden options must be rejected before Docker: %#v", calls)
	}
	// Supported LF/CRLF line endings and continuations remain supported.
	for _, newline := range []string{"\n", "\r\n"} {
		root := t.TempDir()
		body := strings.Join([]string{"# ordinary comment", "packaging==24.2 \\", " --hash=sha256:" + strings.Repeat("a", 64), ""}, newline)
		pyDepsWrite(t, root, "requirements.txt", body)
		if _, err := toolchain.PythonDepsRecipe(root); err != nil {
			t.Errorf("ordinary pip line ending %q rejected: %v", newline, err)
		}
		pyDepsAssertAcceptedWithPip(t, root)
	}
}

// Replace the mutable tag immediately after selection, retaining both images.
// Fresh builds and cache hits are covered without timing-dependent sleeps.
func TestPythonDependenciesPinImageAcrossTagReplacement(t *testing.T) {
	for _, cached := range []bool{false, true} {
		t.Run(fmt.Sprintf("cached=%t", cached), func(t *testing.T) {
			pyDepsFakeDocker(t)
			root := pyDepsFixture(t)
			pyDepsWrite(t, root, "deps/constraints.txt", "# unconstrained within the requested range\n")
			if cached {
				pyDepsBuild(t, root)
			}
			if err := os.WriteFile(filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "calls.jsonl"), nil, 0o644); err != nil {
				t.Fatal(err)
			}
			t.Setenv("INVARIANT_PY_DEPS_REPLACE_TAG", "1")
			tc := toolchain.Toolchain{PythonImage: toolchain.PythonImage, JavaImage: "accept-java", TLCJar: filepath.Join(t.TempDir(), "tlc.jar")}
			r, err := Run(context.Background(), root, "", tc)
			if err != nil || r == nil || !r.Build.Passed || r.Conformance == nil || !r.Conformance.Passed || r.Larger == nil || !r.Larger.Passed {
				t.Fatalf("gate failed across tag replacement: report=%#v error=%v", r, err)
			}
			calls := pyDepsCalls(t)
			selected := ""
			for _, c := range calls {
				if c.Kind == "selection" {
					if selected != "" {
						t.Fatal("race fixture selected more than one original image")
					}
					selected = c.Image
				}
			}
			if !pyDepsDigest.MatchString(selected) {
				t.Fatalf("race never observed a selected immutable image: %#v", calls)
			}
			var evidenceRead, ordinary, larger bool
			for _, c := range calls {
				if c.Kind != "evidence" && c.Kind != "application" {
					continue
				}
				if c.Image != selected || c.Network != "none" {
					t.Errorf("read/run used a mutable or different environment: %+v; selected %s", c, selected)
				}
				if c.Kind == "evidence" {
					evidenceRead = true
				} else if c.Count {
					larger = true
				} else {
					ordinary = true
				}
			}
			if !evidenceRead || !ordinary || !larger {
				t.Fatalf("missing paths across replacement: evidence=%t ordinary=%t larger=%t", evidenceRead, ordinary, larger)
			}
			encoded, err := json.Marshal(r.Toolchain)
			if err != nil {
				t.Fatal(err)
			}
			var decoded struct {
				Dependencies *toolchain.PythonDependencies `json:"python_dependencies"`
			}
			if err := json.Unmarshal(encoded, &decoded); err != nil || decoded.Dependencies == nil {
				t.Fatalf("receipt missing selected dependency evidence: %s; %v", encoded, err)
			}
			pyDepsAssertEnvironment(t, root, decoded.Dependencies, "24.2")
			pyDepsAssertCanonicalStaging(t, root, decoded.Dependencies, []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"})
			if decoded.Dependencies.Artifacts[0].SHA256 != "sha256:"+strings.Repeat("a", 64) {
				t.Fatalf("receipt describes the replacement wheel: %s", encoded)
			}
			refs, err := filepath.Glob(filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "*.ref"))
			if err != nil || len(refs) != 1 {
				t.Fatalf("expected one mutable recipe tag: %v %v", refs, err)
			}
			current, err := os.ReadFile(refs[0])
			if err != nil || string(current) == selected {
				t.Fatalf("concurrent builder did not replace tag: %q %v", current, err)
			}
		})
	}
}

func TestPythonDependencyImagesBuildReuseAndRunOffline(t *testing.T) {
	// This subtest restores PATH before the optional real integration run.
	t.Run("CLI contract", func(t *testing.T) {
		pyDepsFakeDocker(t)
		root := pyDepsFixture(t)
		before := pyDepsFiles(t, root)
		first := pyDepsBuild(t, root)
		second := pyDepsBuild(t, root)
		if first.Image != second.Image || !reflect.DeepEqual(first, second) || pyDepsBuildCount(t) != 1 {
			t.Fatalf("unchanged requirements did not reuse the recorded environment: %#v %#v", first, second)
		}
		pyDepsAssertEnvironment(t, root, first, "24.2")
		pyDepsAssertCanonicalStaging(t, root, first, []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"})
		pyDepsRunChecks(t, root)
		if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
			t.Fatal("image construction or execution changed application inputs")
		}
		pyDepsWrite(t, root, "deps/constraints.txt", "packaging==24.1\n")
		changed := pyDepsBuild(t, root)
		if changed.Recipe == first.Recipe || changed.Image == first.Image || pyDepsBuildCount(t) != 2 {
			t.Fatal("changing a referenced constraint reused the old image")
		}
		pyDepsAssertEnvironment(t, root, changed, "24.1")
		pyDepsAssertCanonicalStaging(t, root, changed, []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"})
		// The recipe is an input identity, not a promise that floating
		// versions always resolve alike. A cached image keeps its original
		// report; rebuilding after eviction may produce another wheel.
		pyDepsWrite(t, root, "deps/constraints.txt", "# unconstrained within the requested range\n")
		floating := pyDepsBuild(t, root)
		pyDepsAssertCanonicalStaging(t, root, floating, []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"})
		t.Setenv("INVARIANT_PY_DEPS_RESOLUTION", "24.1")
		cached := pyDepsBuild(t, root)
		if !reflect.DeepEqual(floating, cached) {
			t.Fatal("cache evidence was replaced by a fresh resolution")
		}
		cacheFile := filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), strings.TrimPrefix(pyDepsHash([]byte(floating.Image)), "sha256:")+".json")
		if err := os.Remove(cacheFile); err != nil {
			t.Fatal(err)
		}
		rebuilt := pyDepsBuild(t, root)
		if rebuilt.Recipe != floating.Recipe || rebuilt.Artifacts[0].SHA256 == floating.Artifacts[0].SHA256 {
			t.Fatal("fresh resolution of unchanged unpinned requirements did not preserve its distinct artifact evidence")
		}
	})
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
		pyDepsRealIntegration(t)
	}
}

func pyDepsBuild(t *testing.T, root string) *toolchain.PythonDependencies {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()
	env, err := toolchain.PythonDepsImage(ctx, root)
	if err != nil || env == nil || !pyDepsDigest.MatchString(env.Image) {
		t.Fatalf("building Python dependencies: env=%#v error=%v", env, err)
	}
	return env
}

func pyDepsAssertEnvironment(t *testing.T, root string, env *toolchain.PythonDependencies, version string) {
	t.Helper()
	recipe, err := toolchain.PythonDepsRecipe(root)
	if err != nil || env.Recipe != recipe || env.Base != toolchain.PythonImage || env.Platform != "linux/amd64" {
		t.Fatalf("wrong recipe provenance: %#v; recipe error=%v", env, err)
	}
	wantInputs := map[string]string{}
	for _, path := range []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"} {
		b, err := os.ReadFile(filepath.Join(root, path))
		if err != nil {
			t.Fatal(err)
		}
		wantInputs[path] = pyDepsHash(b)
	}
	gotInputs := map[string]string{}
	var ordered []string
	for _, input := range env.Inputs {
		gotInputs[input.Path] = input.SHA256
		ordered = append(ordered, input.Path)
	}
	if !reflect.DeepEqual(wantInputs, gotInputs) || len(env.Inputs) != 3 || !sort.StringsAreSorted(ordered) {
		t.Fatalf("receipt inputs=%#v want=%#v in canonical order", env.Inputs, wantInputs)
	}
	if len(env.CanonicalInputs) != 2 || env.CanonicalInputs[0].Path != "constraints.txt" || env.CanonicalInputs[1].Path != "requirements.txt" {
		t.Fatalf("receipt lacks the two canonical installation inputs: %#v", env.CanonicalInputs)
	}
	for _, input := range env.CanonicalInputs {
		if !pyDepsDigest.MatchString(input.SHA256) {
			t.Fatalf("canonical input lacks its content hash: %#v", input)
		}
	}
	if len(env.Artifacts) != 1 {
		t.Fatalf("expected packaging's one resolved wheel: %#v", env.Artifacts)
	}
	a := env.Artifacts[0]
	if a.Name != "packaging" || a.Version != version || a.Filename != "packaging-"+version+"-py3-none-any.whl" || !pyDepsDigest.MatchString(a.SHA256) {
		t.Fatalf("incomplete resolved wheel evidence: %#v", a)
	}
}

func pyDepsRunChecks(t *testing.T, root string) {
	t.Helper()
	p, err := project.Load(root)
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()
	b, evidence, err := (Python{Image: toolchain.PythonImage}).Check(ctx, p)
	if err != nil || !b.Passed || len(evidence.Traces) == 0 {
		t.Fatalf("tests/driver could not use installed package offline: build=%#v evidence=%#v err=%v", b, evidence, err)
	}
}

func TestPythonDependencyFailuresDoNotFallBack(t *testing.T) {
	pyDepsFakeDocker(t)
	root := pyDepsFixture(t)
	p, err := project.Load(root)
	if err != nil {
		t.Fatal(err)
	}
	for _, mode := range []string{"install", "missing report", "malformed report", "missing artifact hash"} {
		t.Run(mode, func(t *testing.T) {
			t.Setenv("INVARIANT_PY_DEPS_FAILURE", mode)
			// Each case has a fresh cache key so installation must be attempted.
			pyDepsWrite(t, root, "requirements.txt", "# "+mode+"\n-r deps/application.txt\n")
			pyDepsAssertAcceptedWithPip(t, root)
			b, evidence, err := (Python{Image: toolchain.PythonImage}).Check(context.Background(), p)
			if err == nil || b.Passed || len(evidence.Traces) > 0 {
				t.Fatalf("dependency failure silently ran Python: %#v %#v %v", b, evidence, err)
			}
			if mode == "install" && !strings.Contains(err.Error(), "No matching distribution found for impossible-invariant-dependency") {
				t.Fatalf("installation error lost pip's diagnostic: %v", err)
			}
		})
	}
	// Repeat at the same recipe after a successful build to exercise corrupt
	// cache evidence too. The fake keeps returning corruption even if the
	// implementation tries to rebuild, so it must ultimately fail closed.
	pyDepsWrite(t, root, "requirements.txt", "# cached image\n-r deps/application.txt\n")
	pyDepsBuild(t, root)
	for _, mode := range []string{"missing report", "malformed report", "missing artifact hash"} {
		t.Run("cached "+mode, func(t *testing.T) {
			t.Setenv("INVARIANT_PY_DEPS_FAILURE", mode)
			ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer cancel()
			b, evidence, err := (Python{Image: toolchain.PythonImage}).Check(ctx, p)
			if err == nil || b.Passed || len(evidence.Traces) != 0 {
				t.Fatalf("unverifiable cached image was used: %#v %#v %v", b, evidence, err)
			}
		})
	}
	for _, c := range pyDepsCalls(t) {
		if c.Kind == "application" {
			t.Fatalf("application ran despite dependency failure: %+v", c)
		}
	}
}

func TestPythonGateRecordsAndReusesApplicationEnvironment(t *testing.T) {
	pyDepsFakeDocker(t)
	t.Setenv("INVARIANT_ACCEPT_CREDENTIAL", "host-only-secret")
	t.Setenv("PIP_INDEX_URL", "https://host-only.invalid/private")
	root := pyDepsFixture(t)
	// Application packages must never be installed into the proof image.
	pyDepsWrite(t, root, "core/core.py", "# +nagini\ndef identity(n: int) -> int:\n    return n\n")
	tc := toolchain.Toolchain{PythonImage: toolchain.PythonImage, JavaImage: "accept-java", TLCJar: filepath.Join(t.TempDir(), "tlc.jar")}
	r, err := Run(context.Background(), root, "", tc)
	if err != nil || r == nil || !r.Build.Passed || r.Conformance == nil || !r.Conformance.Passed || r.Larger == nil || !r.Larger.Passed {
		t.Fatalf("Python gate did not use application dependencies throughout: report=%#v error=%v", r, err)
	}
	b, err := json.Marshal(r.Toolchain)
	if err != nil {
		t.Fatal(err)
	}
	var tools map[string]json.RawMessage
	if err := json.Unmarshal(b, &tools); err != nil {
		t.Fatal(err)
	}
	if len(tools["python_dependencies"]) == 0 || string(tools["python_dependencies"]) == "null" {
		t.Fatalf("gate omitted application environment from receipt: %s", b)
	}
	selected := pyDepsBuild(t, root)
	pyDepsAssertCanonicalStaging(t, root, selected, []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"})
	want, _ := json.Marshal(selected)
	if string(tools["python_dependencies"]) != string(want) {
		t.Fatalf("receipt does not describe the selected environment: %s != %s", tools["python_dependencies"], want)
	}
	if r.Toolchain.NaginiRecipe != toolchain.NaginiRecipe() || pyDepsBuildCount(t) != 1 {
		t.Fatalf("the application changed Nagini or was rebuilt during gate: %#v", r.Toolchain)
	}
	var application, larger, prover bool
	for _, c := range pyDepsCalls(t) {
		switch c.Kind {
		case "application":
			if c.Image != selected.Image || c.Network != "none" {
				t.Errorf("wrong execution environment: %+v", c)
			}
			if c.Count {
				larger = true
			} else {
				application = true
			}
		case "nagini":
			prover = true
			if c.Image == selected.Image || c.Network != "none" {
				t.Errorf("application environment replaced Nagini: %+v", c)
			}
		}
	}
	if !application || !larger || !prover {
		t.Fatalf("missing execution paths: tests/conformance=%t larger=%t Nagini=%t", application, larger, prover)
	}
	// A project without requirements must still run in the pinned plain image.
	if err := os.Remove(filepath.Join(root, "requirements.txt")); err != nil {
		t.Fatal(err)
	}
	env, err := toolchain.PythonDepsImage(context.Background(), root)
	if err != nil || env != nil {
		t.Fatalf("no requirements should select no dependency environment: %#v %v", env, err)
	}
	pyDepsWrite(t, root, "test_dependency.py", "import unittest\nclass StandardLibraryTest(unittest.TestCase):\n    def test_add(self):\n        self.assertEqual(1 + 1, 2)\n")
	pyDepsWrite(t, root, "conformance.py", "import json, os\nwith open(os.environ['INVARIANT_TRACES'], 'w') as f:\n    json.dump({'traces': [[{'n': 0}, {'n': 1}]]}, f)\n")
	p, err := project.Load(root)
	if err != nil {
		t.Fatal(err)
	}
	plain, _, err := (Python{Image: toolchain.PythonImage}).Check(context.Background(), p)
	if err != nil || !plain.Passed {
		t.Fatalf("stdlib path failed: %#v %v", plain, err)
	}
	calls := pyDepsCalls(t)
	if calls[len(calls)-1].Image != toolchain.PythonImage || pyDepsBuildCount(t) != 1 {
		t.Fatal("stdlib path built dependencies or changed its image")
	}
}

func pyDepsRealIntegration(t *testing.T) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 12*time.Minute)
	defer cancel()
	if out, err := exec.CommandContext(ctx, "docker", "info").CombinedOutput(); err != nil {
		t.Fatalf("real dependency integration requires Docker: %v\n%s", err, out)
	}
	t.Setenv("INVARIANT_ACCEPT_CREDENTIAL", "host-only-secret")
	t.Setenv("PIP_INDEX_URL", "https://host-only.invalid/private")
	root := pyDepsFixture(t)
	// A unique comment gives this integration run its own recipe and forces
	// an initial build; the second call must keep the exact image, not rebuild.
	pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("# integration %d\n-r deps/application.txt\n", time.Now().UnixNano()))
	before := pyDepsFiles(t, root)
	first := pyDepsBuild(t, root)
	var images []string
	pyDepsAssertAcceptedWithPip(t, root)
	images = append(images, first.Image)
	t.Cleanup(func() {
		for _, image := range images {
			cleanupCtx, stop := context.WithTimeout(context.Background(), 30*time.Second)
			exec.CommandContext(cleanupCtx, "docker", "image", "rm", image).Run()
			stop()
		}
	})
	pyDepsAssertEnvironment(t, root, first, "24.2")
	identity := func(image string) string {
		t.Helper()
		out, err := exec.CommandContext(ctx, "docker", "image", "inspect", "--format", "{{.Id}} {{.Created}}", image).Output()
		if err != nil {
			t.Fatal(err)
		}
		return string(out)
	}
	id := identity(first.Image)
	second := pyDepsBuild(t, root)
	if !reflect.DeepEqual(first, second) || identity(second.Image) != id {
		t.Fatal("real dependency image was not reused with identical provenance")
	}
	pyDepsRunChecks(t, root)
	p, err := project.Load(root)
	if err != nil {
		t.Fatal(err)
	}
	larger, err := countLarger(ctx, first.Image, "python", p, map[string]int{"Capacity": 2})
	if err != nil || !larger.OK || larger.States != 3 || larger.Depth != 3 {
		t.Fatalf("larger run could not import installed package: %#v %v", larger, err)
	}
	if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
		t.Fatal("real image build or execution rewrote application inputs")
	}
	pyDepsWrite(t, root, "deps/constraints.txt", "packaging==24.1\n")
	changed := pyDepsBuild(t, root)
	images = append(images, changed.Image)
	pyDepsAssertEnvironment(t, root, changed, "24.1")
	if changed.Recipe == first.Recipe || changed.Image == first.Image || changed.Artifacts[0].SHA256 == first.Artifacts[0].SHA256 {
		t.Fatal("real referenced-file change did not select a different dependency artifact")
	}
	pyDepsRunChecks(t, root)
	pyDepsWrite(t, root, "deps/constraints.txt", "packaging==0.0.0+invariant-does-not-exist\n")
	pyDepsAssertAcceptedWithPip(t, root)
	b, evidence, err := (Python{Image: toolchain.PythonImage}).Check(ctx, p)
	if err == nil || b.Passed || len(evidence.Traces) != 0 {
		t.Fatalf("impossible real requirement fell back to a Python execution: %#v %#v %v", b, evidence, err)
	}
	// This executes the full gate, including TLC, and checks provenance from
	// real installation in a receipt. Nagini is not needed for this fixture.
	pyDepsWrite(t, root, "deps/constraints.txt", "packaging==24.2\n")
	tc, err := toolchain.Ensure(ctx)
	if err != nil {
		t.Fatal(err)
	}
	r, err := Run(ctx, root, "", tc)
	if err != nil || r == nil || !r.Passed || r.Larger == nil || !r.Larger.Passed {
		t.Fatalf("real Python gate failed: %#v %v", r, err)
	}
	bJSON, _ := json.Marshal(r.Toolchain)
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(bJSON, &fields); err != nil {
		t.Fatal(err)
	}
	want, _ := json.Marshal(first)
	if string(fields["python_dependencies"]) != string(want) {
		t.Fatalf("real receipt lost the image recipe or resolved wheels: %s != %s", fields["python_dependencies"], want)
	}
}

// The fake implements the Docker boundary, not the pip acceptance oracle.
// Parser responses may be supplied verbatim to test the report consumer. The
// default response only transcribes the already accepted fixture shapes; the
// real suite forwards the exact production parser command to pinned Docker.
// It also persists an installation report per image and records execution.
type pyDepsCall struct {
	Kind           string
	Image          string
	Network        string
	Count          bool
	Command        []string
	Args           []string
	Workdir        string
	Entrypoint     string
	Platform       string
	Mounts         map[string]string
	ReadOnlyMounts map[string]bool
	Environment    map[string]string
	ParserReport   json.RawMessage
}

func pyDepsFakeDocker(t *testing.T) {
	t.Helper()
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
		pyDepsEnsurePinnedPipBase(t)
		t.Setenv("INVARIANT_PY_DEPS_REAL_DOCKER", pyDepsParserDocker)
	}
	dir := t.TempDir()
	binary, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	t.Setenv("INVARIANT_PY_DEPS_TEST_BINARY", binary)
	t.Setenv("INVARIANT_PY_DEPS_FAKE", dir)
	script := "#!/bin/sh\nINVARIANT_PY_DEPS_HELPER=1 exec \"$INVARIANT_PY_DEPS_TEST_BINARY\" \"$@\"\n"
	if err := os.WriteFile(filepath.Join(dir, "docker"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
}

// The injected bytes are exactly the stdout seen by production. No helper
// sanitizes options, fills missing fields or repairs malformed JSON for it.
func pyDepsSetParserRawReport(t *testing.T, report []byte) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "parser-report.json")
	if err := os.WriteFile(path, report, 0o644); err != nil {
		t.Fatal(err)
	}
	t.Setenv("INVARIANT_PY_DEPS_PARSER_REPORT", path)
}

func pyDepsSetParserReport(t *testing.T, report any) {
	t.Helper()
	b, err := json.Marshal(report)
	if err != nil {
		t.Fatal(err)
	}
	pyDepsSetParserRawReport(t, b)
}

// This is fixture transcription for the CLI double, not a second validator or
// an oracle for pip syntax. Adversarial reports are injected verbatim, and the
// real suite executes the production parser in the actual pinned base. Keeping
// this response independent of production's Go parser makes report-authority
// mutations meaningful without requiring host Python in the default suite.
func pyDepsFixtureParserReport(root string) ([]byte, error) {
	report := map[string]any{
		"schema": 1, "pip_version": "26.2.1", "root": "requirements.txt",
		"files": []any{}, "includes": []any{}, "requirements": []any{},
		"options": []any{}, "errors": []any{},
	}
	appendRow := func(key string, row map[string]any) { report[key] = append(report[key].([]any), row) }
	namePattern := regexp.MustCompile(`^([A-Za-z0-9][A-Za-z0-9._-]*)(?:\[([^]]+)\])?(.*)$`)
	commentPattern := regexp.MustCompile(`(^|[ \t])#.*$`)
	canonicalName := func(name string) string {
		return regexp.MustCompile(`[-_.]+`).ReplaceAllString(strings.ToLower(name), "-")
	}
	seen, active := map[string]bool{}, map[string]bool{}
	var visit func(string, bool) error
	visit = func(path string, constraint bool) error {
		if filepath.IsAbs(path) || path == ".." || strings.HasPrefix(path, "../") {
			return fmt.Errorf("fixture parser reference is outside project: %q", path)
		}
		role := fmt.Sprintf("%s:%t", path, constraint)
		if active[role] {
			return fmt.Errorf("fixture parser include cycle at %s", path)
		}
		active[role] = true
		defer delete(active, role)
		b, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(path)))
		if err != nil {
			return err
		}
		if !seen[role] {
			appendRow("files", map[string]any{"path": path, "constraint": constraint})
			seen[role] = true
		}
		body := strings.TrimPrefix(string(b), "\xef\xbb\xbf")
		body = strings.ReplaceAll(body, "\r\n", "\n")
		var continued string
		firstLine := 0
		for index, physical := range strings.Split(body, "\n") {
			if continued == "" {
				firstLine = index + 1
			}
			continued += physical
			if strings.HasSuffix(continued, "\\") {
				continued = strings.TrimSuffix(continued, "\\")
				continue
			}
			line := strings.TrimSpace(commentPattern.ReplaceAllString(continued, ""))
			continued = ""
			if line == "" {
				continue
			}
			var reference string
			var included, asConstraint bool
			for _, option := range []struct {
				prefix     string
				constraint bool
			}{{"--requirement", false}, {"--constraint", true}, {"-r", false}, {"-c", true}} {
				if !strings.HasPrefix(line, option.prefix) {
					continue
				}
				reference = strings.TrimPrefix(line, option.prefix)
				if strings.HasPrefix(reference, "=") {
					reference, _, _ = strings.Cut(strings.TrimPrefix(reference, "="), " ")
				} else {
					reference = strings.TrimLeft(reference, " \t")
				}
				included, asConstraint = true, option.constraint
				break
			}
			if included {
				if reference == "" {
					return fmt.Errorf("fixture parser found empty include in %s:%d", path, firstLine)
				}
				target := filepath.ToSlash(filepath.Join(filepath.Dir(path), reference))
				appendRow("includes", map[string]any{"source": path, "target": target, "value": reference, "constraint": asConstraint})
				if err := visit(target, asConstraint); err != nil {
					return err
				}
				continue
			}
			hashes := map[string][]string{}
			if boundary := strings.Index(line, " --hash="); boundary >= 0 {
				for _, token := range strings.Fields(line[boundary:]) {
					algorithm, digest, ok := strings.Cut(strings.TrimPrefix(token, "--hash="), ":")
					if !ok || !strings.HasPrefix(token, "--hash=") {
						return fmt.Errorf("unsupported fixture hash syntax %q", token)
					}
					hashes[algorithm] = append(hashes[algorithm], digest)
				}
				line = strings.TrimSpace(line[:boundary])
			}
			requirement, marker, _ := strings.Cut(line, ";")
			parts := namePattern.FindStringSubmatch(strings.TrimSpace(requirement))
			if parts == nil {
				return fmt.Errorf("unsupported fixture requirement %q", line)
			}
			extras := []string{}
			if parts[2] != "" {
				for _, extra := range strings.Split(parts[2], ",") {
					extras = append(extras, canonicalName(strings.TrimSpace(extra)))
				}
				sort.Strings(extras)
			}
			specifier := strings.ReplaceAll(strings.TrimSpace(parts[3]), " ", "")
			row := map[string]any{
				"source": path, "line": firstLine, "name": canonicalName(parts[1]),
				"extras": extras, "specifier": specifier, "marker": strings.TrimSpace(marker),
				"hashes": hashes, "constraint": constraint, "url": "", "link": "",
				"path": "", "archive": false, "editable": false, "options": []any{},
			}
			for _, suffix := range []string{".whl", ".tar.gz", ".tar.bz2", ".tar.xz", ".zip"} {
				if strings.HasSuffix(requirement, suffix) {
					row["name"], row["path"], row["archive"] = "", requirement, true
				}
			}
			appendRow("requirements", row)
		}
		return nil
	}
	if err := visit("requirements.txt", false); err != nil {
		return nil, err
	}
	return json.Marshal(report)
}

func pyDepsCalls(t *testing.T) []pyDepsCall {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "calls.jsonl"))
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		t.Fatal(err)
	}
	var calls []pyDepsCall
	if len(strings.TrimSpace(string(b))) == 0 {
		return nil
	}
	for _, line := range strings.Split(strings.TrimSpace(string(b)), "\n") {
		var call pyDepsCall
		if err := json.Unmarshal([]byte(line), &call); err != nil {
			t.Fatal(err)
		}
		calls = append(calls, call)
	}
	return calls
}

func pyDepsBuildCount(t *testing.T) int {
	t.Helper()
	n := 0
	for _, call := range pyDepsCalls(t) {
		if call.Kind == "build" {
			n++
		}
	}
	return n
}

func init() {
	if os.Getenv("INVARIANT_PY_DEPS_HELPER") == "1" {
		os.Exit(pyDepsDocker(os.Args[1:]))
	}
}

func pyDepsDocker(args []string) int {
	state := os.Getenv("INVARIANT_PY_DEPS_FAKE")
	fail := func(s string) int { fmt.Fprintln(os.Stderr, s); return 71 }
	log := func(c pyDepsCall) {
		f, err := os.OpenFile(filepath.Join(state, "calls.jsonl"), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
		if err != nil {
			panic(err)
		}
		b, _ := json.Marshal(c)
		f.Write(append(b, '\n'))
		f.Close()
	}
	reportPath := func(image string) string {
		return filepath.Join(state, strings.TrimPrefix(pyDepsHash([]byte(image)), "sha256:")+".json")
	}
	refPath := func(tag string) string {
		return filepath.Join(state, strings.TrimPrefix(pyDepsHash([]byte(tag)), "sha256:")+".ref")
	}
	resolve := func(image string) string {
		if id, err := os.ReadFile(refPath(image)); err == nil {
			return string(id)
		}
		return image
	}
	cache := func(image string) string { return reportPath(resolve(image)) }
	// Immediately before Docker reads the first report, a concurrent builder
	// publishes another resolution under the same tag. An immutable ID still
	// addresses the original report. Existence-only probes are not selections.
	replaceTag := func(id string) error {
		if os.Getenv("INVARIANT_PY_DEPS_REPLACE_TAG") != "1" {
			return nil
		}
		marker := filepath.Join(state, "selected")
		if _, err := os.Stat(marker); err == nil {
			return nil
		}
		report, err := os.ReadFile(reportPath(id))
		if err != nil {
			return err
		}
		if err := os.WriteFile(marker, []byte(id), 0o644); err != nil {
			return err
		}
		log(pyDepsCall{Kind: "selection", Image: id})
		replacement := strings.ReplaceAll(string(report), "24.2", "24.1")
		replacement = strings.ReplaceAll(replacement, strings.Repeat("a", 64), strings.Repeat("b", 64))
		other := pyDepsHash([]byte("concurrent build\n" + replacement))
		if err := os.WriteFile(reportPath(other), []byte(replacement), 0o644); err != nil {
			return err
		}
		refs, err := filepath.Glob(filepath.Join(state, "*.ref"))
		if err != nil {
			return err
		}
		for _, ref := range refs {
			if err := os.WriteFile(ref, []byte(other), 0o644); err != nil {
				return err
			}
		}
		return nil
	}
	if len(args) == 0 {
		return fail("missing docker command")
	}
	log(pyDepsCall{Kind: "command", Image: strings.Join(args, " ")})
	switch args[0] {
	case "info", "rm":
		return 0
	case "image":
		if len(args) < 3 || args[1] != "inspect" {
			return fail("unexpected image command")
		}
		img := args[len(args)-1]
		id := pyDepsHash([]byte(img))
		if img != toolchain.PythonImage && img != "accept-java" && !strings.HasPrefix(img, "invariant-nagini:") {
			if _, err := os.Stat(cache(img)); err != nil {
				return 1
			}
			id = resolve(img)
		}
		format := ""
		for i, a := range args {
			if (a == "--format" || a == "-f") && i+1 < len(args) {
				format = args[i+1]
			} else if strings.HasPrefix(a, "--format=") {
				format = strings.TrimPrefix(a, "--format=")
			}
		}
		switch {
		case strings.Contains(format, ".Id"):
			fmt.Println(id)
		case strings.Contains(format, "json ."):
			fmt.Printf("{\"Id\":%q,\"Os\":\"linux\",\"Architecture\":\"amd64\"}\n", id)
		default:
			fmt.Printf("[{\"Id\":%q,\"Os\":\"linux\",\"Architecture\":\"amd64\"}]\n", id)
		}
		return 0
	case "build":
		tag, iidfile := "", ""
		for i, arg := range args {
			if (arg == "-t" || arg == "--tag") && i+1 < len(args) {
				tag = args[i+1]
			}
			if arg == "--iidfile" && i+1 < len(args) {
				iidfile = args[i+1]
			}
		}
		if tag == "" {
			return fail("build has no tag")
		}
		log(pyDepsCall{Kind: "build", Image: tag})
		if os.Getenv("INVARIANT_PY_DEPS_FAILURE") == "install" {
			return fail("ERROR: No matching distribution found for impossible-invariant-dependency")
		}
		contextDir := args[len(args)-1]
		dest := filepath.Join(state, "context")
		os.RemoveAll(dest)
		err := filepath.WalkDir(contextDir, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			rel, _ := filepath.Rel(contextDir, path)
			if d.IsDir() {
				return os.MkdirAll(filepath.Join(dest, rel), 0o755)
			}
			b, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			return os.WriteFile(filepath.Join(dest, rel), b, 0o644)
		})
		if err != nil {
			return fail("copying dependency build context: " + err.Error())
		}
		constraints, err := os.ReadFile(filepath.Join(dest, "canonical", "constraints.txt"))
		if err != nil {
			return fail("canonical constraints were not staged")
		}
		if _, err := os.ReadFile(filepath.Join(dest, "canonical", "requirements.txt")); err != nil {
			return fail("canonical requirements were not staged")
		}
		version, hash := "24.2", strings.Repeat("a", 64)
		if strings.Contains(string(constraints), "24.1") {
			version, hash = "24.1", strings.Repeat("b", 64)
		}
		if os.Getenv("INVARIANT_PY_DEPS_RESOLUTION") == "24.1" {
			version, hash = "24.1", strings.Repeat("b", 64)
		}
		report := fmt.Sprintf(`{"version":"1","pip_version":"25.0","install":[{"download_info":{"url":"https://files.pythonhosted.org/packages/packaging-%s-py3-none-any.whl","archive_info":{"hashes":{"sha256":"%s"}}},"is_direct":false,"is_yanked":false,"requested":true,"metadata":{"name":"packaging","version":"%s"}}],"environment":{"implementation_name":"cpython","implementation_version":"3.13.15","os_name":"posix","platform_machine":"x86_64","platform_python_implementation":"CPython","platform_system":"Linux","python_full_version":"3.13.15","python_version":"3.13","sys_platform":"linux"}}`, version, hash, version)
		id := pyDepsHash([]byte(tag + "\n" + report))
		if err := os.WriteFile(reportPath(id), []byte(report), 0o644); err != nil {
			return fail(err.Error())
		}
		if err := os.WriteFile(refPath(tag), []byte(id), 0o644); err != nil {
			return fail(err.Error())
		}
		if iidfile != "" {
			if err := os.WriteFile(iidfile, []byte(id), 0o644); err != nil {
				return fail(err.Error())
			}
		}
		fmt.Println(id)
		return 0
	case "run":
		env, volumes := map[string]string{}, map[string]string{}
		readonlyVolumes := map[string]bool{}
		image, network, workdir, entrypoint, platform := "", "", "", "", ""
		var command []string
		mount := func(value string) {
			var source, target string
			readonly := false
			for _, part := range strings.Split(value, ",") {
				key, v, _ := strings.Cut(part, "=")
				switch key {
				case "source", "src":
					source = v
				case "target", "dst", "destination":
					target = v
				case "readonly", "ro":
					readonly = v == "" || v == "true" || v == "1"
				}
			}
			if source != "" && target != "" {
				volumes[target], readonlyVolumes[target] = source, readonly
			}
		}
		for i := 1; i < len(args); i++ {
			a := args[i]
			if a == "--rm" || a == "--read-only" || a == "--pull=never" || a == "-i" || a == "--interactive" {
				continue
			}
			if option, value, ok := strings.Cut(a, "="); ok {
				switch option {
				case "--platform":
					platform = value
					continue
				case "--workdir":
					workdir = value
					continue
				case "--entrypoint":
					entrypoint = value
					continue
				case "--env":
					key, v, _ := strings.Cut(value, "=")
					env[key] = v
					continue
				}
			}
			if strings.HasPrefix(a, "--network=") {
				network = strings.TrimPrefix(a, "--network=")
				continue
			}
			if strings.HasPrefix(a, "--mount=") {
				mount(strings.TrimPrefix(a, "--mount="))
				continue
			}
			switch a {
			case "--name", "--network", "--platform", "--memory", "--pids-limit", "-w", "--workdir", "--user", "--entrypoint", "--cap-drop", "--security-opt", "--tmpfs", "--pull", "--mount", "-e", "--env", "-v", "--volume":
				if i+1 >= len(args) {
					return fail("missing Docker option value")
				}
				i++
				v := args[i]
				switch a {
				case "--network":
					network = v
				case "--platform":
					platform = v
				case "-w", "--workdir":
					workdir = v
				case "--entrypoint":
					entrypoint = v
				case "--mount":
					mount(v)
				case "-e", "--env":
					k, value, _ := strings.Cut(v, "=")
					env[k] = value
				case "-v", "--volume":
					parts := strings.Split(v, ":")
					if len(parts) >= 2 {
						volumes[parts[1]] = parts[0]
						readonlyVolumes[parts[1]] = len(parts) >= 3 && strings.Contains(","+parts[2]+",", ",ro,")
					}
				}
				continue
			}
			if strings.HasPrefix(a, "-") {
				return fail("unrecognized Docker option " + a)
			}
			image, command = a, args[i+1:]
			break
		}
		if network != "none" {
			return fail("execution or metadata inspection has network access")
		}
		if image == toolchain.PythonImage && env["DRIVER"] == "" {
			call := pyDepsCall{Kind: "parser", Image: image, Network: network,
				Command: command, Args: args, Workdir: workdir, Entrypoint: entrypoint,
				Platform: platform, Mounts: volumes, ReadOnlyMounts: readonlyVolumes, Environment: env}
			root := ""
			for target, source := range volumes {
				if !readonlyVolumes[target] {
					log(call)
					return fail("pip parser received a writable host mount")
				}
				if workdir == target || strings.HasPrefix(workdir, strings.TrimSuffix(target, "/")+"/") {
					log(call)
					return fail("pip parser cwd contains mounted application inputs")
				}
				if _, err := os.Stat(filepath.Join(source, "requirements.txt")); err == nil {
					if root != "" {
						log(call)
						return fail("pip parser has ambiguous project mounts")
					}
					root = source
				}
			}
			effective := append([]string(nil), command...)
			if entrypoint != "" {
				effective = append([]string{entrypoint}, effective...)
			}
			if root == "" || !filepath.IsAbs(workdir) || platform != "linux/amd64" ||
				len(effective) < 2 || !filepath.IsAbs(effective[0]) || !strings.HasPrefix(filepath.Base(effective[0]), "python") {
				log(call)
				return fail("pip parser requires the pinned platform, read-only project, clean cwd and absolute Python")
			}
			isolated := false
			for _, arg := range effective[1:] {
				if arg == "-I" {
					isolated = true
				}
				if arg == "-c" || arg == "-m" || !strings.HasPrefix(arg, "-") {
					break
				}
			}
			if !isolated {
				log(call)
				return fail("pip parser Python is not isolated with -I")
			}
			for _, key := range []string{"INVARIANT_ACCEPT_CREDENTIAL", "PIP_INDEX_URL", "PYTHONPATH", "PYTHONHOME"} {
				if _, ok := env[key]; ok {
					log(call)
					return fail("host configuration passed to pip parser: " + key)
				}
			}
			if diagnostic := os.Getenv("INVARIANT_PY_DEPS_PARSER_FAILURE"); diagnostic != "" {
				log(call)
				return fail(diagnostic)
			}
			var report []byte
			var err error
			switch {
			case os.Getenv("INVARIANT_PY_DEPS_PARSER_REPORT") != "":
				report, err = os.ReadFile(os.Getenv("INVARIANT_PY_DEPS_PARSER_REPORT"))
			case os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1":
				realDocker := os.Getenv("INVARIANT_PY_DEPS_REAL_DOCKER")
				if realDocker == "" || !filepath.IsAbs(realDocker) || filepath.Dir(realDocker) == state {
					log(call)
					return fail("real production-parser acceptance has no captured Docker executable")
				}
				parserArgs := append([]string(nil), args...)
				// Replay the actual production helper against adversarial files
				// which the stricter host preflight normally rejects first. The
				// helper, container restrictions and report consumer are unchanged;
				// only the host source of the project mount changes in this
				// explicit real-suite hook. Logged Args remain the production CLI.
				if project := os.Getenv("INVARIANT_PY_DEPS_PARSER_PROJECT"); project != "" {
					replaced := false
					for i := 1; i < len(parserArgs); i++ {
						option, value, joined := strings.Cut(parserArgs[i], "=")
						if option != "-v" && option != "--volume" && option != "--mount" {
							continue
						}
						if !joined {
							if i+1 >= len(parserArgs) {
								break
							}
							i++
							value = parserArgs[i]
						}
						before := value
						if option == "--mount" {
							parts := strings.Split(value, ",")
							for index, part := range parts {
								key, source, _ := strings.Cut(part, "=")
								if (key == "source" || key == "src") && source == root {
									parts[index] = key + "=" + project
								}
							}
							value = strings.Join(parts, ",")
						} else if strings.HasPrefix(value, root+":") {
							value = project + strings.TrimPrefix(value, root)
						}
						if value != before {
							replaced = true
							parserArgs[i] = value
							if joined {
								parserArgs[i] = option + "=" + value
							}
						}
					}
					if !replaced {
						log(call)
						return fail("production-parser replay did not find the project mount")
					}
				}
				cmd := exec.Command(realDocker, parserArgs...)
				cmd.Stderr = os.Stderr
				report, err = cmd.Output()
			default:
				report, err = pyDepsFixtureParserReport(root)
			}
			if json.Valid(report) {
				call.ParserReport = json.RawMessage(report)
			}
			log(call)
			if err != nil {
				return fail(fmt.Sprintf("pip parser command failed: %v\n%s", err, report))
			}
			fmt.Println(string(report))
			return 0
		}
		if image == "accept-java" {
			count := 2
			cfg, _ := os.ReadFile(filepath.Join(volumes["/work"], "Invariant.cfg"))
			if strings.Contains(string(cfg), "CONSTANT Capacity = 2") {
				count = 3
			}
			message := func(code int, body string) {
				fmt.Printf("@!@!@STARTMSG %d:0 @!@!@\n%s\n@!@!@ENDMSG %d @!@!@\n", code, body, code)
			}
			message(2262, "TLC2 Version 2.19")
			message(2193, "Model checking completed. No error has been found.")
			message(2199, fmt.Sprintf("%d states generated, %d distinct states found, 0 states left on queue.", count, count))
			message(2194, fmt.Sprintf("The depth of the complete state graph search is %d.", count))
			return 0
		}
		if strings.HasPrefix(image, "invariant-nagini:") {
			log(pyDepsCall{Kind: "nagini", Image: image, Network: network})
			fmt.Println("Verification successful")
			return 0
		}
		if env["DRIVER"] != "" {
			count := env["INVARIANT_COUNT"] != ""
			log(pyDepsCall{Kind: "application", Image: image, Network: network, Count: count, Command: command,
				Args: args, Workdir: workdir, Entrypoint: entrypoint, Platform: platform,
				Mounts: volumes, ReadOnlyMounts: readonlyVolumes, Environment: env})
			for _, key := range []string{"INVARIANT_ACCEPT_CREDENTIAL", "PIP_INDEX_URL"} {
				if _, present := env[key]; present {
					return fail("host variable passed to application: " + key)
				}
			}
			_, requirementsErr := os.Stat(filepath.Join(volumes["/src"], "requirements.txt"))
			if requirementsErr == nil && image == toolchain.PythonImage {
				fmt.Print("@@invariant compile=0\nModuleNotFoundError: No module named 'packaging'\n@@invariant test=1\n@@invariant conform=1\n")
				return 0
			}
			if image != toolchain.PythonImage {
				if _, err := os.Stat(cache(image)); err != nil {
					return fail("application image was never built")
				}
			}
			if count {
				os.WriteFile(filepath.Join(volumes["/out"], "count.json"), []byte(`{"states":3,"depth":3}`), 0o644)
				fmt.Println("@@invariant count=0")
			} else {
				os.WriteFile(filepath.Join(volumes["/out"], "traces.json"), []byte(`{"traces":[[{"n":0},{"n":1}]]}`), 0o644)
				fmt.Print("@@invariant compile=0\nRan 1 test\n@@invariant test=0\n@@invariant conform=0\n")
			}
			return 0
		}
		// Metadata reads may use cat or a Python wrapper; return the image's
		// pip report, never the currently available index resolution.
		if len(command) == 0 {
			return fail("missing image metadata command")
		}
		id := resolve(image)
		if err := replaceTag(id); err != nil {
			return fail(err.Error())
		}
		report, err := os.ReadFile(cache(image))
		if err != nil {
			return fail("no pip installation report")
		}
		log(pyDepsCall{Kind: "evidence", Image: image, Network: network, Command: command,
			Args: args, Workdir: workdir, Entrypoint: entrypoint, Platform: platform,
			Mounts: volumes, ReadOnlyMounts: readonlyVolumes, Environment: env})
		switch os.Getenv("INVARIANT_PY_DEPS_FAILURE") {
		case "missing report":
			return fail("no pip installation report")
		case "malformed report":
			report = []byte("not a pip report")
		case "missing artifact hash":
			report = []byte(strings.ReplaceAll(string(report), `"sha256":`, `"untrusted":`))
		}
		fmt.Println(string(report))
		return 0
	default:
		return fail("unexpected docker command: " + strings.Join(args, " "))
	}
}

sources.internal/verify/python_encoding_accept_t:
package verify

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/toolchain"
)

// Validate raw bytes before BOM removal, newline normalization, comments,
// continuations or include parsing. Pip discovers an encoding from its first
// two raw LF-delimited lines; accepting a declaration after normalizing CR
// gives the validator a different language from the network-enabled installer.
// Every effective requirements/constraints file therefore uses valid UTF-8,
// an optional leading UTF-8 BOM, LF/CRLF only, and no encoding declaration
// in any comment; package names such as geocoding are not declarations.
// The existing splitlines-separator rejection remains in force.
//
// The default layer captures the recipe and checks canonical installer bytes
// plus both original and canonical provenance. The opt-in layer actually
// executes that generated recipe:
// INVARIANT_PYTHON_DEPS_REAL=1 go test ./internal/verify -run '^TestPythonDependenciesAcceptUTF8Inputs$' -count=1 -timeout 30m
func TestPythonDependenciesAcceptUTF8Inputs(t *testing.T) {
	var canonicalUTF8 map[string]string
	for _, tc := range []struct {
		name    string
		bom     string
		newline string
	}{
		{"LF", "", "\n"},
		{"CRLF", "", "\r\n"},
		{"BOM LF", "\xef\xbb\xbf", "\n"},
		{"BOM CRLF", "\xef\xbb\xbf", "\r\n"},
		{"mixed LF and CRLF", "\xef\xbb\xbf", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			root := pyDepsFixture(t)
			inputs := []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"}
			for _, filename := range inputs {
				b, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(filename)))
				if err != nil {
					t.Fatal(err)
				}
				// Non-ASCII comments establish UTF-8 acceptance, rather than
				// merely the ASCII subset. A unique comment forces real builds.
				body := fmt.Sprintf("# café λ 日本語 %s %d\n", tc.name, time.Now().UnixNano()) + string(b)
				var encoded strings.Builder
				encoded.WriteString(tc.bom)
				for i, line := range strings.SplitAfter(body, "\n") {
					newline := tc.newline
					if newline == "" {
						newline = "\n"
						if i%2 == 0 {
							newline = "\r\n"
						}
					}
					encoded.WriteString(strings.ReplaceAll(line, "\n", newline))
				}
				pyDepsWrite(t, root, filename, encoded.String())
			}
			before := pyDepsFiles(t, root)
			t.Run("generated recipe contract", func(t *testing.T) {
				pyDepsFakeDocker(t)
				first := pyDepsBuild(t, root)
				pyDepsAssertRecipeEnvironment(t, root, first, inputs)
				canonical := pyDepsAssertCanonicalStaging(t, root, first, inputs)
				if canonicalUTF8 == nil {
					canonicalUTF8 = canonical
				} else if !reflect.DeepEqual(canonical, canonicalUTF8) {
					t.Fatalf("BOM, newline style or comments changed canonical installation inputs: got=%#v want=%#v", canonical, canonicalUTF8)
				}
				if second := pyDepsBuild(t, root); !reflect.DeepEqual(first, second) || pyDepsBuildCount(t) != 1 {
					t.Fatalf("accepted raw input bytes did not reuse their environment: first=%#v second=%#v", first, second)
				}
			})
			if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
				t.Run("execute generated recipe", func(t *testing.T) {
					pyDepsRequireRealDocker(t)
					env := pyDepsBuild(t, root)
					pyDepsCleanupRecipeImage(t, env.Image)
					pyDepsAssertRecipeEnvironment(t, root, env, inputs)
					pyDepsRunChecks(t, root)
				})
			}
			if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
				t.Fatal("accepting UTF-8 inputs rewrote their bytes")
			}
		})
	}
}

type pyDepsInvalidInputCase struct {
	name string
	raw  string
}

func TestPythonDependenciesRejectInvalidUTF8(t *testing.T) {
	pyDepsRejectInvalidInputs(t, []pyDepsInvalidInputCase{
		{"Latin-1 comment", "# caf\xe9\npackaging==24.2\n"},
		{"stray continuation byte", "# \x80\npackaging==24.2\n"},
		{"truncated multibyte sequence", "# \xe2\x82\npackaging==24.2\n"},
		{"overlong LF", "# \xc0\x8a--no-binary :all:\npackaging==24.2\n"},
		{"UTF-8 surrogate", "# \xed\xa0\x80\npackaging==24.2\n"},
		{"beyond Unicode range", "# \xf4\x90\x80\x80\npackaging==24.2\n"},
		{"invalid after valid BOM", "\xef\xbb\xbf# \xff\npackaging==24.2\n"},
		{"UTF-16 BOM", "\xff\xfe#\x00 \x00x\x00\n\x00"},
	})
}

func TestPythonDependenciesRejectBareCR(t *testing.T) {
	pyDepsRejectInvalidInputs(t, []pyDepsInvalidInputCase{
		{"CR only lines", "# ordinary comment\rpackaging==24.2\r"},
		{"inside comment", "# first\r# second\npackaging==24.2\n"},
		{"trailing CR", "packaging==24.2\n# end\r"},
		{"repeated CR before LF", "# comment\r\r\npackaging==24.2\n"},
		{"before continuation", "# comment \\\r# continued\npackaging==24.2\n"},
		{"mixed valid and bare CR", "# valid\r\n# invalid\r# after\npackaging==24.2\n"},
		{"after BOM", "\xef\xbb\xbf# first\r# second\npackaging==24.2\n"},
	})
}

func TestPythonDependenciesRejectEncodingDeclarations(t *testing.T) {
	pyDepsRejectInvalidInputs(t, []pyDepsInvalidInputCase{
		{"UTF-8 first line", "# coding: utf-8\npackaging==24.2\n"},
		{"equals second line", "# requirements\n# coding=utf-8\npackaging==24.2\n"},
		{"Emacs declaration", "# -*- coding: utf-8 -*-\npackaging==24.2\n"},
		{"Vim declaration", "# vim: set fileencoding=utf-8 :\npackaging==24.2\n"},
		{"third line", "# one\n# two\n# coding: unicode_escape\npackaging==24.2\n"},
		{"late declaration", "packaging==24.2\n\n# ordinary\n# coding: utf-8\n"},
		{"trailing comment", "packaging==24.2 # coding: utf-8\n"},
		{"CRLF declaration", "# ordinary\r\n# coding: utf-8\r\npackaging==24.2\r\n"},
		{"BOM declaration", "\xef\xbb\xbf# coding: utf-8\npackaging==24.2\n"},
		{"non UTF-8 declaration", "# coding: latin-1\npackaging==24.2\n"},
		{"unicode escape hidden source option", "# coding: unicode_escape\n# \\u000a--no-binary :all:\npackaging\n"},
		{"unicode escape hidden index", "# coding=unicode_escape\n# \\u000a--index-url https://example.invalid/simple\npackaging\n"},
	})
}

func TestPythonDependenciesRejectEncodingDeclarationExploit(t *testing.T) {
	// Exact raw bytes from the #243 review: two bare CR bytes, then a
	// literal backslash-u sequence (not an already-decoded LF). Pip finds
	// coding: in its first raw LF-delimited line and unicode_escape turns
	// that sequence into an active option during the network-enabled build.
	const review = "# a\r# b\r# coding: unicode_escape\n# \\u000a--no-binary :all:\npackaging\n"
	pyDepsRejectInvalidInputs(t, []pyDepsInvalidInputCase{
		{"review raw bytes", review},
		{"review index redirection", strings.ReplaceAll(review, "--no-binary :all:", "--index-url https://example.invalid/simple")},
	})
}

// Encoding and strict grammar restrictions apply equally to the root, a
// recursively referenced requirement and a recursively referenced constraint.
// The Docker double records every CLI entry, including image inspection.
func pyDepsRejectInvalidInputs(t *testing.T, cases []pyDepsInvalidInputCase) {
	t.Helper()
	pyDepsFakeDocker(t)
	for _, tc := range cases {
		for _, filename := range []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"} {
			t.Run(tc.name+"/"+filename, func(t *testing.T) {
				root := pyDepsFixture(t)
				pyDepsWrite(t, root, filename, tc.raw)
				before := pyDepsFiles(t, root)
				if recipe, err := toolchain.PythonDepsRecipe(root); err == nil {
					t.Errorf("unsafe dependency input accepted in %s: recipe=%q input=%q", filename, recipe, tc.raw)
				}
				ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
				defer cancel()
				if env, err := toolchain.PythonDepsImage(ctx, root); err == nil || env != nil {
					t.Errorf("unsafe dependency input reached image selection: env=%#v error=%v", env, err)
				}
				if calls := pyDepsCalls(t); len(calls) != 0 {
					t.Fatalf("raw input validation must precede every Docker invocation: calls=%#v", calls)
				}
				if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
					t.Fatal("rejection rewrote dependency inputs")
				}
			})
		}
	}
}

sources.internal/verify/python_libraries_accept_:
package verify

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/toolchain"
)

// The Docker double checks the production recipe and launcher contract; it
// cannot prove that wheel installation or Python startup is safe. The real
// layer executes that generated recipe and installs independently hostile
// wheels with real pip, using the exact target parsed from that recipe. Each
// wheel has a working takeover control, but the gate must retain genuine
// receipt evidence and both passing and failing ordinary/larger results.
//
// INVARIANT_PYTHON_DEPS_REAL=1 go test ./internal/verify -run '^TestPythonDependenc' -count=1 -timeout 30m
func TestPythonDependenciesTreatInstalledDistributionsAsLibraries(t *testing.T) {
	for _, vector := range []string{"python", "pth", "sitecustomize", "usercustomize", "gate_modules"} {
		t.Run(vector, func(t *testing.T) {
			root := pyDepsFixture(t)
			pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("# library regression %s %d\n-r deps/application.txt\n", vector, time.Now().UnixNano()))
			var recipe string
			t.Run("recipe and launcher contract", func(t *testing.T) {
				pyDepsFakeDocker(t)
				tc := toolchain.Toolchain{PythonImage: toolchain.PythonImage, JavaImage: "accept-java", TLCJar: filepath.Join(t.TempDir(), "tlc.jar")}
				r, err := Run(context.Background(), root, "", tc)
				pyDepsRequireGateChecks(t, r, err)
				staged := pyDepsFiles(t, filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "context"))
				recipe = staged["Dockerfile"]
				target := pyDepsRecipeLibraryTarget(t, recipe)
				pyDepsAssertIsolatedRecipe(t, recipe)
				for _, line := range strings.Split(recipe, "\n") {
					words := strings.Fields(line)
					if len(words) == 0 || !strings.EqualFold(words[0], "ENV") {
						continue
					}
					if strings.Contains(line, "PYTHONPATH") || strings.Contains(line, "PYTHONHOME") ||
						(regexp.MustCompile(`(?:^|\s)PATH(?:=|\s)`).MatchString(line) && strings.Contains(line, target)) {
						t.Fatalf("dependency target must not enter interpreter startup or command lookup through image ENV: %s", line)
					}
				}
				var ordinary, larger, evidence bool
				for _, call := range pyDepsCalls(t) {
					if call.Kind != "application" && call.Kind != "evidence" {
						continue
					}
					command := append([]string(nil), call.Command...)
					if call.Entrypoint != "" {
						command = append([]string{call.Entrypoint}, command...)
					}
					if len(command) == 0 || !pyDepsTrustedExecutable(command[0]) {
						t.Fatalf("gate launcher/evidence reader can be installed by a wheel: %#v", call)
					}
					for _, key := range []string{"PATH", "PYTHONPATH", "PYTHONHOME"} {
						for _, dir := range strings.Split(call.Environment[key], ":") {
							if dir == target || strings.HasPrefix(dir, target+"/") {
								t.Fatalf("dependency library enters startup/command lookup through %s: %#v", key, call)
							}
						}
					}
					if call.Kind == "evidence" {
						evidence = true
						continue
					}
					ordinary, larger = ordinary || !call.Count, larger || call.Count
					if path.Base(command[0]) != "sh" || len(command) != 3 || command[1] != "-c" {
						t.Fatalf("unexpected check launcher: %#v", command)
					}
					pyDepsRequireTrustedHelpers(t, command[2])
					pyDepsRequireIsolatedApplicationPython(t, command[2])
				}
				if !ordinary || !larger || !evidence {
					t.Fatalf("missing library isolation boundary: ordinary=%t larger=%t evidence=%t", ordinary, larger, evidence)
				}
			})
			if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
				t.Run("real installed wheel cannot take over", func(t *testing.T) {
					pyDepsRealTrustedCommands(t, root, recipe, vector)
				})
			}
		})
	}
}

func pyDepsRequireIsolatedApplicationPython(t *testing.T, script string) {
	t.Helper()
	python := regexp.MustCompile(`^python(?:[0-9]+(?:\.[0-9]+)*)?$`)
	seen := false
	for _, command := range pyDepsShellCommands(t, script) {
		if strings.TrimSpace(command) == "exec 2>&1" {
			continue
		}
		args := pyDepsRecipeArguments(t, command)
		if len(args) == 0 {
			continue
		}
		i := 0
		if args[i] == "exec" {
			i++
		}
		if i < len(args) && path.Base(args[i]) == "timeout" {
			i++
			for i < len(args) && strings.HasPrefix(args[i], "-") {
				i++
			}
			i++ // duration, then the child executable
		}
		if i >= len(args) || !python.MatchString(path.Base(args[i])) {
			continue
		}
		seen = true
		if path.Dir(args[i]) != "/usr/local/bin" || !pyDepsTrustedExecutable(args[i]) {
			t.Fatalf("application Python is not the pinned base interpreter: %q in %s", args[i], script)
		}
		isolated := false
		for _, flag := range args[i+1:] {
			if flag == "-I" {
				isolated = true
			}
			if flag == "-c" || flag == "-m" || !strings.HasPrefix(flag, "-") {
				break
			}
		}
		if !isolated {
			t.Fatalf("application Python can run startup hooks or load startup paths: %s", script)
		}
	}
	if !seen || strings.Contains(script, "addsitedir") {
		t.Fatalf("checks must start trusted isolated Python and add libraries without processing site hooks: %s", script)
	}
}

// Split only outside quotes, preserving multi-line Python -c programs as a
// single argument rather than treating their statements as shell commands.
func pyDepsShellCommands(t *testing.T, script string) []string {
	t.Helper()
	var commands []string
	var current strings.Builder
	var quote rune
	escaped := false
	flush := func() {
		if command := strings.TrimSpace(current.String()); command != "" {
			commands = append(commands, command)
		}
		current.Reset()
	}
	for i, r := range script {
		switch {
		case escaped:
			current.WriteRune(r)
			escaped = false
		case r == '\\' && quote != '\'':
			current.WriteRune(r)
			escaped = true
		case quote != 0:
			current.WriteRune(r)
			if r == quote {
				quote = 0
			}
		case r == '\'' || r == '"':
			current.WriteRune(r)
			quote = r
		case r == '\n' || r == ';' || r == '|' || (r == '&' && ((i > 0 && script[i-1] == '&') || (i+1 < len(script) && script[i+1] == '&'))):
			flush()
		default:
			current.WriteRune(r)
		}
	}
	if quote != 0 || escaped {
		t.Fatalf("unterminated check launcher quote or escape: %s", script)
	}
	flush()
	return commands
}

func pyDepsShadowNegativeControl(t *testing.T, ctx context.Context, docker func(...string) []byte, image, target, reportPath, vector string) {
	t.Helper()
	base := []string{"run", "--rm", "--network", "none", "--platform", "linux/amd64", "-w", "/tmp"}
	if vector == "commands" {
		unsafePath := "PATH=" + path.Join(target, "bin") + ":/usr/local/bin:/usr/bin:/bin"
		var forged struct {
			Install []any `json:"install"`
		}
		out := docker(append(append([]string(nil), base...), "-e", unsafePath, image, "cat", reportPath)...)
		if err := json.Unmarshal(out, &forged); err != nil || forged.Install == nil || len(forged.Install) != 0 {
			t.Fatalf("installed cat did not forge empty evidence when enabled on PATH: %s %v", out, err)
		}
		for _, name := range []string{"sh", "timeout"} {
			args := append(append([]string(nil), base...), "-e", unsafePath, image, name)
			out, err := exec.CommandContext(ctx, "docker", args...).CombinedOutput()
			if err == nil || !strings.Contains(string(out), "INVARIANT_SHADOW_"+name) {
				t.Fatalf("installed %s did not intercept unsafe PATH: error=%v\n%s", name, err, out)
			}
		}
		return
	}
	var args []string
	switch vector {
	case "python":
		args = append(base, image, path.Join(target, "bin", "python"), "-c", "raise AssertionError('wrapped interpreter ran application')")
	case "pth":
		args = append(base, image, "/usr/local/bin/python", "-I", "-c", "import site, sys; site.addsitedir(sys.argv[1]); raise AssertionError('inactive pth fixture')", target)
	case "sitecustomize", "usercustomize":
		args = append(base, "-e", "PYTHONPATH="+target, image, "/usr/local/bin/python", "-c", "raise AssertionError('inactive startup module fixture')")
	case "gate_modules":
		args = append(base, image, "/usr/local/bin/python", "-I", "-c", "import sys; sys.path.insert(0, sys.argv[1]); import unittest; raise AssertionError('inactive runner replacement fixture')", target)
	default:
		t.Fatalf("unknown hostile wheel vector %q", vector)
	}
	out := docker(args...)
	if !strings.Contains(string(out), "INVARIANT_SHADOW_"+vector) || !strings.Contains(string(out), "@@invariant test=0") {
		t.Fatalf("hostile %s did not forge success with the unsafe startup control: %s", vector, out)
	}
}

func pyDepsAssertImportOnlyImage(t *testing.T, docker func(...string) []byte, image, target string) {
	t.Helper()
	const probe = `import builtins, importlib.util, os, site, sys
target = sys.argv[1]
assert os.path.realpath(target) not in [os.path.realpath(p) for p in sys.path if p]
assert os.path.realpath(target) not in [os.path.realpath(p) for p in site.getsitepackages() + [site.getusersitepackages()]]
assert importlib.util.find_spec("invariant_gate_shadow") is None
assert not hasattr(builtins, "INVARIANT_IMPORTED_LIBRARY")
# This raw path update imports no dependency and processes no .pth files.
sys.path.append(target)
assert not hasattr(builtins, "INVARIANT_IMPORTED_LIBRARY")
import invariant_gate_shadow
assert builtins.INVARIANT_IMPORTED_LIBRARY == "import-only"
from packaging.version import Version
assert Version("1.9") < Version("1.10")
print("INVARIANT_IMPORT_ONLY_OK")
`
	out := docker("run", "--rm", "--network", "none", "--platform", "linux/amd64", "--read-only", "-w", "/tmp", image, "/usr/local/bin/python", "-I", "-c", probe, target)
	if string(out) != "INVARIANT_IMPORT_ONLY_OK" {
		t.Fatalf("installed wheel ran at startup or failed explicit import: %s", out)
	}
}

sources.internal/verify/python_parser_accept_tes:
package verify

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"sort"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/toolchain"
)

// The shared canonical-staging assertion calls pyDepsAssertPipParserMatches,
// so the real parser checks each accepted fixture at its existing test site,
// including the UTF-8, traversal, canonicalization and semantic regressions.
// Recipe-only acceptance sites use pyDepsAssertAcceptedWithPip to capture the
// generated files without installing synthetic hashes or nonexistent packages.
//
// With INVARIANT_PYTHON_DEPS_REAL=1 the Docker double forwards production's
// parser invocation unchanged to real Docker and captures its actual report.
// The comparison checks that report and its followed-file closure against
// independent pinned pip observations, then compares its requirements with
// production's canonical files. It also retains matching refusal of rejected
// option-whitespace fixtures and deliberately corrupted-result controls.
// No host Python, replacement parser, resolver or installation is involved.
func TestPythonDependenciesMatchPinnedPipParser(t *testing.T) {
	firstHash, secondHash := strings.Repeat("a", 64), strings.Repeat("b", 64)
	for _, tc := range []struct {
		name         string
		files        map[string]string
		requirements []string
		constraints  []string
	}{
		{
			name: "whitespace extras versions and markers",
			files: map[string]string{
				"requirements.txt": "# ordinary UTF-8 café comment\n\tpackaging >=24, <25  # requested\nrequests[security,socks]==2.32.3 ; python_version < '0' and (os_name == 'posix' or sys_platform == 'linux')\n",
			},
			requirements: []string{"packaging>=24,<25", "requests[security,socks]==2.32.3; python_version < '0' and (os_name == 'posix' or sys_platform == 'linux')"},
		},
		{
			name: "shared file in both roles and repeated same role",
			files: map[string]string{
				"requirements.txt":     "--requirement=deps/application.txt\n-r deps/shared.txt\n--constraint deps/shared.txt\n-cdeps/constraints.txt\n",
				"deps/application.txt": "packaging>=24,<25\n--constraint=constraints.txt\n",
				"deps/constraints.txt": "packaging==24.2\n",
				"deps/shared.txt":      "idna==3.10; python_version < '0'\n",
			},
			requirements: []string{"packaging>=24,<25", "idna==3.10; python_version < '0'"},
			constraints:  []string{"packaging==24.2", "idna==3.10; python_version < '0'"},
		},
		{
			name: "BOM CRLF hashes and false marker",
			files: map[string]string{
				"requirements.txt":     "\xef\xbb\xbf# root\r\n--requirement \\\r\n deps/application.txt\r\n-c deps/constraints.txt\r\n",
				"deps/application.txt": "\xef\xbb\xbfpackaging==24.2; os_name == 'posix' \\\r\n --hash=sha256:" + firstHash + " \\\r\n --hash=sha256:" + secondHash + "\r\nidna==3.10; python_version < '0'\r\n",
				"deps/constraints.txt": "\xef\xbb\xbfpackaging<25\r\n",
			},
			requirements: []string{"packaging==24.2; os_name == 'posix' --hash=sha256:" + firstHash + " --hash=sha256:" + secondHash, "idna==3.10; python_version < '0'"},
			constraints:  []string{"packaging<25"},
		},
		{
			name: "continued literal and coding package regression",
			files: map[string]string{
				"requirements.txt": "packaging; os_name == 'po\\\nsix'\ngeocoding==1.0\n",
			},
			requirements: []string{"packaging; os_name == 'posix'", "geocoding==1.0"},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			pyDepsFakeDocker(t)
			root := t.TempDir()
			var inputs []string
			for filename, body := range tc.files {
				pyDepsWrite(t, root, filename, body)
				inputs = append(inputs, filename)
			}
			sort.Strings(inputs)
			before := pyDepsFiles(t, root)
			env := pyDepsBuild(t, root)
			canonical := pyDepsAssertCanonicalStaging(t, root, env, inputs)
			// Repeated includes may preserve or collapse identical entries.
			// Compare identities here, just as the real pip oracle does.
			for filename, want := range map[string][]string{"requirements.txt": tc.requirements, "constraints.txt": tc.constraints} {
				seen := map[string]bool{}
				var distinct strings.Builder
				for _, line := range strings.Split(strings.TrimSuffix(canonical[filename], "\n"), "\n") {
					identity := pyDepsComparableRequirement(t, line)
					if line != "" && !seen[identity] {
						seen[identity] = true
						distinct.WriteString(line + "\n")
					}
				}
				pyDepsAssertCanonicalLines(t, distinct.String(), want)
			}
			if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
				t.Fatal("canonicalization or the offline pip oracle rewrote original requirements")
			}
			if tc.name == "BOM CRLF hashes and false marker" && os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
				pyDepsPipParserNegativeControls(t, root, canonical, firstHash, secondHash)
			}
		})
	}
	t.Run("rejected option whitespace", pyDepsAssertRejectedOptionWhitespaceWithPip)
}

// #258: parsing the requirement-file options alone is insufficient: pip
// returns a TAB-delimited --hash as part of the requirement with no options.
// Its own install-requirement constructor must reject that argument. Exercise
// the same shared rejected corpus in every effective-file role, and require a
// successful Docker command that reports a known pip input error; an image,
// network, file-opening or Python failure must never count as pip refusal.
func pyDepsAssertRejectedOptionWhitespaceWithPip(t *testing.T) {
	t.Helper()
	pyDepsFakeDocker(t)
	for _, tc := range pyDepsRejectedOptionWhitespaceFixtures() {
		for _, filename := range []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"} {
			t.Run(tc.name+"/"+filename, func(t *testing.T) {
				root := pyDepsFixture(t)
				pyDepsWrite(t, root, filename, tc.raw)
				before := pyDepsFiles(t, root)
				if recipe, err := toolchain.PythonDepsRecipe(root); err == nil {
					t.Errorf("validator accepted input pinned pip must refuse in %s: recipe=%q input=%q", filename, recipe, tc.raw)
				}
				if calls := pyDepsCalls(t); len(calls) != 0 {
					t.Fatalf("rejected input reached Docker before validation: %#v", calls)
				}
				if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
					got := pyDepsRunPinnedPipRefusal(t, root)
					if !got.Refused || got.ErrorType == "" || !strings.Contains(got.Error, "Invalid requirement") || !strings.Contains(got.Error, "--hash") {
						t.Errorf("pinned pip %s did not refuse the malformed requirement/hash boundary in %s: result=%#v input=%q", got.PipVersion, filename, got, tc.raw)
					}
				}
				if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
					t.Fatal("validator or offline pip refusal oracle rewrote dependency inputs")
				}
			})
		}
	}
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
		t.Run("refusal oracle accepts ASCII space control", func(t *testing.T) {
			root := t.TempDir()
			pyDepsWrite(t, root, "requirements.txt", "packaging==24.2 --hash=sha256:"+strings.Repeat("a", 64)+"\n")
			got := pyDepsRunPinnedPipRefusal(t, root)
			if got.Refused || got.ErrorType != "" || got.Error != "" {
				t.Fatalf("pinned pip refusal oracle rejected its valid ASCII-space control: %#v", got)
			}
		})
	}
}

// Only called for positive inputs which otherwise exercise the recipe API or
// an intentional install/evidence failure. Keep its fake Docker and flags in
// a nested scope, so existing build-count and failure assertions are unchanged.
func pyDepsAssertAcceptedWithPip(t *testing.T, root string) {
	t.Helper()
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") != "1" {
		return
	}
	t.Run("accepted input agrees with pinned pip", func(t *testing.T) {
		for _, name := range []string{"INVARIANT_PY_DEPS_FAILURE", "INVARIANT_PY_DEPS_REPLACE_TAG", "INVARIANT_PY_DEPS_RESOLUTION"} {
			t.Setenv(name, "")
		}
		pyDepsFakeDocker(t)
		env := pyDepsBuild(t, root)
		var inputs []string
		for _, input := range env.Inputs {
			inputs = append(inputs, input.Path)
		}
		pyDepsAssertCanonicalStaging(t, root, env, inputs)
	})
}

type pyDepsPipRequirement struct {
	Name       string              `json:"name"`
	Extras     []string            `json:"extras"`
	Specifiers []string            `json:"specifiers"`
	Marker     string              `json:"marker"`
	URL        string              `json:"url"`
	Link       string              `json:"link"`
	Constraint bool                `json:"constraint"`
	Editable   bool                `json:"editable"`
	Hashes     map[string][]string `json:"hashes"`
}

type pyDepsPipComparison struct {
	PipVersion       string                   `json:"pip_version"`
	Original         []pyDepsPipRequirement   `json:"original"`
	Canonical        []pyDepsPipRequirement   `json:"canonical"`
	OriginalFiles    []pyDepsAuthorityFile    `json:"original_files"`
	OriginalIncludes []pyDepsAuthorityInclude `json:"original_includes"`
}

func pyDepsAssertPipParserMatches(t *testing.T, root string, canonical map[string]string) {
	t.Helper()
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") != "1" {
		return
	}
	got := pyDepsRunPinnedPipParser(t, root, canonical)
	if !reflect.DeepEqual(got.Original, got.Canonical) {
		original, _ := json.MarshalIndent(got.Original, "", "  ")
		generated, _ := json.MarshalIndent(got.Canonical, "", "  ")
		t.Fatalf("pinned pip %s reads different requirements, constraints or hashes from canonical files:\noriginal=%s\ncanonical=%s\ncanonical files=%#v", got.PipVersion, original, generated, canonical)
	}
	// This report comes from the production parser command forwarded to the
	// real pinned image, not from the Docker double's fixture report builder.
	var report pyDepsAuthorityReport
	found := false
	for _, call := range pyDepsCalls(t) {
		if call.Kind == "parser" && len(call.ParserReport) != 0 {
			if err := json.Unmarshal(call.ParserReport, &report); err != nil {
				t.Fatalf("invalid production pip report: %v\n%s", err, call.ParserReport)
			}
			found = true
		}
	}
	if !found || report.Schema != 1 || report.PipVersion != got.PipVersion || report.Root != "requirements.txt" || report.Requirements == nil {
		t.Fatalf("accepted fixture lacks its actual pinned-pip production report: found=%t report=%#v oracle pip=%s", found, report, got.PipVersion)
	}
	if len(report.Errors) != 0 || len(report.Options) != 0 {
		t.Fatalf("production accepted pip errors or non-hash options: %#v", report)
	}
	var reported []pyDepsPipRequirement
	for _, requirement := range report.Requirements {
		if requirement.Path != "" || requirement.Archive || requirement.URL != "" || requirement.Link != "" || requirement.Editable || len(requirement.Options) != 0 {
			t.Fatalf("production accepted a non-PyPI form or extra option: %#v", requirement)
		}
		var specifiers []string
		if requirement.Specifier != "" {
			for _, specifier := range strings.Split(requirement.Specifier, ",") {
				specifiers = append(specifiers, strings.TrimSpace(specifier))
			}
		}
		reported = append(reported, pyDepsPipRequirement{Name: requirement.Name, Extras: requirement.Extras, Specifiers: specifiers, Marker: requirement.Marker, URL: requirement.URL, Link: requirement.Link, Constraint: requirement.Constraint, Editable: requirement.Editable, Hashes: requirement.Hashes})
	}
	if actual, want := pyDepsPipIdentities(t, reported), pyDepsPipIdentities(t, got.Canonical); !reflect.DeepEqual(actual, want) {
		t.Fatalf("canonical files disagree with production's authoritative pip report:\nreport=%q\ncanonical=%q", actual, want)
	}
	if actual, want := pyDepsJSONSet(t, report.Files), pyDepsJSONSet(t, got.OriginalFiles); !reflect.DeepEqual(actual, want) {
		t.Fatalf("production pip report lost followed files or their requirement/constraint roles:\nreport=%q\npip=%q", actual, want)
	}
	if actual, want := pyDepsJSONSet(t, report.Includes), pyDepsJSONSet(t, got.OriginalIncludes); !reflect.DeepEqual(actual, want) {
		t.Fatalf("production pip report lost includes, literal filenames or their roles:\nreport=%q\npip=%q", actual, want)
	}
}

func pyDepsPipIdentities(t *testing.T, rows []pyDepsPipRequirement) []string {
	t.Helper()
	canonicalName := func(value string) string {
		value = strings.ToLower(strings.NewReplacer("_", "-", ".", "-").Replace(value))
		for strings.Contains(value, "--") {
			value = strings.ReplaceAll(value, "--", "-")
		}
		return value
	}
	var normalized []pyDepsPipRequirement
	for _, row := range rows {
		row.Name = canonicalName(row.Name)
		extras := make([]string, 0, len(row.Extras))
		for _, extra := range row.Extras {
			extras = append(extras, canonicalName(extra))
		}
		sort.Strings(extras)
		row.Extras = extras
		row.Specifiers = append([]string{}, row.Specifiers...)
		sort.Strings(row.Specifiers)
		// The shared comparator accepts a whole requirement; prefix a name
		// so commas/operators inside a marker literal cannot be mistaken
		// for a requirement's reorderable specifier set.
		row.Marker = strings.TrimPrefix(pyDepsComparableRequirement(t, "placeholder;"+row.Marker), "placeholder;")
		hashes := map[string][]string{}
		for algorithm, values := range row.Hashes {
			unique := map[string]bool{}
			for _, value := range values {
				unique[value] = true
			}
			for value := range unique {
				hashes[algorithm] = append(hashes[algorithm], value)
			}
			sort.Strings(hashes[algorithm])
		}
		row.Hashes = hashes
		normalized = append(normalized, row)
	}
	return pyDepsJSONSet(t, normalized)
}

func pyDepsJSONSet[T any](t *testing.T, values []T) []string {
	t.Helper()
	seen := map[string]bool{}
	var result []string
	for _, value := range values {
		b, err := json.Marshal(value)
		if err != nil {
			t.Fatal(err)
		}
		if !seen[string(b)] {
			result = append(result, string(b))
			seen[string(b)] = true
		}
	}
	sort.Strings(result)
	return result
}

// Resolve the actual executable before any test prepends a Docker double to
// PATH. The helper subprocess also initializes this variable, but exits in
// its existing init handler and never executes the parser.
var pyDepsParserDocker, pyDepsParserDockerErr = exec.LookPath("docker")
var pyDepsParserBaseOnce sync.Once
var pyDepsParserBaseErr error

func pyDepsEnsurePinnedPipBase(t *testing.T) {
	t.Helper()
	if pyDepsParserDockerErr != nil || !filepath.IsAbs(pyDepsParserDocker) {
		t.Fatalf("requested pinned pip acceptance requires a real Docker executable: path=%q error=%v", pyDepsParserDocker, pyDepsParserDockerErr)
	}
	// Acquiring the pinned base is setup, as for the existing real-build
	// suite. Parsing itself forbids pulls, network access and package installs.
	pyDepsParserBaseOnce.Do(func() {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
		defer cancel()
		if err := exec.CommandContext(ctx, pyDepsParserDocker, "image", "inspect", toolchain.PythonImage).Run(); err == nil {
			return
		}
		out, err := exec.CommandContext(ctx, pyDepsParserDocker, "pull", "--platform", "linux/amd64", toolchain.PythonImage).CombinedOutput()
		if err != nil {
			pyDepsParserBaseErr = fmt.Errorf("acquire pinned Python base for parser acceptance: %w\n%s", err, out)
		}
	})
	if pyDepsParserBaseErr != nil {
		t.Fatal(pyDepsParserBaseErr)
	}
}

func pyDepsRunPinnedPipParser(t *testing.T, root string, canonical map[string]string) pyDepsPipComparison {
	t.Helper()
	pyDepsEnsurePinnedPipBase(t)
	if len(canonical) != 2 {
		t.Fatalf("pip parser requires exactly the generated requirements and constraints files: %#v", canonical)
	}
	canonicalDir := t.TempDir()
	for _, filename := range []string{"requirements.txt", "constraints.txt"} {
		body, ok := canonical[filename]
		if !ok {
			t.Fatalf("missing generated %s", filename)
		}
		pyDepsWrite(t, canonicalDir, filename, body)
	}
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	out, err := exec.CommandContext(ctx, pyDepsParserDocker,
		"run", "--rm", "--pull=never", "--network", "none", "--platform", "linux/amd64", "--read-only",
		"-v", root+":/original:ro", "-v", canonicalDir+":/canonical:ro", "-w", "/tmp",
		"--entrypoint", "/usr/local/bin/python", toolchain.PythonImage, "-I", "-B", "-c", pyDepsPinnedPipParser).CombinedOutput()
	if err != nil {
		t.Fatalf("pinned image's own pip could not parse accepted fixture offline: %v\n%s", err, out)
	}
	var got pyDepsPipComparison
	if err := json.Unmarshal(out, &got); err != nil || got.PipVersion == "" || got.Original == nil || got.Canonical == nil {
		t.Fatalf("invalid pinned pip parser output: error=%v\n%s", err, out)
	}
	return got
}

type pyDepsPipRefusal struct {
	PipVersion string `json:"pip_version"`
	Refused    bool   `json:"refused"`
	ErrorType  string `json:"error_type"`
	Error      string `json:"error"`
}

func pyDepsRunPinnedPipRefusal(t *testing.T, root string) pyDepsPipRefusal {
	t.Helper()
	pyDepsEnsurePinnedPipBase(t)
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	out, err := exec.CommandContext(ctx, pyDepsParserDocker,
		"run", "--rm", "--pull=never", "--network", "none", "--platform", "linux/amd64", "--read-only",
		"-v", root+":/original:ro", "-w", "/tmp",
		"--entrypoint", "/usr/local/bin/python", toolchain.PythonImage, "-I", "-B", "-c", pyDepsPinnedPipRefusal).CombinedOutput()
	if err != nil {
		t.Fatalf("pinned pip refusal oracle failed to execute offline; this is not input rejection: %v\n%s", err, out)
	}
	var got pyDepsPipRefusal
	if err := json.Unmarshal(out, &got); err != nil || got.PipVersion == "" {
		t.Fatalf("invalid pinned pip refusal output: error=%v\n%s", err, out)
	}
	return got
}

// These controls are oracle checks: every changed canonical input must parse
// successfully, then differ. A parser exception or failed Docker command is
// a test failure, not evidence that the comparison detected semantic drift.
func pyDepsPipParserNegativeControls(t *testing.T, root string, canonical map[string]string, firstHash, secondHash string) {
	t.Helper()
	for _, change := range []string{"missing requirement", "extra requirement", "false marker dropped", "requirement became constraint", "marker space inserted", "hash changed", "second hash dropped"} {
		t.Run("oracle detects "+change, func(t *testing.T) {
			changed := map[string]string{"requirements.txt": canonical["requirements.txt"], "constraints.txt": canonical["constraints.txt"]}
			lines := strings.Split(strings.TrimSuffix(changed["requirements.txt"], "\n"), "\n")
			var retained []string
			for _, line := range lines {
				switch {
				case change == "missing requirement" && strings.HasPrefix(line, "packaging"):
					continue
				case change == "false marker dropped" && strings.HasPrefix(line, "idna"):
					continue
				case change == "requirement became constraint" && strings.HasPrefix(line, "packaging"):
					changed["constraints.txt"] += line + "\n"
					continue
				case change == "marker space inserted":
					line = strings.ReplaceAll(line, "posix", "po six")
				case change == "hash changed":
					line = strings.ReplaceAll(line, firstHash, strings.Repeat("c", 64))
				case change == "second hash dropped":
					line = strings.TrimSpace(strings.ReplaceAll(line, "--hash=sha256:"+secondHash, ""))
				}
				retained = append(retained, line)
			}
			if change == "extra requirement" {
				retained = append(retained, "six==1.17.0")
			}
			changed["requirements.txt"] = strings.Join(retained, "\n") + "\n"
			if reflect.DeepEqual(changed, canonical) {
				t.Fatal("oracle negative control did not alter canonical bytes")
			}
			got := pyDepsRunPinnedPipParser(t, root, changed)
			if reflect.DeepEqual(got.Original, got.Canonical) {
				t.Fatalf("pinned pip oracle failed to detect %s: %#v", change, got)
			}
		})
	}
}

const pyDepsPinnedPipParser = `
import json
import os
import pip
from pip._internal.network.session import PipSession
from pip._internal.req.req_file import RequirementsFileParser, parse_requirements
from pip._internal.req.constructors import install_req_from_parsed_requirement
from pip._vendor.packaging.utils import canonicalize_name

def no_network(*args, **kwargs):
    raise AssertionError("pip parser attempted network access")

# Observe pip's own parsed lines before its recursive iterator consumes
# include-only rows. Merely inspecting parse_requirements' yielded entries
# misses those files and any global-option-only lines.
original_files = {}
original_includes = {}
parse_file = RequirementsFileParser._parse_file

def observe_file(self, filename, constraint):
    original = filename.startswith("/original/")
    if original:
        source = os.path.relpath(filename, "/original")
        row = {"path": source, "constraint": constraint}
        original_files[json.dumps(row, sort_keys=True)] = row
    for line in parse_file(self, filename, constraint):
        if original and not line.is_requirement:
            for values, role in [(line.opts.requirements, False), (line.opts.constraints, True)]:
                for value in values or []:
                    target = os.path.relpath(os.path.normpath(os.path.join(os.path.dirname(filename), value)), "/original")
                    row = {"source": source, "target": target, "value": value, "constraint": role}
                    original_includes[json.dumps(row, sort_keys=True)] = row
        yield line

RequirementsFileParser._parse_file = observe_file

def records(sources):
    result = {}
    with PipSession() as session:
        session.request = no_network
        for filename, constraint in sources:
            for parsed in parse_requirements(filename, session=session, constraint=constraint):
                # Use pip's own constructor too: its marker splitting differs
                # from directly feeding the complete line to packaging.
                install = install_req_from_parsed_requirement(parsed, isolated=True)
                req = install.req
                if req is None:
                    raise AssertionError("accepted input is not a named PEP 508 requirement")
                row = {
                    "name": canonicalize_name(req.name),
                    "extras": sorted({canonicalize_name(extra) for extra in req.extras}),
                    "specifiers": sorted(str(specifier) for specifier in req.specifier),
                    "marker": str(install.markers) if install.markers else "",
                    "url": req.url or "",
                    "link": str(install.link) if install.link else "",
                    "constraint": install.constraint,
                    "editable": install.editable,
                    "hashes": {algorithm: sorted(set(values)) for algorithm, values in install.hash_options.items()},
                }
                # Repeating the same include in the same role, or the same
                # allowed hash, has no semantic effect. Different per-entry
                # hashes or roles stay distinct. Never evaluate markers: even
                # false-marker requirements must survive canonicalization.
                result[json.dumps(row, sort_keys=True)] = row
    return [result[key] for key in sorted(result)]

original = records([("/original/requirements.txt", False)])
canonical = records([("/canonical/requirements.txt", False), ("/canonical/constraints.txt", True)])
print(json.dumps({
    "pip_version": pip.__version__,
    "original": original,
    "canonical": canonical,
    "original_files": [original_files[key] for key in sorted(original_files)],
    "original_includes": [original_includes[key] for key in sorted(original_includes)],
}, sort_keys=True))
`

const pyDepsPinnedPipRefusal = `
import json
import pip
from pip._internal.exceptions import InstallationError
from pip._internal.network.session import PipSession
from pip._internal.req.req_file import parse_requirements
from pip._internal.req.constructors import install_req_from_parsed_requirement

def no_network(*args, **kwargs):
    raise AssertionError("pip refusal oracle attempted network access")

result = {"pip_version": pip.__version__, "refused": False, "error_type": "", "error": ""}
try:
    with PipSession() as session:
        session.request = no_network
        for parsed in parse_requirements("/original/requirements.txt", session=session):
            # req_file parsing can return the malformed --hash in its raw
            # requirement. Only the constructor establishes pip's refusal.
            install_req_from_parsed_requirement(parsed, isolated=True)
except InstallationError as error:
    if not str(error).startswith("Invalid requirement") or "--hash" not in str(error):
        raise
    result.update(refused=True, error_type=type(error).__name__, error=str(error))

# Unexpected exceptions, missing files and failed Docker invocations produce
# a nonzero process status, never a successful rejection result.
print(json.dumps(result, sort_keys=True))
`

sources.internal/verify/python_proxy_accept_test:
package verify

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/toolchain"
)

var pyDepsProxyKeys = []string{
	"HTTP_PROXY", "http_proxy", "HTTPS_PROXY", "https_proxy", "FTP_PROXY", "ftp_proxy",
	"ALL_PROXY", "all_proxy", "NO_PROXY", "no_proxy",
}

const pyDepsProxyCredential = "http://invariant-proxy-user:invariant-proxy-password@127.0.0.1:9"

// Docker adds proxies from config.json even when the gate passes no host
// environment variables. The default layer emulates that client behavior;
// the real layer independently checks the actual container/build environment
// before forwarding each unchanged production invocation. Neither layer
// requires a particular defense: explicit empty overrides and a separate
// sanitized client configuration both work.
func TestPythonDependenciesSuppressDockerClientProxies(t *testing.T) {
	t.Run("client configuration at every gate boundary", func(t *testing.T) {
		// The observer delegates to the ordinary CLI double here. The real
		// subtest below executes the parser and recipe without that double.
		t.Setenv("INVARIANT_PYTHON_DEPS_REAL", "")
		pyDepsFakeDocker(t)
		config := pyDepsProxyConfig(t, false)
		before := pyDepsFiles(t, config)
		log := pyDepsProxyObserver(t, false)
		out, err := exec.Command("docker", "run", "--rm", "--network", "none", toolchain.PythonImage, "/usr/bin/env").CombinedOutput()
		if err == nil || !bytes.Contains(out, []byte("Docker client configuration leaked")) {
			t.Fatalf("Docker double did not inject configured proxy defaults: %v\n%s", err, out)
		}
		root := pyDepsProxyFixture(t)
		first := pyDepsBuild(t, root)
		tc := toolchain.Toolchain{PythonImage: toolchain.PythonImage, JavaImage: "accept-java", TLCJar: filepath.Join(t.TempDir(), "tlc.jar")}
		r, err := Run(context.Background(), root, "", tc)
		pyDepsRequireGateChecks(t, r, err)
		pyDepsProxyRequireCalls(t, log, first.Image, false)
		pyDepsProxyRequireReceipt(t, r, first)
		if !reflect.DeepEqual(before, pyDepsFiles(t, config)) {
			t.Fatal("gate rewrote the user's Docker client configuration")
		}
	})
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
		t.Run("real Docker config injection and generated recipe", func(t *testing.T) {
			pyDepsRequireRealDocker(t)
			// Obtain the model checker before changing the Docker client
			// fixture. Context/daemon selection is retained in the fixture.
			ctx, cancel := context.WithTimeout(context.Background(), 12*time.Minute)
			defer cancel()
			tc, err := toolchain.Ensure(ctx)
			if err != nil {
				t.Fatal(err)
			}
			pyDepsEnsurePinnedPipBase(t)
			config := pyDepsProxyConfig(t, true)
			before := pyDepsFiles(t, config)
			// This negative control uses the actual Docker client directly.
			// It proves the selected config/context injects all ten values,
			// rather than accepting an inert fixture or an ignored config.
			probe := "import json,os;print(json.dumps({k:os.environ.get(k) for k in " + pyDepsProxyKeyJSON() + "}))"
			out, err := exec.CommandContext(ctx, "docker", "run", "--rm", "--network", "none", "--platform", "linux/amd64", toolchain.PythonImage,
				"/usr/local/bin/python", "-I", "-c", probe).CombinedOutput()
			var inherited map[string]string
			if err != nil || json.Unmarshal(bytes.TrimSpace(out), &inherited) != nil {
				t.Fatalf("real Docker proxy negative control failed: %v\n%s", err, out)
			}
			for _, key := range pyDepsProxyKeys {
				if inherited[key] != pyDepsProxyCredential {
					t.Fatalf("Docker did not inject configured credential into %s: %#v", key, inherited)
				}
			}
			log := pyDepsProxyObserver(t, true)
			root := pyDepsProxyFixture(t)
			originals := pyDepsFiles(t, root)
			first := pyDepsBuild(t, root)
			pyDepsCleanupRecipeImage(t, first.Image)
			pyDepsAssertEnvironment(t, root, first, "24.2")
			second := pyDepsBuild(t, root)
			if !reflect.DeepEqual(first, second) {
				t.Fatal("client proxy suppression changed dependency reuse or artifact evidence")
			}
			r, err := Run(ctx, root, "", tc)
			pyDepsRequireGateChecks(t, r, err)
			pyDepsProxyRequireReceipt(t, r, first)
			pyDepsProxyRequireCalls(t, log, first.Image, true)
			if !reflect.DeepEqual(originals, pyDepsFiles(t, root)) || !reflect.DeepEqual(before, pyDepsFiles(t, config)) {
				t.Fatal("proxy suppression changed application inputs or the user's Docker client configuration")
			}
		})
	}
}

func pyDepsProxyFixture(t *testing.T) string {
	t.Helper()
	root := pyDepsFixture(t)
	pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("# Docker proxy regression %d\n-r deps/application.txt\n", time.Now().UnixNano()))
	guard := "import os\nassert not {k: os.environ[k] for k in " + pyDepsProxyKeyJSON() + " if os.environ.get(k)}, 'Docker client proxy reached application'\n"
	files := pyDepsFiles(t, root)
	for _, name := range []string{"test_dependency.py", "conformance.py"} {
		pyDepsWrite(t, root, name, guard+files[name])
	}
	return root
}

func pyDepsProxyKeyJSON() string {
	b, _ := json.Marshal(pyDepsProxyKeys)
	return string(b)
}

// Write only a new temporary client configuration. Retaining Docker context
// metadata preserves named desktop/remote contexts and their TLS connection;
// registry auth, credential stores and the host config itself are not copied
// or changed. DOCKER_HOST and DOCKER_CONTEXT remain as the caller set them.
func pyDepsProxyConfig(t *testing.T, preserveContext bool) string {
	t.Helper()
	dir := t.TempDir()
	config := map[string]any{"proxies": map[string]any{"default": map[string]string{
		"httpProxy": pyDepsProxyCredential, "httpsProxy": pyDepsProxyCredential,
		"ftpProxy": pyDepsProxyCredential, "allProxy": pyDepsProxyCredential, "noProxy": pyDepsProxyCredential,
	}}}
	if preserveContext {
		old := os.Getenv("DOCKER_CONFIG")
		if old == "" {
			home, err := os.UserHomeDir()
			if err != nil {
				t.Fatal(err)
			}
			old = filepath.Join(home, ".docker")
		}
		original, err := os.ReadFile(filepath.Join(old, "config.json"))
		originalExists := err == nil
		if err != nil && !os.IsNotExist(err) {
			t.Fatal(err)
		}
		if len(original) > 0 {
			var fields map[string]json.RawMessage
			if err := json.Unmarshal(original, &fields); err != nil {
				t.Fatal(err)
			}
			if current, present := fields["currentContext"]; present {
				config["currentContext"] = current
			}
		}
		t.Cleanup(func() {
			after, err := os.ReadFile(filepath.Join(old, "config.json"))
			if err != nil && !os.IsNotExist(err) || (err == nil) != originalExists || !bytes.Equal(original, after) {
				t.Error("acceptance fixture or gate modified the original Docker client config")
			}
		})
		contexts := filepath.Join(old, "contexts")
		err = filepath.WalkDir(contexts, func(path string, d fs.DirEntry, err error) error {
			if os.IsNotExist(err) && path == contexts {
				return nil
			}
			if err != nil {
				return err
			}
			rel, err := filepath.Rel(old, path)
			if err != nil {
				return err
			}
			if d.IsDir() {
				return os.MkdirAll(filepath.Join(dir, rel), 0o700)
			}
			b, err := os.ReadFile(path)
			if err != nil {
				return err
			}
			return os.WriteFile(filepath.Join(dir, rel), b, 0o600)
		})
		if err != nil {
			t.Fatal(err)
		}
	}
	b, err := json.Marshal(config)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "config.json"), b, 0o600); err != nil {
		t.Fatal(err)
	}
	t.Setenv("DOCKER_CONFIG", dir)
	return dir
}

type pyDepsProxyCall struct {
	Kind     string
	Image    string
	Count    bool
	Observed bool
	Proxies  map[string]string
}

func pyDepsProxyObserver(t *testing.T, real bool) string {
	t.Helper()
	target, err := exec.LookPath("docker")
	if err != nil {
		t.Fatal(err)
	}
	binary, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	log := filepath.Join(dir, "proxy-calls.jsonl")
	t.Setenv("INVARIANT_PY_DEPS_PROXY_BINARY", binary)
	t.Setenv("INVARIANT_PY_DEPS_PROXY_TARGET", target)
	t.Setenv("INVARIANT_PY_DEPS_PROXY_LOG", log)
	t.Setenv("INVARIANT_PY_DEPS_PROXY_REAL", fmt.Sprint(real))
	script := "#!/bin/sh\nINVARIANT_PY_DEPS_PROXY_HELPER=1 exec \"$INVARIANT_PY_DEPS_PROXY_BINARY\" \"$@\"\n"
	if err := os.WriteFile(filepath.Join(dir, "docker"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	return log
}

func pyDepsProxyRequireReceipt(t *testing.T, r *Report, want *toolchain.PythonDependencies) {
	t.Helper()
	b, err := json.Marshal(r.Toolchain)
	if err != nil {
		t.Fatal(err)
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(b, &fields); err != nil {
		t.Fatal(err)
	}
	expected, _ := json.Marshal(want)
	if !bytes.Equal(fields["python_dependencies"], expected) || bytes.Contains(b, []byte("invariant-proxy-password")) {
		t.Fatalf("proxy fixture changed dependency provenance or entered receipt: %s", b)
	}
}

func pyDepsProxyRequireCalls(t *testing.T, log, image string, real bool) {
	t.Helper()
	b, err := os.ReadFile(log)
	if err != nil {
		t.Fatal(err)
	}
	seen := map[string]bool{}
	builds := 0
	for _, line := range bytes.Split(bytes.TrimSpace(b), []byte{'\n'}) {
		var call pyDepsProxyCall
		if err := json.Unmarshal(line, &call); err != nil {
			t.Fatal(err)
		}
		if real && !call.Observed {
			t.Fatalf("real Docker phase was not observed: %#v", call)
		}
		for key, value := range call.Proxies {
			if value != "" {
				t.Fatalf("Docker config injected %s into %s: %#v", key, call.Kind, call)
			}
		}
		phase := call.Kind
		if phase == "application" && call.Count {
			phase = "larger"
		}
		if phase == "run" && call.Image == image {
			phase = "evidence"
		}
		seen[phase] = true
		if phase == "build" {
			builds++
		}
	}
	for _, phase := range []string{"parser", "build", "evidence", "application", "larger"} {
		if !seen[phase] {
			t.Errorf("Docker proxy regression missed %s", phase)
		}
	}
	if builds != 1 {
		t.Fatalf("dependency image was not built once then reused: builds=%d", builds)
	}
}

func init() {
	if os.Getenv("INVARIANT_PY_DEPS_PROXY_HELPER") == "1" {
		os.Exit(pyDepsProxyDocker(os.Args[1:]))
	}
}

// This wrapper is independent of pyDepsDocker: merely inspecting explicit
// -e arguments cannot detect client configuration defaults. In real mode the
// real Docker binary also executes probes with the same configuration and
// overrides. Production's parser, recipe and commands are then forwarded
// unchanged; no probe result is used as dependency or check evidence.
func pyDepsProxyDocker(args []string) int {
	fail := func(err error) int { fmt.Fprintln(os.Stderr, err); return 72 }
	global, command, err := pyDepsProxyClientArguments(args)
	if err != nil {
		return fail(err)
	}
	child := func(argv []string) *exec.Cmd {
		cmd := exec.Command(os.Getenv("INVARIANT_PY_DEPS_PROXY_TARGET"), argv...)
		for _, entry := range os.Environ() {
			if !strings.HasPrefix(entry, "INVARIANT_PY_DEPS_PROXY_HELPER=") {
				cmd.Env = append(cmd.Env, entry)
			}
		}
		return cmd
	}
	if len(command) > 0 && (command[0] == "run" || command[0] == "build") {
		proxies, err := pyDepsProxyDefaults(global)
		if err != nil {
			return fail(err)
		}
		call := pyDepsProxyCall{Kind: command[0], Proxies: proxies}
		var options []string
		var buildArgs []string
		if command[0] == "run" {
			var env map[string]string
			options, call.Image, env, err = pyDepsProxyRunArguments(command[1:])
			if err != nil {
				return fail(err)
			}
			for key, value := range env {
				if _, proxy := proxies[key]; proxy {
					proxies[key] = value
				}
			}
			if env["DRIVER"] != "" {
				call.Kind, call.Count = "application", env["INVARIANT_COUNT"] != ""
			} else if call.Image == toolchain.PythonImage {
				call.Kind = "parser"
			}
		} else {
			for i := 1; i < len(command); i++ {
				key, value, joined := strings.Cut(command[i], "=")
				if key != "--build-arg" {
					continue
				}
				if !joined {
					i++
					if i >= len(command) {
						return fail(fmt.Errorf("missing build arg"))
					}
					value = command[i]
				}
				buildArgs = append(buildArgs, "--build-arg", value)
				name, content := pyDepsProxyAssignment(value)
				if _, proxy := proxies[name]; proxy {
					proxies[name] = content
				}
			}
		}
		if os.Getenv("INVARIANT_PY_DEPS_PROXY_REAL") == "true" {
			check := "import os; assert not {k:os.environ[k] for k in " + pyDepsProxyKeyJSON() + " if os.environ.get(k)}, 'Docker client proxy leaked'; print('invariant-proxy-probe-ok')"
			if command[0] == "run" {
				probe := append(append([]string{}, global...), "run")
				probe = append(probe, options...)
				// Proxy injection is client-side and independent of the image.
				// TLC's Java image has no Python, so use the pinned probe base
				// with the production options, then run the original image and
				// command unchanged. Application fixtures separately assert
				// that their actual dependency image contains no proxy values.
				probe = append(probe, "--rm", "--platform", "linux/amd64", "--entrypoint", "/usr/local/bin/python", toolchain.PythonImage, "-I", "-c", check)
				out, err := child(probe).CombinedOutput()
				if err != nil || !bytes.Contains(out, []byte("invariant-proxy-probe-ok")) {
					return fail(fmt.Errorf("observing %s proxy environment: %v\n%s", call.Kind, err, out))
				}
			} else {
				// Execute a separate uncached RUN using the same client config
				// and exact build-arg overrides. The actual recipe is untouched
				// and runs afterward against its original build context.
				probe := append(append([]string{}, global...), "build", "--no-cache", "--network", "none", "--platform", "linux/amd64", "-q")
				probe = append(probe, buildArgs...)
				probe = append(probe, "-")
				run, _ := json.Marshal([]string{"/usr/local/bin/python", "-I", "-c", check})
				cmd := child(probe)
				cmd.Stdin = strings.NewReader("FROM " + toolchain.PythonImage + "\nRUN " + string(run) + "\n")
				var stderr bytes.Buffer
				cmd.Stderr = &stderr
				out, err := cmd.Output()
				if err != nil || !pyDepsDigest.Match(bytes.TrimSpace(out)) {
					return fail(fmt.Errorf("observing Docker build proxy environment: %v\n%s\n%s", err, out, stderr.Bytes()))
				}
				cleanup := append(append([]string{}, global...), "image", "rm", string(bytes.TrimSpace(out)))
				if out, err := child(cleanup).CombinedOutput(); err != nil {
					return fail(fmt.Errorf("cleaning proxy build probe: %v\n%s", err, out))
				}
			}
			call.Observed = true
			// The actual Docker environment is authoritative in this layer,
			// including endpoint-specific settings in a sanitized config.
			// Both real probes succeeded only if every value was empty.
			for key := range proxies {
				proxies[key] = ""
			}
		}
		for key, value := range proxies {
			if value != "" {
				return fail(fmt.Errorf("Docker client configuration leaked %s into %s", key, call.Kind))
			}
		}
		f, err := os.OpenFile(os.Getenv("INVARIANT_PY_DEPS_PROXY_LOG"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
		if err != nil {
			return fail(err)
		}
		err = json.NewEncoder(f).Encode(call)
		f.Close()
		if err != nil {
			return fail(err)
		}
	}
	forward := args
	if os.Getenv("INVARIANT_PY_DEPS_PROXY_REAL") != "true" {
		// The older generic double has no global client-flag parser. They
		// have already been applied by this independent config observer.
		forward = command
	}
	cmd := child(forward)
	cmd.Stdin, cmd.Stdout, cmd.Stderr = os.Stdin, os.Stdout, os.Stderr
	if err := cmd.Run(); err != nil {
		if exit, ok := err.(*exec.ExitError); ok {
			return exit.ExitCode()
		}
		return fail(err)
	}
	return 0
}

func pyDepsProxyClientArguments(args []string) ([]string, []string, error) {
	for i := 0; i < len(args); i++ {
		if !strings.HasPrefix(args[i], "-") {
			return args[:i], args[i:], nil
		}
		key, _, joined := strings.Cut(args[i], "=")
		if !joined {
			switch key {
			case "--config", "--context", "-c", "--host", "-H", "--log-level", "-l", "--tlscacert", "--tlscert", "--tlskey":
				i++
			}
		}
	}
	return nil, nil, fmt.Errorf("Docker proxy observer found no command")
}

func pyDepsProxyDefaults(global []string) (map[string]string, error) {
	dir := os.Getenv("DOCKER_CONFIG")
	for i := 0; i < len(global); i++ {
		if global[i] == "--config" && i+1 < len(global) {
			i++
			dir = global[i]
		} else if strings.HasPrefix(global[i], "--config=") {
			dir = strings.TrimPrefix(global[i], "--config=")
		}
	}
	if dir == "" {
		home, err := os.UserHomeDir()
		if err != nil {
			return nil, err
		}
		dir = filepath.Join(home, ".docker")
	}
	var config struct {
		Proxies map[string]map[string]string `json:"proxies"`
	}
	b, err := os.ReadFile(filepath.Join(dir, "config.json"))
	if err != nil && !os.IsNotExist(err) {
		return nil, err
	}
	if len(b) > 0 {
		if err := json.Unmarshal(b, &config); err != nil {
			return nil, err
		}
	}
	proxies := map[string]string{}
	for _, key := range pyDepsProxyKeys {
		name := strings.TrimSuffix(strings.ToLower(key), "_proxy") + "Proxy"
		proxies[key] = config.Proxies["default"][name]
	}
	return proxies, nil
}

func pyDepsProxyAssignment(value string) (string, string) {
	key, content, assigned := strings.Cut(value, "=")
	if !assigned {
		content = os.Getenv(key)
	}
	return key, content
}

func pyDepsProxyRunArguments(args []string) ([]string, string, map[string]string, error) {
	env := map[string]string{}
	for i := 0; i < len(args); i++ {
		if !strings.HasPrefix(args[i], "-") {
			return args[:i], args[i], env, nil
		}
		key, value, joined := strings.Cut(args[i], "=")
		if !joined {
			switch key {
			case "--name", "--network", "--platform", "--memory", "--pids-limit", "-w", "--workdir", "--user", "--entrypoint", "--cap-drop", "--security-opt", "--tmpfs", "--pull", "--mount", "-e", "--env", "--env-file", "-v", "--volume":
				i++
				if i >= len(args) {
					return nil, "", nil, fmt.Errorf("Docker option %s has no value", key)
				}
				value = args[i]
			}
		}
		if key == "-e" || key == "--env" {
			name, content := pyDepsProxyAssignment(value)
			env[name] = content
		}
		if key == "--env-file" {
			b, err := os.ReadFile(value)
			if err != nil {
				return nil, "", nil, err
			}
			for _, line := range strings.Split(string(b), "\n") {
				line = strings.TrimSpace(line)
				if line != "" && !strings.HasPrefix(line, "#") {
					name, content := pyDepsProxyAssignment(line)
					env[name] = content
				}
			}
		}
	}
	return nil, "", nil, fmt.Errorf("Docker proxy observer found no run image")
}

sources.internal/verify/python_recipe_accept_tes:
package verify

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"reflect"
	"regexp"
	"sort"
	"strings"
	"testing"
	"time"
	"unicode"
	"unicode/utf8"

	"github.com/gitdek/invariant/internal/toolchain"
)

// These tests have two deliberately different layers. The Docker double only
// captures the context: its successful "build" is never evidence that pip or
// Python ran. The default layer checks the generated recipe's literal COPY,
// canonical input tree and isolated Python commands. The real layer executes
// that recipe through PythonDepsImage and verifies its installed environment.
// The real command is a required acceptance check, not optional merge evidence:
//
// INVARIANT_PYTHON_DEPS_REAL=1 go test ./internal/verify -run '^TestPythonDependencyRecipe(IsolatesInputModules|CopiesLiteralFilenames|ReadsOnlyCanonicalFiles)$' -count=1 -timeout 20m
//
// Requested real runs fail, rather than skip, when Docker/builds are unavailable.

func TestPythonDependencyRecipeIsolatesInputModules(t *testing.T) {
	for _, module := range []string{"venv", "pip"} {
		t.Run(module, func(t *testing.T) {
			root := pyDepsFixture(t)
			filename := module + ".py"
			// This is both valid Python syntax and a valid pip requirement with
			// a false marker. pip treats __import__ as inert marker text. If
			// Python executes the file as a module, evaluating python_version
			// raises NameError before the legitimate venv/pip module can run.
			payload := "print; python_version == \"__import__('sys').exit(86)\"\n"
			pyDepsWrite(t, root, filename, payload)
			pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("# shadow recipe %s %d\n-r deps/application.txt\n-r %s\n", module, time.Now().UnixNano(), filename))
			inputs := []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt", filename}
			before := pyDepsFiles(t, root)
			t.Run("generated recipe contract", func(t *testing.T) {
				pyDepsFakeDocker(t)
				env := pyDepsBuild(t, root)
				pyDepsAssertRecipeEnvironment(t, root, env, inputs)
				pyDepsAssertCanonicalStaging(t, root, env, inputs)
			})
			if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
				t.Run("execute generated recipe", func(t *testing.T) {
					pyDepsRequireRealDocker(t)
					env := pyDepsBuild(t, root)
					pyDepsCleanupRecipeImage(t, env.Image)
					pyDepsAssertRecipeEnvironment(t, root, env, inputs)
					pyDepsRunChecks(t, root)
					// Negative control: the same harmless input MUST shadow the
					// module if -I and the separate working directory are absent.
					ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
					defer cancel()
					out, err := exec.CommandContext(ctx, "docker", "run", "--rm", "--network", "none", "--platform", "linux/amd64", "--read-only", "-v", root+":/shadow:ro", "-w", "/shadow", "--entrypoint", "/usr/local/bin/python", toolchain.PythonImage, "-m", module, "--version").CombinedOutput()
					if err == nil || !strings.Contains(string(out), "NameError") || !strings.Contains(string(out), "python_version") || !strings.Contains(string(out), "/shadow/"+filename) {
						t.Fatalf("shadow fixture did not exercise module loading: error=%v\n%s", err, out)
					}
				})
			}
			if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
				t.Fatal("dependency recipe or execution rewrote application files")
			}
		})
	}
}

func TestPythonDependencyRecipeCopiesLiteralFilenames(t *testing.T) {
	root := pyDepsFixture(t)
	pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("# literal recipe %d\n-r deps/application.txt\n-r [a].txt\n-c a.txt\n", time.Now().UnixNano()))
	pyDepsWrite(t, root, "[a].txt", "# literal bracket filename\npackaging==24.2\n")
	// Constraints for an unrequested package are inert. Literal host reads
	// must preserve the roles of [a].txt and a.txt before canonicalization;
	// treating the latter as requirements makes its versions conflict.
	pyDepsWrite(t, root, "a.txt", "packaging==24.2\nidna==3.9\nidna==3.10\n")
	inputs := []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt", "[a].txt", "a.txt"}
	before := pyDepsFiles(t, root)
	t.Run("generated recipe contract", func(t *testing.T) {
		pyDepsFakeDocker(t)
		env := pyDepsBuild(t, root)
		pyDepsAssertRecipeEnvironment(t, root, env, inputs)
		pyDepsAssertCanonicalStaging(t, root, env, inputs)
	})
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
		t.Run("execute generated recipe", func(t *testing.T) {
			pyDepsRequireRealDocker(t)
			env := pyDepsBuild(t, root)
			pyDepsCleanupRecipeImage(t, env.Image)
			pyDepsAssertRecipeEnvironment(t, root, env, inputs)
			pyDepsRunChecks(t, root)
		})
	}
	if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
		t.Fatal("literal dependency inputs were rewritten")
	}
}

// Capture the production recipe, then execute it with real Docker from a
// context containing only its generated files. No application include can be
// opened there. Real pip must honor the surviving hashes, markers and separate
// constraints; negative controls modify only canonical bytes and must fail.
func TestPythonDependencyRecipeReadsOnlyCanonicalFiles(t *testing.T) {
	writeFixture := func(t *testing.T, root, hash string) {
		t.Helper()
		pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("\xef\xbb\xbf# canonical-only recipe %d\r\n-r deps/application.txt\r\n-c deps/constraints.txt\r\n", time.Now().UnixNano()))
		pyDepsWrite(t, root, "deps/application.txt", "# accepted requirement and a continued hash\npackaging==24.2 ; python_version >= '3.0' \\\n    --hash="+hash+"\n"+
			"invariant-canonical-marker-never==0 ; python_version < '0' \\\n    --hash=sha256:"+strings.Repeat("a", 64)+"\n")
		// These conflicting constraints must stay inert: they are not
		// requirements, and no installed distribution needs idna.
		pyDepsWrite(t, root, "deps/constraints.txt", "# constraint-only input\npackaging==24.2\nidna==3.9\nidna==3.10\n")
	}
	inputs := []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"}
	capture := func(t *testing.T, root string) (map[string]string, *toolchain.PythonDependencies) {
		t.Helper()
		pyDepsFakeDocker(t)
		env := pyDepsBuild(t, root)
		pyDepsAssertRecipeEnvironment(t, root, env, inputs)
		pyDepsAssertCanonicalStaging(t, root, env, inputs)
		return pyDepsFiles(t, filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "context")), env
	}
	t.Run("generated recipe contract", func(t *testing.T) {
		root := pyDepsFixture(t)
		writeFixture(t, root, "sha256:"+strings.Repeat("a", 64))
		before := pyDepsFiles(t, root)
		capture(t, root)
		if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
			t.Fatal("canonicalization rewrote the application's dependency files")
		}
	})
	if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") != "1" {
		return
	}
	t.Run("execute generated canonical-only recipe", func(t *testing.T) {
		pyDepsRequireRealDocker(t)
		root := pyDepsFixture(t)
		pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("# real hash oracle %d\n-r deps/application.txt\n", time.Now().UnixNano()))
		oracle := pyDepsBuild(t, root)
		pyDepsCleanupRecipeImage(t, oracle.Image)
		pyDepsAssertRecipeEnvironment(t, root, oracle, inputs)
		// The independent hash comes from a real installation report, never
		// from the Docker double or a guessed package version/digest table.
		hash := oracle.Artifacts[0].SHA256
		writeFixture(t, root, hash)
		before := pyDepsFiles(t, root)
		var staged map[string]string
		var captured *toolchain.PythonDependencies
		t.Run("capture exact production recipe", func(t *testing.T) {
			staged, captured = capture(t, root)
		})
		if staged == nil || captured == nil {
			t.Fatal("no canonical recipe was captured")
		}
		// Also execute production's normal build path, not just a test-owned
		// Docker invocation, and retain its receipt and offline checks.
		env := pyDepsBuild(t, root)
		pyDepsCleanupRecipeImage(t, env.Image)
		pyDepsAssertRecipeEnvironment(t, root, env, inputs)
		if !reflect.DeepEqual(env.CanonicalInputs, captured.CanonicalInputs) || !reflect.DeepEqual(env.Artifacts, oracle.Artifacts) {
			t.Fatalf("production build changed canonical bytes or installed artifacts: captured=%#v built=%#v oracle=%#v", captured, env, oracle)
		}
		pyDepsRunChecks(t, root)
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
		defer cancel()
		build := func(t *testing.T, change func(string), failure string) string {
			t.Helper()
			contextDir := t.TempDir()
			for filename, body := range staged {
				pyDepsWrite(t, contextDir, filename, body)
			}
			if change != nil {
				change(contextDir)
			}
			iidfile := filepath.Join(t.TempDir(), "image-id")
			out, err := exec.CommandContext(ctx, "docker", "build", "--no-cache", "--platform", "linux/amd64", "--iidfile", iidfile, contextDir).CombinedOutput()
			if failure != "" {
				if err == nil || !strings.Contains(strings.ToLower(string(out)), failure) {
					t.Fatalf("changing only canonical %s did not fail installation as expected: error=%v\n%s", failure, err, out)
				}
				return ""
			}
			if err != nil {
				t.Fatalf("unmodified generated recipe could not install using only canonical files: %v\n%s", err, out)
			}
			id, err := os.ReadFile(iidfile)
			image := strings.TrimSpace(string(id))
			if err != nil || !pyDepsDigest.MatchString(image) {
				t.Fatalf("replayed recipe did not produce an immutable image: id=%q error=%v", image, err)
			}
			pyDepsCleanupRecipeImage(t, image)
			return image
		}
		t.Run("canonical files alone install", func(t *testing.T) {
			image := build(t, nil, "")
			reportPath := pyDepsRecipeReportPath(t, staged["Dockerfile"])
			out, err := exec.CommandContext(ctx, "docker", "run", "--rm", "--network", "none", "--platform", "linux/amd64", "--read-only", image, "/bin/cat", reportPath).CombinedOutput()
			if err != nil {
				t.Fatalf("read actual replayed installation report: %v\n%s", err, out)
			}
			var report struct {
				Install []struct {
					Metadata     struct{ Name, Version string }
					DownloadInfo struct {
						URL         string
						ArchiveInfo struct{ Hashes map[string]string } `json:"archive_info"`
					} `json:"download_info"`
				}
			}
			if err := json.Unmarshal(out, &report); err != nil || len(report.Install) != 1 {
				t.Fatalf("false markers or constraint-only entries became installed requirements: error=%v report=%s", err, out)
			}
			installed := report.Install[0]
			if installed.Metadata.Name != "packaging" || installed.Metadata.Version != "24.2" || "sha256:"+installed.DownloadInfo.ArchiveInfo.Hashes["sha256"] != hash || !strings.HasSuffix(installed.DownloadInfo.URL, "/packaging-24.2-py3-none-any.whl") {
				t.Fatalf("canonical recipe installed a different artifact: %s", out)
			}
			libraryTarget := pyDepsRecipeLibraryTarget(t, staged["Dockerfile"])
			const imports = `import importlib.util, os, site, sys
target = os.path.realpath(sys.argv[1])
startup_paths = [os.path.realpath(p) for p in sys.path + site.getsitepackages() + [site.getusersitepackages()]]
assert target not in startup_paths, (target, startup_paths)
assert importlib.util.find_spec('packaging') is None
sys.path.insert(0, target)
import packaging
assert packaging.__version__ == '24.2'
assert os.path.realpath(packaging.__file__).startswith(target + os.sep)
assert importlib.util.find_spec('idna') is None
`
			out, err = exec.CommandContext(ctx, "docker", "run", "--rm", "--network", "none", "--platform", "linux/amd64", "--read-only", "-w", "/tmp", image, "/usr/local/bin/python", "-I", "-c", imports, libraryTarget).CombinedOutput()
			if err != nil {
				t.Fatalf("canonical-only image failed offline imports: %v\n%s", err, out)
			}
		})
		t.Run("canonical hashes are enforced", func(t *testing.T) {
			build(t, func(dir string) {
				pyDepsWrite(t, dir, "canonical/requirements.txt", strings.ReplaceAll(staged["canonical/requirements.txt"], hash, "sha256:"+strings.Repeat("0", 64)))
			}, "hashes")
		})
		t.Run("canonical constraints are enforced", func(t *testing.T) {
			build(t, func(dir string) {
				pyDepsWrite(t, dir, "canonical/constraints.txt", staged["canonical/constraints.txt"]+"packaging==24.1\n")
			}, "conflict")
		})
		if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
			t.Fatal("real canonical recipe build or execution rewrote original inputs")
		}
	})
}

func pyDepsAssertRecipeEnvironment(t *testing.T, root string, env *toolchain.PythonDependencies, inputs []string) {
	t.Helper()
	recipe, err := toolchain.PythonDepsRecipe(root)
	if err != nil || recipe != env.Recipe || env.Base != toolchain.PythonImage || env.Platform != "linux/amd64" {
		t.Fatalf("wrong recipe provenance: %#v; recipe error=%v", env, err)
	}
	want := map[string]string{}
	for _, filename := range inputs {
		body, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(filename)))
		if err != nil {
			t.Fatal(err)
		}
		want[filename] = pyDepsHash(body)
	}
	got := map[string]string{}
	var ordered []string
	for _, input := range env.Inputs {
		got[input.Path] = input.SHA256
		ordered = append(ordered, input.Path)
	}
	if !reflect.DeepEqual(got, want) || len(env.Inputs) != len(inputs) || !sort.StringsAreSorted(ordered) {
		t.Fatalf("receipt must hash every literal input exactly once, in path order: got=%#v want=%#v", env.Inputs, want)
	}
	if len(env.Artifacts) != 1 {
		t.Fatalf("false markers or inert constraints became installed dependencies: %#v", env.Artifacts)
	}
	a := env.Artifacts[0]
	if a.Name != "packaging" || a.Version != "24.2" || a.Filename != "packaging-24.2-py3-none-any.whl" || !pyDepsDigest.MatchString(a.SHA256) {
		t.Fatalf("recipe installed a different environment: %#v", a)
	}
}

// Application paths are evidence, host validation and read-only parser inputs. The
// network-enabled installer gets exactly these two generated UTF-8/LF files.
// Return their bytes for semantic assertions without coupling tests to the
// production parser or reproducing its normalization algorithm.
func pyDepsAssertCanonicalStaging(t *testing.T, root string, env *toolchain.PythonDependencies, inputs []string) map[string]string {
	t.Helper()
	staged := pyDepsFiles(t, filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "context"))
	want := map[string]string{}
	for _, filename := range inputs {
		body, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(filename)))
		if err != nil {
			t.Fatal(err)
		}
		want[filename] = pyDepsHash(body)
	}
	gotInputs := map[string]string{}
	for _, input := range env.Inputs {
		gotInputs[input.Path] = input.SHA256
	}
	if !reflect.DeepEqual(gotInputs, want) || len(env.Inputs) != len(want) {
		t.Fatalf("canonicalization lost original input evidence: got=%#v want=%#v", env.Inputs, want)
	}
	canonical := map[string]string{}
	for filename, body := range staged {
		switch filename {
		case "canonical/requirements.txt", "canonical/constraints.txt":
			name := strings.TrimPrefix(filename, "canonical/")
			canonical[name] = body
			if !utf8.ValidString(body) || strings.ContainsAny(body, "\\#\r\v\f\u001c\u001d\u001e\u0085\u2028\u2029\ufeff") || (body != "" && !strings.HasSuffix(body, "\n")) {
				t.Errorf("canonical file %s contains invalid UTF-8, comments, continuations, a BOM or non-LF endings: %q", filename, body)
			}
			for _, line := range strings.Split(strings.TrimSuffix(body, "\n"), "\n") {
				if line == "" && body == "" {
					continue
				}
				if !regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*`).MatchString(line) || strings.TrimSpace(line) != line {
					t.Errorf("canonical file %s must contain one accepted requirement per line, without includes or option lines: %q", filename, line)
				}
				for _, token := range strings.Fields(line) {
					if strings.HasPrefix(token, "-") && !regexp.MustCompile(`^--hash=sha256:[0-9a-f]{64}$`).MatchString(token) {
						t.Errorf("canonical file %s contains an option other than an accepted SHA-256 hash: %q", filename, line)
					}
				}
			}
		case "Dockerfile", ".dockerignore":
		default:
			t.Errorf("build context exposes an original input or unrelated file to pip: %s", filename)
		}
	}
	if len(canonical) != 2 {
		t.Fatalf("build context must contain exactly canonical/requirements.txt and canonical/constraints.txt: %#v", staged)
	}
	if len(env.CanonicalInputs) != 2 {
		t.Fatalf("receipt must identify both canonical files: %#v", env.CanonicalInputs)
	}
	for i, name := range []string{"constraints.txt", "requirements.txt"} {
		input := env.CanonicalInputs[i]
		if input.Path != name || input.SHA256 != pyDepsHash([]byte(canonical[name])) {
			t.Errorf("canonical evidence must hash staged bytes in path order: got=%#v want path=%s hash=%s", input, name, pyDepsHash([]byte(canonical[name])))
		}
	}
	pyDepsAssertIsolatedRecipe(t, staged["Dockerfile"])
	pyDepsAssertPipParserMatches(t, root, canonical)
	return canonical
}

// The generated recipe uses a small, auditable form: one stage, one literal
// directory COPY, absolute WORKDIR and direct Python commands (shell or exec
// form). Reject indirect shell scripts/eval rather than pretending a regex
// proves that an arbitrary shell program always invokes isolated Python.
func pyDepsAssertIsolatedRecipe(t *testing.T, recipe string) {
	t.Helper()
	python := regexp.MustCompile(`^python(?:[0-9]+(?:\.[0-9]+)*)?$`)
	pip := regexp.MustCompile(`^pip(?:[0-9]+(?:\.[0-9]+)*)?$`)
	recipe = strings.ReplaceAll(strings.ReplaceAll(recipe, "\\\r\n", " "), "\\\n", " ")
	workdir, inputdir := "", ""
	copies, stages := 0, 0
	pipSeen, requirementsSeen, constraintsSeen := false, false, false
	for _, line := range strings.Split(recipe, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		words := strings.Fields(line)
		instruction := strings.ToUpper(words[0])
		body := strings.TrimSpace(line[len(words[0]):])
		switch instruction {
		case "FROM":
			stages++
			args := pyDepsRecipeArguments(t, body)
			if len(args) > 0 && args[0] == "--platform=linux/amd64" {
				args = args[1:]
			} else if len(args) > 1 && args[0] == "--platform" && args[1] == "linux/amd64" {
				args = args[2:]
			}
			if (len(args) != 1 && !(len(args) == 3 && strings.EqualFold(args[1], "AS"))) || args[0] != toolchain.PythonImage {
				t.Fatalf("recipe must build from the existing digest-pinned Python base: %s", line)
			}
		case "ADD":
			t.Fatal("recipe must copy the dedicated canonical directory literally, without ADD")
		case "COPY":
			args := pyDepsRecipeArguments(t, body)
			if len(args) != 2 || (args[0] != "canonical/" && args[0] != "./canonical/") || !path.IsAbs(args[1]) || strings.ContainsAny(args[1], "$*?[]") {
				t.Fatalf("COPY must use one literal canonical/ directory and an absolute destination: %s", line)
			}
			inputdir = path.Clean(args[1])
			copies++
		case "WORKDIR":
			args := pyDepsRecipeArguments(t, body)
			if len(args) != 1 || !path.IsAbs(args[0]) || strings.ContainsAny(args[0], "$*?[]") {
				t.Fatalf("recipe needs an explicit absolute clean WORKDIR: %s", line)
			}
			workdir = path.Clean(args[0])
		case "RUN":
			if workdir == "" || inputdir == "" || workdir == inputdir || strings.HasPrefix(workdir, inputdir+"/") {
				t.Fatalf("RUN must execute outside the dependency-input directory: workdir=%q inputs=%q line=%s", workdir, inputdir, line)
			}
			args := pyDepsRecipeArguments(t, body)
			pipCommand := false
			for i, arg := range args {
				if strings.Contains(";&|()", arg) {
					pipCommand = false
				}
				if pip.MatchString(path.Base(arg)) && i > 0 && args[i-1] == "-m" {
					pipCommand = true
				}
				// Every requirements/constraints argument must name a generated
				// canonical file. No application paths survive into pip commands.
				option, value := "", ""
				if pipCommand {
					for _, flag := range []string{"--requirement", "--constraint", "-r", "-c"} {
						if arg == flag && i+1 < len(args) {
							option, value = flag, args[i+1]
						} else if strings.HasPrefix(arg, flag+"=") {
							option, value = flag, strings.TrimPrefix(arg, flag+"=")
						} else if len(flag) == 2 && strings.HasPrefix(arg, flag) && len(arg) > 2 {
							option, value = flag, arg[2:]
						}
					}
				}
				if option != "" {
					name := "requirements.txt"
					if option == "-c" || option == "--constraint" {
						name = "constraints.txt"
					}
					if value != path.Join(inputdir, name) {
						t.Fatalf("installer must read only generated canonical files: %s", line)
					}
					requirementsSeen = requirementsSeen || name == "requirements.txt"
					constraintsSeen = constraintsSeen || name == "constraints.txt"
				}
				base := path.Base(arg)
				switch base {
				case "cd", "eval", "exec", "sh", "bash", "ash", "source", ".":
					t.Fatalf("keep build commands direct and their clean cwd auditable: %s", line)
				}
				if pip.MatchString(base) {
					// A module argument is safe; a pip console entry point does
					// not establish the required isolated Python interpreter.
					if i == 0 || args[i-1] != "-m" {
						t.Fatalf("pip must run through isolated Python: %s", line)
					}
				}
				commandPosition := i == 0 || strings.Contains(";&|()", args[i-1])
				if !commandPosition || !python.MatchString(base) {
					continue
				}
				if arg != "/usr/local/bin/python" {
					t.Fatalf("build Python must be the pinned base interpreter by its absolute path: %s", line)
				}
				isolated := false
				for j := i + 1; j < len(args); j++ {
					if args[j] == "-I" {
						isolated = true
					}
					if args[j] == "-m" && j+1 < len(args) {
						pipSeen = pipSeen || args[j+1] == "pip"
						break
					}
					if args[j] == "-c" || !strings.HasPrefix(args[j], "-") {
						break
					}
				}
				if !isolated {
					t.Fatalf("every build-side Python invocation must use -I: %s", line)
				}
			}
		}
	}
	if stages != 1 || copies != 1 || !pipSeen || !requirementsSeen || !constraintsSeen {
		t.Fatalf("expected one stage, literal canonical COPY, isolated base Python/pip and both canonical files: stages=%d copies=%d pip=%t requirements=%t constraints=%t\n%s", stages, copies, pipSeen, requirementsSeen, constraintsSeen, recipe)
	}
	libraryTarget := pyDepsRecipeLibraryTarget(t, recipe)
	if libraryTarget == inputdir || strings.HasPrefix(libraryTarget, inputdir+"/") || strings.HasPrefix(inputdir, libraryTarget+"/") {
		t.Fatalf("installed libraries must be separate from canonical input files: target=%s inputs=%s", libraryTarget, inputdir)
	}
}

// Discover the recipe's import-only library directory without coupling the
// acceptance harness to its spelling. Every pip install must use the same
// literal --target; inherited site directories and the base runtime stay
// outside dependency control. The real probe also checks startup sys.path.
func pyDepsRecipeLibraryTarget(t *testing.T, recipe string) string {
	t.Helper()
	recipe = strings.ReplaceAll(strings.ReplaceAll(recipe, "\\\r\n", " "), "\\\n", " ")
	target := ""
	for _, line := range strings.Split(recipe, "\n") {
		line = strings.TrimSpace(line)
		word, body, _ := strings.Cut(line, " ")
		if !strings.EqualFold(word, "RUN") {
			continue
		}
		args := pyDepsRecipeArguments(t, strings.TrimSpace(body))
		for i := 0; i+1 < len(args); i++ {
			if args[i] != "-m" || args[i+1] != "pip" {
				continue
			}
			install, value, targets := false, "", 0
			for j := i + 2; j < len(args); j++ {
				arg := args[j]
				if strings.Contains(";&|()", arg) {
					break
				}
				install = install || arg == "install"
				switch {
				case arg == "--target" || arg == "-t":
					targets++
					if j+1 < len(args) {
						j++
						value = args[j]
					}
				case strings.HasPrefix(arg, "--target="):
					targets++
					value = strings.TrimPrefix(arg, "--target=")
				case strings.HasPrefix(arg, "-t") && len(arg) > 2:
					targets++
					value = arg[2:]
				}
			}
			if !install {
				continue
			}
			if targets != 1 || !path.IsAbs(value) || value != path.Clean(value) || strings.ContainsAny(value, "$*?[]") {
				t.Fatalf("each pip installation needs one literal absolute non-site --target: %s", line)
			}
			if target != "" && target != value {
				t.Fatalf("pip installs into inconsistent library targets: %q and %q", target, value)
			}
			target = value
		}
	}
	if target == "" {
		t.Fatalf("generated recipe has no import-only pip --target installation: %s", recipe)
	}
	for _, dir := range []string{"/bin", "/sbin", "/usr/bin", "/usr/sbin", "/usr/local/bin", "/lib", "/lib64", "/usr/lib", "/usr/local/lib"} {
		if target == "/" || target == dir || strings.HasPrefix(target, dir+"/") || strings.HasPrefix(dir, target+"/") {
			t.Fatalf("dependency target can overwrite the base interpreter, commands or startup libraries: %s", target)
		}
	}
	for _, part := range strings.Split(target, "/") {
		if part == "site-packages" || part == "dist-packages" {
			t.Fatalf("dependency target must not be a site directory: %s", target)
		}
	}
	report := path.Clean(pyDepsRecipeReportPath(t, recipe))
	if report == target || strings.HasPrefix(report, target+"/") {
		t.Fatalf("saved installation evidence must stay outside the dependency target: report=%s target=%s", report, target)
	}
	return target
}

// Tokenize the generated recipe's literal shell commands without executing
// anything. Quoted -c code remains one argument; command separators do not
// hide a second interpreter. Exec-form instructions use JSON directly.
func pyDepsRecipeArguments(t *testing.T, body string) []string {
	t.Helper()
	if strings.HasPrefix(body, "[") {
		var args []string
		if err := json.Unmarshal([]byte(body), &args); err != nil {
			t.Fatalf("invalid exec-form recipe instruction %q: %v", body, err)
		}
		return args
	}
	var args []string
	var token strings.Builder
	var quote rune
	escaped := false
	flush := func() {
		if token.Len() != 0 {
			args = append(args, token.String())
			token.Reset()
		}
	}
	for _, r := range body {
		switch {
		case escaped:
			token.WriteRune(r)
			escaped = false
		case r == '\\' && quote != '\'':
			escaped = true
		case quote != 0:
			if r == quote {
				quote = 0
			} else {
				token.WriteRune(r)
			}
		case r == '\'' || r == '"':
			quote = r
		case unicode.IsSpace(r):
			flush()
		case strings.ContainsRune(";&|()", r):
			flush()
			args = append(args, string(r))
		case r == '`' || r == '$':
			t.Fatalf("generated recipe must use literal, directly auditable commands: %s", body)
		default:
			token.WriteRune(r)
		}
	}
	if quote != 0 || escaped {
		t.Fatalf("unterminated quote or escape in recipe: %s", body)
	}
	flush()
	return args
}

func pyDepsRequireRealDocker(t *testing.T) {
	t.Helper()
	if os.Getenv("INVARIANT_PY_DEPS_FAKE") != "" {
		t.Fatal("real recipe acceptance cannot use the Docker double")
	}
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	if out, err := exec.CommandContext(ctx, "docker", "info").CombinedOutput(); err != nil {
		t.Fatalf("requested real recipe acceptance requires Docker: %v\n%s", err, out)
	}
}

func pyDepsCleanupRecipeImage(t *testing.T, image string) {
	t.Helper()
	t.Cleanup(func() {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		exec.CommandContext(ctx, "docker", "image", "rm", image).Run()
	})
}

sources.internal/verify/python_semantics_accept_:
package verify

import (
	"reflect"
	"strings"
	"testing"
)

// #253: pip removes a single trailing continuation without inserting or
// removing any other character. In particular, inserting a space inside
// 'posix' silently changes whether the dependency is installed. These are
// parser fixtures: synthetic hashes are checked offline by the real parser
// oracle, while the Docker double captures production's canonical bytes.
func TestPythonDependenciesJoinContinuationsWithoutInsertedCharacters(t *testing.T) {
	firstHash, secondHash := strings.Repeat("a", 32), strings.Repeat("b", 32)
	for _, tc := range []struct {
		name string
		raw  string
		want []string
	}{
		{
			name: "review marker literal",
			raw:  "packaging; os_name == 'po\\\nsix'\n",
			want: []string{"packaging; os_name == 'posix'"},
		},
		{
			name: "requirement version hash and marker fragments",
			raw: "req\\\nuests==2.32.3\n" +
				"idna==3.\\\n10\n" +
				"typing-extensions==4.12.2 --hash=sha256:" + firstHash + "\\\n" + secondHash + "\n" +
				"urllib3>\\\n=2,<3\n" +
				"charset-normalizer; python_ver\\\nsion >= '3.0'\n" +
				"six; os_name == 'po \\\nsix'\n" +
				"certifi; os_name == 'po\\\n six'\n",
			want: []string{
				"requests==2.32.3",
				"idna==3.10",
				"typing-extensions==4.12.2 --hash=sha256:" + firstHash + secondHash,
				"urllib3>=2,<3",
				"charset-normalizer; python_version >= '3.0'",
				"six; os_name == 'po six'",
				"certifi; os_name == 'po six'",
			},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			pyDepsAssertAcceptedSemanticInput(t, tc.raw, tc.want)
		})
	}
}

// #253: coding: and coding= are declarations only within comments. Names
// ending in coding and marker values containing that text remain ordinary
// requirement syntax. Declarations in comments remain forbidden at every
// position, including after an otherwise accepted package-name regression.
func TestPythonDependenciesAcceptCodingPackageNames(t *testing.T) {
	t.Run("package names and marker text", func(t *testing.T) {
		pyDepsAssertAcceptedSemanticInput(t,
			"geocoding==1.0\n"+
				"coding==2.0\n"+
				"decoding==3.0\n"+
				"fileencoding==4.0 # ordinary package comment\n"+
				"transcoding; os_name == 'coding:utf-8'\n"+
				"encoding-tools; os_name == 'coding=utf-8'\n",
			[]string{
				"geocoding==1.0",
				"coding==2.0",
				"decoding==3.0",
				"fileencoding==4.0",
				"transcoding; os_name == 'coding:utf-8'",
				"encoding-tools; os_name == 'coding=utf-8'",
			})
	})
	t.Run("comment declarations remain rejected anywhere", func(t *testing.T) {
		pyDepsRejectInvalidInputs(t, []pyDepsInvalidInputCase{
			{"after accepted package", "geocoding==1.0\n# coding: utf-8\n"},
			{"late after accepted packages", "geocoding==1.0\ndecoding==2.0\n\n# coding=utf-8\n"},
			{"trailing accepted package", "geocoding==1.0 # coding: utf-8\n"},
			{"indented comment", "geocoding==1.0\n\t  # -*- coding: utf-8 -*-\n"},
			{"CRLF late comment", "geocoding==1.0\r\n# ordinary\r\n# coding=utf-8\r\n"},
			{"BOM late comment", "\xef\xbb\xbfgeocoding==1.0\n# ordinary\n# coding: utf-8\n"},
		})
	})
}

// Every accepted shape is exercised in each effective-file role and supported
// byte encoding. The expected logical lines are written independently of the
// production parser. Both receipt representations are checked against their
// actual bytes, and rebuilding must reuse the same environment evidence.
func pyDepsAssertAcceptedSemanticInput(t *testing.T, raw string, want []string) {
	t.Helper()
	inputs := []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt"}
	for _, filename := range inputs {
		t.Run(filename, func(t *testing.T) {
			var firstCanonical map[string]string
			for _, encoding := range []struct {
				name    string
				bom     string
				newline string
			}{
				{"LF", "", "\n"},
				{"CRLF", "", "\r\n"},
				{"BOM LF", "\xef\xbb\xbf", "\n"},
				{"BOM CRLF", "\xef\xbb\xbf", "\r\n"},
			} {
				t.Run(encoding.name, func(t *testing.T) {
					pyDepsFakeDocker(t)
					root := pyDepsFixture(t)
					files := pyDepsFiles(t, root)
					// Put the regression first, including on line one for the
					// package-name case. Existing includes preserve the closure.
					body := raw + files[filename]
					pyDepsWrite(t, root, filename, encoding.bom+strings.ReplaceAll(body, "\n", encoding.newline))
					before := pyDepsFiles(t, root)
					env := pyDepsBuild(t, root)
					pyDepsAssertRecipeEnvironment(t, root, env, inputs)
					canonical := pyDepsAssertCanonicalStaging(t, root, env, inputs)
					wantRequirements := []string{"packaging>=24,<25"}
					wantConstraints := []string{"packaging==24.2"}
					if filename == "deps/constraints.txt" {
						wantConstraints = append(wantConstraints, want...)
					} else {
						wantRequirements = append(wantRequirements, want...)
					}
					pyDepsAssertCanonicalLines(t, canonical["requirements.txt"], wantRequirements)
					pyDepsAssertCanonicalLines(t, canonical["constraints.txt"], wantConstraints)
					if firstCanonical == nil {
						firstCanonical = canonical
					} else if !reflect.DeepEqual(canonical, firstCanonical) {
						t.Fatalf("BOM or newline style changed accepted semantics: got=%#v want=%#v", canonical, firstCanonical)
					}
					if again := pyDepsBuild(t, root); !reflect.DeepEqual(again, env) || pyDepsBuildCount(t) != 1 {
						t.Fatalf("accepted semantics did not reuse exact evidence: first=%#v again=%#v", env, again)
					}
					if !reflect.DeepEqual(before, pyDepsFiles(t, root)) {
						t.Fatal("accepting requirement syntax rewrote application inputs")
					}
				})
			}
		})
	}
}

sources.internal/verify/python_traversal_accept_:
package verify

import (
	"context"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"reflect"
	"testing"
	"time"

	"github.com/gitdek/invariant/internal/toolchain"
)

// References pass host validation and pip parses them in a read-only mount.
// Opening deps/../constraints.txt requires the empty deps/ directory, but only
// canonical requirements and constraints reach the Docker installation context.
// Installation must succeed without any original traversed directories there.
//
// INVARIANT_PYTHON_DEPS_REAL=1 go test ./internal/verify -run '^TestPythonDependencyRecipeResolvesTraversedDirectories$' -count=1 -timeout 20m
func TestPythonDependencyRecipeResolvesTraversedDirectories(t *testing.T) {
	for _, option := range []string{"-r", "-c"} {
		t.Run(option, func(t *testing.T) {
			root := pyDepsFixture(t)
			// The exact reported regression occurs in deps/refs/entry.txt,
			// whose sibling deps/ directory is empty and has no input file.
			rootReference := "root-hop/child/../../deps/application.txt"
			rootBody := "-r " + rootReference + "\n"
			applicationBody := "-r refs/entry.txt\n"
			nestedBody := "packaging>=24,<25\n-c ../constraints.txt\n"
			rootTarget := "deps/application.txt"
			if option == "-c" {
				rootReference = "root-hop/child/../../deps/constraints.txt"
				rootBody = "-r deps/application.txt\n-c " + rootReference + "\n"
				applicationBody = "packaging>=24,<25\n-c refs/entry.txt\n"
				nestedBody = "-c ../constraints.txt\n"
				rootTarget = "deps/constraints.txt"
			}
			pyDepsWrite(t, root, "requirements.txt", fmt.Sprintf("# traversed-directory recipe %s %d\n%s", option, time.Now().UnixNano(), rootBody))
			pyDepsWrite(t, root, "deps/application.txt", applicationBody)
			pyDepsWrite(t, root, "deps/refs/entry.txt", option+" deps/../constraints.txt\n")
			pyDepsWrite(t, root, "deps/refs/constraints.txt", nestedBody)
			traversed := []string{"root-hop", "root-hop/child", "deps/refs/deps"}
			for _, dir := range traversed {
				if err := os.MkdirAll(filepath.Join(root, filepath.FromSlash(dir)), 0o755); err != nil {
					t.Fatal(err)
				}
			}
			for _, dir := range []string{"root-hop/child", "deps/refs/deps"} {
				entries, err := os.ReadDir(filepath.Join(root, filepath.FromSlash(dir)))
				if err != nil || len(entries) != 0 {
					t.Fatalf("fixture traversal directory %s must be empty: %v %v", dir, entries, err)
				}
			}
			inputs := []string{"requirements.txt", "deps/application.txt", "deps/constraints.txt", "deps/refs/entry.txt", "deps/refs/constraints.txt"}
			before := pyDepsFiles(t, root)
			beforeDirs := pyDepsTraversalDirectories(t, root)
			// These opens intentionally preserve .. so the fixture itself
			// proves that every reference is valid before staging.
			pyDepsAssertTraversalOpen(t, root, "requirements.txt", rootReference, rootTarget)
			pyDepsAssertTraversalOpen(t, root, "deps/refs/entry.txt", "deps/../constraints.txt", "deps/refs/constraints.txt")
			t.Run("generated recipe contract", func(t *testing.T) {
				pyDepsFakeDocker(t)
				env := pyDepsBuild(t, root)
				pyDepsAssertRecipeEnvironment(t, root, env, inputs)
				pyDepsAssertCanonicalStaging(t, root, env, inputs)
				staged := filepath.Join(os.Getenv("INVARIANT_PY_DEPS_FAKE"), "context")
				if got := pyDepsTraversalDirectories(t, staged); !reflect.DeepEqual(got, []string{".", "canonical"}) {
					t.Fatalf("original traversal directories reached the installation context: %#v", got)
				}
				if again := pyDepsBuild(t, root); !reflect.DeepEqual(again, env) || pyDepsBuildCount(t) != 1 {
					t.Fatalf("host-resolved traversal inputs did not reuse their recorded environment: first=%#v again=%#v", env, again)
				}
			})
			if os.Getenv("INVARIANT_PYTHON_DEPS_REAL") == "1" {
				t.Run("execute generated recipe", func(t *testing.T) {
					pyDepsRequireRealDocker(t)
					env := pyDepsBuild(t, root)
					pyDepsCleanupRecipeImage(t, env.Image)
					pyDepsAssertRecipeEnvironment(t, root, env, inputs)
					pyDepsRunChecks(t, root)
				})
			}
			if !reflect.DeepEqual(before, pyDepsFiles(t, root)) || !reflect.DeepEqual(beforeDirs, pyDepsTraversalDirectories(t, root)) {
				t.Fatal("building or executing a traversal recipe rewrote application inputs or directories")
			}
		})
	}
}

// Canonical containment alone cannot establish that host reads are safe: lexical
// path components discarded by .. must also stay inside the project and must
// not be symlinks. Every fixture below can actually be opened as written and
// resolves to the existing pinned constraint, so a missing target cannot make
// an otherwise unsafe resolver pass this test.
func TestPythonDependenciesRejectUnsafeTraversal(t *testing.T) {
	pyDepsFakeDocker(t)
	for _, kind := range []string{"canceled symlink", "outside and back"} {
		for _, option := range []string{"-r", "-c"} {
			for _, containing := range []string{"requirements.txt", "deps/application.txt"} {
				t.Run(kind+"/"+option+"/"+containing, func(t *testing.T) {
					root := pyDepsFixture(t)
					base := filepath.Dir(filepath.Join(root, filepath.FromSlash(containing)))
					var reference string
					if kind == "canceled symlink" {
						if err := os.Mkdir(filepath.Join(base, "ordinary"), 0o755); err != nil {
							t.Fatal(err)
						}
						if err := os.Symlink("ordinary", filepath.Join(base, "linked")); err != nil {
							t.Fatal(err)
						}
						reference = "linked/../deps/constraints.txt"
						if containing != "requirements.txt" {
							reference = "linked/../constraints.txt"
						}
					} else {
						reference = "../" + filepath.Base(root) + "/deps/constraints.txt"
						if containing != "requirements.txt" {
							reference = "../" + reference
						}
					}
					body := option + " " + reference + "\n"
					pyDepsWrite(t, root, containing, body)
					pyDepsAssertTraversalOpen(t, root, containing, reference, "deps/constraints.txt")
					if recipe, err := toolchain.PythonDepsRecipe(root); err == nil {
						t.Errorf("accepted unsafe intermediate directory in %s: reference=%q recipe=%q", containing, reference, recipe)
					}
					if env, err := toolchain.PythonDepsImage(context.Background(), root); err == nil || env != nil {
						t.Errorf("unsafe traversal reached image selection: reference=%q env=%#v error=%v", reference, env, err)
					}
					if got, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(containing))); err != nil || string(got) != body {
						t.Errorf("rejecting unsafe traversal rewrote its input: error=%v got=%q want=%q", err, got, body)
					}
				})
			}
		}
	}
	if calls := pyDepsCalls(t); len(calls) != 0 {
		t.Fatalf("unsafe traversals must fail before Docker runs: %#v", calls)
	}
}

func pyDepsAssertTraversalOpen(t *testing.T, root, containing, reference, target string) {
	t.Helper()
	// filepath.Join would clean away the very directories being tested.
	literal := filepath.Dir(filepath.Join(root, filepath.FromSlash(containing))) + string(os.PathSeparator) + filepath.FromSlash(reference)
	got, err := os.ReadFile(literal)
	if err != nil {
		t.Fatalf("cannot open reference %q from %s as written: %v", reference, containing, err)
	}
	want, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(target)))
	if err != nil || string(got) != string(want) {
		t.Fatalf("reference %q from %s did not read exact bytes of %s: error=%v got=%q want=%q", reference, containing, target, err, got, want)
	}
}

func pyDepsTraversalDirectories(t *testing.T, root string) []string {
	t.Helper()
	var dirs []string
	if err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			rel, err := filepath.Rel(root, path)
			if err != nil {
				return err
			}
			dirs = append(dirs, filepath.ToSlash(rel))
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	return dirs
}

sources.internal/verify/python_whitespace_accept:
package verify

import (
	"fmt"
	"strings"
	"testing"
)

// #258: pip splits requirement text from its options on ASCII spaces only.
// Treating a tab or Unicode whitespace as that boundary repairs an input pip
// rejects and changes its meaning when producing the canonical install files.
// Both dependency APIs must reject every case before even inspecting Docker,
// in the root, a referenced requirement and a referenced constraint, while
// leaving every application's input byte unchanged.
func TestPythonDependenciesRejectNonSpaceOptionWhitespace(t *testing.T) {
	pyDepsRejectInvalidInputs(t, pyDepsRejectedOptionWhitespaceFixtures())
}

// The real pinned-pip differential consumes this same rejected corpus. These
// are all Python str.isspace characters except ASCII space and characters
// handled by str.splitlines. The latter have separate separator regressions:
// a requirement, line break and standalone --hash need not be refused by pip.
// U+001F belongs here even though Go's unicode.IsSpace does not recognize it.
func pyDepsRejectedOptionWhitespaceFixtures() []pyDepsInvalidInputCase {
	hash := "--hash=sha256:" + strings.Repeat("a", 64)
	var cases []pyDepsInvalidInputCase
	for _, separator := range []struct {
		name string
		char rune
	}{
		{"tab", '\u0009'},
		{"unit separator", '\u001f'},
		{"no-break space", '\u00a0'},
		{"ogham space mark", '\u1680'},
		{"en quad", '\u2000'},
		{"em quad", '\u2001'},
		{"en space", '\u2002'},
		{"em space", '\u2003'},
		{"three-per-em space", '\u2004'},
		{"four-per-em space", '\u2005'},
		{"six-per-em space", '\u2006'},
		{"figure space", '\u2007'},
		{"punctuation space", '\u2008'},
		{"thin space", '\u2009'},
		{"hair space", '\u200a'},
		{"narrow no-break space", '\u202f'},
		{"medium mathematical space", '\u205f'},
		{"ideographic space", '\u3000'},
	} {
		cases = append(cases, pyDepsInvalidInputCase{
			name: fmt.Sprintf("U+%04X %s", separator.char, separator.name),
			raw:  "packaging==24.2" + string(separator.char) + hash + "\n",
		})
	}
	return append(cases,
		pyDepsInvalidInputCase{"ASCII space then tab", "packaging==24.2 \t" + hash + "\n"},
		pyDepsInvalidInputCase{"tab after continuation", "packaging==24.2\\\n\t" + hash + "\n"},
	)
}

// Keep the supported forms working while tightening the option boundary.
// Leading tabs are ordinary indentation; a tab attached to --hash is not an
// ASCII-space boundary. These accepted fixtures also reach the pinned parser
// oracle through the shared canonical-staging assertion when opted in.
func TestPythonDependenciesAcceptASCIIOptionSpaces(t *testing.T) {
	firstHash, secondHash := strings.Repeat("a", 64), strings.Repeat("b", 64)
	pyDepsAssertAcceptedSemanticInput(t,
		"\tpackaging==24.2 --hash=sha256:"+firstHash+"\n"+
			"idna==3.10    --hash=sha256:"+firstHash+"   --hash=sha256:"+secondHash+"\n"+
			"typing-extensions==4.12.2; python_version >= '3.0'  --hash=sha256:"+firstHash+"\n"+
			"requests==2.32.3\\\n    --hash=sha256:"+firstHash+"\n",
		[]string{
			"packaging==24.2 --hash=sha256:" + firstHash,
			"idna==3.10 --hash=sha256:" + firstHash + " --hash=sha256:" + secondHash,
			"typing-extensions==4.12.2; python_version >= '3.0' --hash=sha256:" + firstHash,
			"requests==2.32.3 --hash=sha256:" + firstHash,
		})
}
